module sequence_detector (
    input clk,
    input reset_n,
    input data_in,
    output reg sequence_detected
);


parameter IDLE = 3'b000;
parameter S1   = 3'b001;
parameter S2   = 3'b010;
parameter S3   = 3'b011;
parameter S4   = 3'b100;

reg [2:0] current_state, next_state;


always @(posedge clk or negedge reset_n) begin
    if (!reset_n) begin
        current_state <= IDLE;
    end else begin
        current_state <= next_state;
    end
end


always @(*) begin
    case (current_state)
        IDLE: begin
            next_state = data_in ? S1 : IDLE;
        end
        S1: begin
            next_state = data_in ? S1 : S2;
        end
        S2: begin
            next_state = data_in ? S1 : S3;
        end
        S3: begin
            next_state = data_in ? S4 : IDLE;
        end
        S4: begin
            next_state = IDLE;
        end
        default: next_state = IDLE;
    endcase
end


always @(*) begin
    sequence_detected = (current_state == S4);
end

endmodule

