module asyn_fifo #(
    parameter WIDTH = 8,
    parameter DEPTH = 16
)(
    input wire wclk,
    input wire rclk,
    input wire wrstn,
    input wire rrstn,
    input wire winc,
    input wire rinc,
    input wire [WIDTH-1:0] wdata,
    output wire wfull,
    output wire rempty,
    output wire [WIDTH-1:0] rdata
);


    dual_port_RAM #(
        .WIDTH(WIDTH),
        .DEPTH(DEPTH)
    ) ram (
        .wclk(wclk),
        .wenc(winc && !wfull),
        .waddr(waddr_bin[$clog2(DEPTH)-1:0]),
        .wdata(wdata),
        .rclk(rclk),
        .renc(rinc && !rempty),
        .raddr(raddr_bin[$clog2(DEPTH)-1:0]),
        .rdata(rdata)
    );


    reg [$clog2(DEPTH):0] waddr_bin;
    reg [$clog2(DEPTH):0] wgray;
    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn)
            waddr_bin <= 0;
        else if (winc && !wfull)
            waddr_bin <= waddr_bin + 1;
    end
    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn)
            wgray <= 0;
        else
            wgray <= waddr_bin ^ (waddr_bin >> 1);
    end


    reg [$clog2(DEPTH):0] raddr_bin;
    reg [$clog2(DEPTH):0] rgray;
    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn)
            raddr_bin <= 0;
        else if (rinc && !rempty)
            raddr_bin <= raddr_bin + 1;
    end
    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn)
            rgray <= 0;
        else
            rgray <= raddr_bin ^ (raddr_bin >> 1);
    end


    reg [$clog2(DEPTH):0] rgray_sync1, rgray_sync;
    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn) begin
            rgray_sync1 <= 0;
            rgray_sync <= 0;
        end else begin
            rgray_sync1 <= rgray;
            rgray_sync <= rgray_sync1;
        end
    end


    reg [$clog2(DEPTH):0] wgray_sync1, wgray_sync;
    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn) begin
            wgray_sync1 <= 0;
            wgray_sync <= 0;
        end else begin
            wgray_sync1 <= wgray;
            wgray_sync <= wgray_sync1;
        end
    end


    localparam ADDR_BITS = $clog2(DEPTH);
    localparam FULL_MASK = 3 << (ADDR_BITS-1);
    assign wfull = (wgray == (rgray_sync ^ FULL_MASK));
    assign rempty = (rgray == wgray_sync);

endmodule

module dual_port_RAM #(
    parameter WIDTH = 8,
    parameter DEPTH = 16
)(
    input wclk,
    input wenc,
    input [$clog2(DEPTH)-1:0] waddr,
    input [WIDTH-1:0] wdata,
    input rclk,
    input renc,
    input [$clog2(DEPTH)-1:0] raddr,
    output reg [WIDTH-1:0] rdata
);

    reg [WIDTH-1:0] RAM_MEM [0:DEPTH-1];

    always @(posedge wclk) begin
        if (wenc)
            RAM_MEM[waddr] <= wdata;
    end

    always @(posedge rclk) begin
        if (renc)
            rdata <= RAM_MEM[raddr];
    end

endmodule

