module LIFObuffer (
    input Clk,
    input Rst,
    input EN,
    input RW,
    input [3:0] dataIn,
    output EMPTY,
    output FULL,
    output reg [3:0] dataOut
);

reg [3:0] stack_mem [0:3];
reg [2:0] SP;



always @(posedge Clk) begin
    if (Rst) begin
        SP <= 3'b100;
        stack_mem[0] <= 0;
        stack_mem[1] <= 0;
        stack_mem[2] <= 0;
        stack_mem[3] <= 0;
    end else if (EN) begin
        if (RW) begin

            if (!EMPTY) begin
                dataOut <= stack_mem[SP];
                SP <= SP + 1;
            end
        end else begin

            if (!FULL) begin
                stack_mem[SP - 1] <= dataIn;
                SP <= SP - 1;
            end
        end
    end
end


assign EMPTY = (SP == 3'b100);
assign FULL = (SP == 3'b000);

endmodule

