module parallel2serial (
    input clk,
    input rst_n,
    input [3:0] d,
    output reg valid_out,
    output reg dout
);

reg [3:0] data;
reg [1:0] cnt;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        data <= 4'b0;
        cnt <= 2'b0;
        valid_out <= 1'b0;
        dout <= 1'b0;
    end else begin
        if (valid_out) begin
            if (cnt == 2'b11) begin
                valid_out <= 1'b0;
                cnt <= 2'b0;
                data <= d;
            end else begin
                cnt <= cnt + 1;
                data <= data << 1;
            end
            dout <= data[3];
        end else begin
            data <= d;
            valid_out <= 1'b1;
            cnt <= 2'b0;
        end
    end
end

endmodule

