module pulse_detect (
    input clk,
    input rst_n,
    input data_in,
    output reg data_out
);


localparam IDLE      = 2'b00;
localparam FIRST_RISE = 2'b01;
localparam SECOND_FALL = 2'b10;

reg [1:0] state, next_state;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        data_out <= 0;
    end else begin
        state <= next_state;

        case (state)
            IDLE: data_out <= 0;
            FIRST_RISE: data_out <= 0;
            SECOND_FALL: data_out <= 1;
            default: data_out <= 0;
        endcase
    end
end


always @(*) begin
    case (state)
        IDLE: begin
            if (data_in) 
                next_state = FIRST_RISE;
            else 
                next_state = IDLE;
        end
        FIRST_RISE: begin
            if (!data_in) 
                next_state = SECOND_FALL;
            else 
                next_state = IDLE;

        end
        SECOND_FALL: 
            next_state = IDLE;
        default: 
            next_state = IDLE;
    endcase
end

endmodule

