                end
                s1_red: begin
                    if (cnt == 0) begin
                        state <= s3_green;
                        green <= 1;
                        red <= 0;
                        cnt <= 8'h3F;

                    end else begin
                        cnt <= cnt - 1;
                    end
                end
                s3_green: begin
                    if (pass_request && cnt > 8'h0A) begin
                        cnt <= 8'h09;

                    end
                    if (cnt == 0) begin
                        state <= s2_yellow;
                        yellow <= 1;
                        green <= 0;
                        cnt <= 8'h04;

                    end else begin
                        cnt <= cnt - 1;
                    end
                end
                s2_yellow: begin
                    if (cnt == 0) begin
                        state <= s1_red;
                        red <= 1;
                        yellow <= 0;
                        cnt <= 8'h09;

                    end else begin
                        cnt <= cnt - 1;
                    end
                end
                default: state <= idle;
            endcase
        end
    end

    assign clock = cnt;

