module fixed_point_adder #(
    parameter Q = 4, 
    parameter N = 8  
) (
    input [N-1:0] a,
    input [N-1:0] b,
    output [N-1:0] c
);

reg res_sign;
reg [N-2:0] res_mag;


wire sign_a = a[N-1];
wire [N-2:0] mag_a = a[N-2:0];
wire sign_b = b[N-1];
wire [N-2:0] mag_b = b[N-2:0];

always @(*) begin
    if (sign_a == sign_b) begin

        wire [N-1:0] sum_mag = mag_a + mag_b;
        if (sum_mag >= (1 << (N-1))) begin
            res_mag = (1 << (N-1)) - 1;
            res_sign = sign_a;
        end else begin
            res_mag = sum_mag[N-2:0];
            res_sign = sign_a;
        end
    end else begin

        if (mag_a > mag_b) begin
            res_mag = mag_a - mag_b;
            res_sign = sign_a;
        end else if (mag_b > mag_a) begin
            res_mag = mag_b - mag_a;
            res_sign = sign_b;
        end else begin
            res_mag = 0;
            res_sign = 0;
        end
    end
end

assign c = {res_sign, res_mag};

endmodule

