        res = a - b;

        if (res[N-1] != (a[N-1] ^ b[N-1])) begin

            if (a[N-1] == b[N-1]) begin

                res = (a > b) ? a - b : b - a;
            end else begin

                if (a[N-1]) begin
                    res = a + (-b);
                end else begin
                    res = b + (-a);
                end
            end
        end
        c = res;
    end

