module pulse_detect (
    input clk,
    input rst_n,
    input data_in,
    output reg data_out
);


parameter IDLE    = 2'b00;
parameter FIRST   = 2'b01;
parameter SECOND  = 2'b10;

reg [1:0] state;


always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        data_out <= 0;
    end else begin
        case (state)
            IDLE: begin
                if (data_in == 0) begin
                    state <= FIRST;
                    data_out <= 0;
                end else begin
                    state <= IDLE;
                    data_out <= 0;
                end
            end
            FIRST: begin
                if (data_in == 1) begin
                    state <= SECOND;
                    data_out <= 0;
                end else begin
                    state <= IDLE;
                    data_out <= 0;
                end
            end
            SECOND: begin
                if (data_in == 0) begin
                    state <= IDLE;
                    data_out <= 1;
                end else begin
                    state <= IDLE;
                    data_out <= 0;
                end
            end
            default: begin
                state <= IDLE;
                data_out <= 0;
            end
        endcase
    end
end

endmodule

