module traffic_light (
    input rst_n,
    input clk,
    input pass_request,
    output reg [7:0] clock,
    output reg red,
    output reg yellow,
    output reg green
);

    parameter idle = 2'b00,
              s1_red = 2'b01,
              s2_yellow = 2'b10,
              s3_green = 2'b11;

    reg [1:0] state, next_state;
    reg [7:0] cnt;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= idle;
            cnt <= 8'd10;
        end else begin
            state <= next_state;
            case (state)
                idle: cnt <= 8'd10;
                s1_red: cnt <= (cnt > 0) ? cnt - 1 : 8'd60;
                s3_green: cnt <= (cnt > 0) ? cnt - 1 : 8'd5;
                s2_yellow: cnt <= (cnt > 0) ? cnt - 1 : 8'd10;
                default: cnt <= 8'd10;
            endcase
            if (pass_request && (state == s3_green) && (cnt > 10))
                cnt <= 8'd10;
        end
    end

    always @(*) begin
        next_state = state;
        case (state)
            idle: next_state = s1_red;
            s1_red: next_state = (cnt == 0) ? s3_green : next_state;
            s3_green: next_state = (cnt == 0) ? s2_yellow : next_state;
            s2_yellow: next_state = (cnt == 0) ? s1_red : next_state;
            default: next_state = idle;
        endcase
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            {red, yellow, green} <= 3'b0;
        end else begin
            red <= (state == s1_red);
            yellow <= (state == s2_yellow);
            green <= (state == s3_green);
        end
    end

    assign clock = cnt;

endmodule

