module alu (
    input [31:0] a,
    input [31:0] b,
    input [5:0] aluc,
    output reg [31:0] r,
    output zero,
    output reg carry,
    output reg overflow,
    output negative,
    output reg flag
);

parameter ADD  = 6'b100000;
parameter ADDU = 6'b100001;
parameter SUB  = 6'b100010;
parameter SUBU = 6'b100011;
parameter AND  = 6'b100100;
parameter OR   = 6'b100101;
parameter XOR  = 6'b100110;
parameter NOR  = 6'b100111;
parameter SLT  = 6'b101010;
parameter SLTU = 6'b101011;
parameter SLL  = 6'b000000;
parameter SRL  = 6'b000010;
parameter SRA  = 6'b000011;
parameter SLLV = 6'b000100;
parameter SRLV = 6'b000110;
parameter SRAV = 6'b000111;
parameter LUI  = 6'b001111;

always @(*) begin

    r = 32'b0;
    carry = 1'b0;
    overflow = 1'b0;
    flag = 1'bz;

    case (aluc)
        ADD: begin
            {carry, r} = {1'b0, a} + {1'b0, b};
            overflow = (a[31] == b[31]) && (r[31] != a[31]);
        end
        ADDU: begin
            {carry, r} = {1'b0, a} + {1'b0, b};
        end
        SUB: begin
            {carry, r} = {1'b0, a} + {1'b0, ~b} + 33'b1;
            overflow = (a[31] != b[31]) && (r[31] != a[31]);
        end
        SUBU: begin
            {carry, r} = {1'b0, a} + {1'b0, ~b} + 33'b1;
        end
        AND: begin
            r = a & b;
        end
        OR: begin
            r = a | b;
        end
        XOR: begin
            r = a ^ b;
        end
        NOR: begin
            r = ~(a | b);
        end
        SLT: begin
            {carry, r} = {1'b0, a} + {1'b0, ~b} + 33'b1;
            overflow = (a[31] != b[31]) && (r[31] != a[31]);
            flag = (r[31] ^ overflow);
            r = {31'b0, flag};
        end
        SLTU: begin
            {carry, r} = {1'b0, a} + {1'b0, ~b} + 33'b1;
            flag = ~carry;
            r = {31'b0, flag};
        end
        SLL: begin
            r = a << b[4:0];
        end
        SRL: begin
            r = a >> b[4:0];
        end
        SRA: begin
            r = $signed(a) >>> b[4:0];
        end
        SLLV: begin
            r = b << a[4:0];
        end
        SRLV: begin
            r = b >> a[4:0];
        end
        SRAV: begin
            r = $signed(b) >>> a[4:0];
        end
        LUI: begin
            r = {b[15:0], 16'b0};
        end
        default: r = 32'bz;
    endcase
end

assign zero = (r == 32'b0);
assign negative = r[31];

endmodule

