module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

reg [7:0] dividend_abs, divisor_abs;
reg [7:0] neg_divisor;
reg [15:0] sr_reg;

reg [3:0] cnt;
reg quotient_sign;
reg remainder_sign;

always @(posedge clk) begin
    if (rst) begin
        res_valid <= 0;
        cnt <= 0;
        sr_reg <= 0;
        dividend_abs <= 0;
        divisor_abs <= 0;
        neg_divisor <= 0;
        quotient_sign <= 0;
        remainder_sign <= 0;
    end else begin
        if (opn_valid && !res_valid) begin

            if (sign) begin
                dividend_abs <= dividend[7] ? -dividend : dividend;
                divisor_abs <= divisor[7] ? -divisor : divisor;
                quotient_sign <= dividend[7] ^ divisor[7];
                remainder_sign <= divisor[7];
            end else begin
                dividend_abs <= dividend;
                divisor_abs <= divisor;
                quotient_sign <= 0;
                remainder_sign <= 0;
            end

            sr_reg <= {dividend_abs, 8'b0} << 1;
            neg_divisor <= -divisor_abs;
            cnt <= 1;
            res_valid <= 0;
        end else if (cnt > 0 && cnt <= 8) begin
            if (cnt == 8) begin

                if (remainder_sign) begin

                    sr_reg[15:8] <= -sr_reg[15:8];
                end
                if (quotient_sign) begin

                    sr_reg[7:0] <= -sr_reg[7:0];
                end
                result <= {sr_reg[7:0], sr_reg[15:8]};
                res_valid <= 1;
                cnt <= 0;
            end else begin

                if (sr_reg[15:8] >= neg_divisor) begin
                    sr_reg <= {sr_reg[7:0] - neg_divisor, sr_reg[7:0], 1'b1};
                end else begin
                    sr_reg <= {sr_reg[7:0], sr_reg[7:0], 1'b0};
                end
                cnt <= cnt + 1;
            end
        end else begin
            res_valid <= 0;
        end
    end
end

endmodule

