                areg <= ain;
                breg <= bin;
                yout_r <= 0;
            end else if (i >= 1 && i <= 16) begin

                if (areg[i-1]) begin
                    yout_r <= yout_r + (breg << (i-1));
                end
            end
        end else begin

            areg <= 0;
