module fixed_point_adder #(
    parameter Q = 4,
    parameter N = 8
) (
    input [N-1:0] a,
    input [N-1:0] b,
    output reg [N-1:0] c
);

localparam INTEGER_BITS = N - Q;

reg a_sign, b_sign;
reg [INTEGER_BITS-1:0] a_int, b_int;
reg [INTEGER_BITS-1:0] a_mag, b_mag;
reg [INTEGER_BITS-1:0] sum_int, diff_int;
reg sum_sign, diff_sign;

always @(*) begin

    a_sign = a[N-1];
    a_int = a[N-2:Q];
    a_mag = a_sign ? (~a_int + 1) : a_int;

    b_sign = b[N-1];
    b_int = b[N-2:Q];
    b_mag = b_sign ? (~b_int + 1) : b_int;


    if (a_sign == b_sign) begin

        sum_int = a_mag + b_mag;
        sum_sign = a_sign;

        if (sum_int > {INTEGER_BITS{1'b1}}) begin
            sum_int = {INTEGER_BITS{1'b1}};
        end
    end else begin

        if (a_mag > b_mag) begin
            diff_int = a_mag - b_mag;
            diff_sign = a_sign;
        end else if (b_mag > a_mag) begin
            diff_int = b_mag - a_mag;
            diff_sign = b_sign;
        end else begin
            diff_int = 0;
            diff_sign = 0;
        end
    end


    if (a_sign != b_sign && a_mag == b_mag) begin
        c = {1'b0, {INTEGER_BITS{1'b0}}, {Q{1'b0}}};
    end else begin
        c = {diff_sign, diff_int, b[Q-1:0]};
    end
end

endmodule

