module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);

    reg [2:0] counter;
    reg [31:0] a_data, b_data;
    reg [7:0] a_exponent, b_exponent;
    reg [22:0] a_mantissa, b_mantissa;
    reg z_sign;
    reg [9:0] z_exponent;
    reg [47:0] product;
    reg guard, round, sticky;

    always @(posedge clk) begin
        if (rst) begin
            counter <= 0;
            z <= 0;
            a_data <= 0;
            b_data <= 0;
            a_exponent <= 0;
            b_exponent <= 0;
            a_mantissa <= 0;
            b_mantissa <= 0;
        end else begin
            case (counter)
                0: begin

                    a_sign = a[31];
                    b_sign = b[31];
                    a_exponent = a[30:23];
                    b_exponent = b[30:23];
                    a_mantissa = {1'b1, a[22:0]};
                    b_mantissa = {1'b1, b[22:0]};
                    a_data <= a;
                    b_data <= b;
                    counter <= 1;
                end

                1: begin

                    if (a_exponent == 8'hff || b_exponent == 8'hff) begin
                        if ((a_exponent == 8'hff && |a_mantissa) || (b_exponent == 8'hff && |b_mantissa)) begin
                            z <= {a_sign ^ b_sign, 8'hff, 1'b0, 22'h0};
                        end else if (a_exponent == 8'hff && |a_mantissa) begin
                            if (b_exponent == 8'hff && |b_mantissa) begin
                                z <= {a_sign ^ b_sign, 8'hff, 1'b0, 22'h0};
                            end else if (|b_mantissa) begin
                                z <= {a_sign ^ b_sign, 8'hff, 23'h0};
                            end else begin
                                z <= {b_sign, 23'h0, 1'b0, 22'h0};
                            end
                        end else if (b_exponent == 8'hff && |b_mantissa) begin
                            if (|a_mantissa) begin
                                z <= {b_sign, 8'hff, 23'h0};
                            end else begin
                                z <= {a_sign ^ b_sign, 8'hff, 23'h0};
                            end
                        end else begin
                            counter <= 2;
                        end
                        counter <= 0;
                    end else if (a_mantissa == 0 || b_mantissa == 0) begin
                        if (a_mantissa == 0 && b_mantissa == 0) begin
                            z <= {a_sign ^ b_sign, 8'h00, 23'h0, 1'b0};
                        end else begin
                            z <= { (a_mantissa == 0) ? b_sign : a_sign, 8'h00, 23'h0, 1'b0 };
                        end
                        counter <= 0;
                    end else begin
                        counter <= 2;
                    end
                end

                2: begin

                    product = {a_mantissa, 24'b0} * {b_mantissa, 24'b0};
                    counter <= 3;
                end

                3: begin

                    if (product[47]) begin
                        z_exponent = a_exponent + b_exponent - 9'd127 + 1;
                        product = product >> 1;
                    end else begin
                        z_exponent = a_exponent + b_exponent - 9'd127;
