                4: begin

                    if (guard && (round | sticky | z_mantissa[0])) begin
                        z_mantissa = z_mantissa + 1;
                        if (z_mantissa[24]) begin
                            z_exponent = z_exponent + 1;
                            z_mantissa = 24'b0;
                        end
                    end

                    if (z_exponent > 11'h0ff) begin
                        z <= {z_sign, 8'hff, 23'h0};
                    end else if (z_exponent[8]) begin
                        z <= {z_sign, 8'h00, 23'h0, 1'b0};
                    end else begin
                        z <= {z_sign, z_exponent[7:0], z_mantissa[22:0]};
                    end
                    counter <= 0;
                end

                default: counter <= 0;
            endcase
