module asyn_fifo #(
    parameter WIDTH = 8,
    parameter DEPTH = 16
) (
    input wclk,
    input wrstn,
    input winc,
    input [WIDTH-1:0] wdata,
    output reg wfull,
    input rclk,
    input rrstn,
    input rinc,
    output rempty,
    output [WIDTH-1:0] rdata
);

    reg [$clog2(DEPTH):0] waddr_bin, raddr_bin;

    reg [($clog2(DEPTH)):0] wptr, rptr;

    reg [($clog2(DEPTH)):0] wptr_sync_r2, rptr_sync_w2;
    reg [($clog2(DEPTH)):0] wptr_sync_r1, rptr_sync_w1;


    function [($clog2(DEPTH)):0] bin2gray;
        input [($clog2(DEPTH)):0] bin;
        bin2gray = bin ^ (bin >> 1);
    endfunction


    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn) begin
            rptr_sync_w1 <= 0;
            rptr_sync_w2 <= 0;
        end else begin
            rptr_sync_w1 <= rptr;
            rptr_sync_w2 <= rptr_sync_w1;
        end
    end


    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn) begin
            wptr_sync_r1 <= 0;
            wptr_sync_r2 <= 0;
        end else begin
            wptr_sync_r1 <= wptr;
            wptr_sync_r2 <= wptr_sync_r1;
        end
    end


    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn) begin
            waddr_bin <= 0;
            wptr <= bin2gray(0);
            wfull <= 0;
        end else begin
            if (winc && !wfull) begin
                waddr_bin <= waddr_bin + 1;
                wptr <= bin2gray(waddr_bin + 1);
            end
            wfull <= ((wptr_sync_r2[$clog2(DEPTH): ($clog2(DEPTH)-1)] != wptr[$clog2(DEPTH): ($clog2(DEPTH)-1)]) &&
                      (wptr_sync_r2[$clog2(DEPTH)-2:0] == wptr[$clog2(DEPTH)-2:0]));
        end
    end


    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn) begin
            raddr_bin <= 0;
            rptr <= bin2gray(0);
            rempty <= 1;
        end else begin
            if (rinc && !rempty) begin
                raddr_bin <= raddr_bin + 1;
                rptr <= bin2gray(raddr_bin + 1);
            end
            rempty <= (rptr == wptr_sync_r2);
        end
    end


    dual_port_RAM #(
        .WIDTH(WIDTH),
        .DEPTH(DEPTH)
    ) ram (
        .wclk(wclk),
        .wenc(winc && !wfull),
        .waddr(waddr_bin[$clog2(DEPTH)-1:0]),
        .wdata(wdata),
        .rclk(rclk),
        .renc(rinc && !rempty),
        .raddr(raddr_bin[$clog2(DEPTH)-1:0]),
        .rdata(rdata)
    );

endmodule


