always @(posedge Clk) begin
    if (EN) begin
        if (Rst) begin
            SP <= 4;

            dataOut <= 0;
            stack_mem[0] <= 0;
            stack_mem[1] <= 0;
            stack_mem[2] <= 0;
            stack_mem[3] <= 0;
        end else begin
            case (RW)
                0: begin   
                    if (SP != 0) begin
                        stack_mem[SP - 1] <= dataIn;
                        SP <= SP - 1;
                    end
                end
                1: begin   
                    if (SP != 4) begin
                        dataOut <= stack_mem[SP];
                        SP <= SP + 1;
                    end
                end
            endcase
        end
    end
end


assign EMPTY = (SP == 4);
assign FULL = (SP == 0);

endmodule

