module pulse_detect (
    input clk,
    input rst_n,
    input data_in,
    output reg data_out
);

reg [1:0] state;
localparam IDLE = 2'b00;
localparam STATE1 = 2'b01;
localparam STATE2 = 2'b10;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        data_out <= 0;
    end else begin
        case (state)
            IDLE: begin
                if (data_in == 0) begin
                    state <= STATE1;
                end else begin
                    state <= IDLE;
                end
                data_out <= 0;
            end
            STATE1: begin
                if (data_in == 1) begin
                    state <= STATE2;
                end else begin
                    state <= IDLE;
                end
                data_out <= 0;
            end
            STATE2: begin
                if (data_in == 0) begin
                    state <= IDLE;
                    data_out <= 1;
                end else begin
                    state <= IDLE;
                    data_out <= 0;
                end
            end
            default: state <= IDLE;
        endcase
    end
end

endmodule

