module traffic_light (
    input rst_n,
    input clk,
    input pass_request,
    output reg [7:0] clock,
    output reg red,
    output reg yellow,
    output reg green
);

parameter IDLE = 2'b00;
parameter S1_RED = 2'b01;
parameter S2_YELLOW = 2'b10;
parameter S3_GREEN = 2'b11;

reg [1:0] state;
reg [7:0] counter;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        counter <= 8'd10;
        red <= 0;
        yellow <= 0;
        green <= 0;
    end else begin
        case (state)
            IDLE: begin
                state <= S3_GREEN;
                counter <= 8'd60;
                red <= 0;
                yellow <= 0;
                green <= 1;
            end
            S3_GREEN: begin
                if (pass_request && counter > 10) begin
                    counter <= 8'd10;
                end else if (counter == 0) begin
                    state <= S2_YELLOW;
                    counter <= 8'd5;
                    green <= 0;
                    yellow <= 1;
                end else begin
                    counter <= counter - 1;
                end
                red <= 0;
            end
            S2_YELLOW: begin
                if (counter == 0) begin
                    state <= S1_RED;
                    counter <= 8'd10;
                    yellow <= 0;
                    red <= 1;
                end else begin
                    counter <= counter - 1;
                end
            end
            S1_RED: begin
                if (counter == 0) begin
                    state <= IDLE;
                    counter <= 8'd0;
                    red <= 0;
                    green <= 1;
                end else begin
                    counter <= counter - 1;
                end
            end
            default: state <= IDLE;
        endcase
    end
end

assign clock = counter;

endmodule

