module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

    reg [15:0] SR;
    reg [3:0] cnt;
    reg start_cnt;
    reg [7:0] abs_dividend;
    reg [7:0] abs_divisor;
    reg sign_dividend;
    reg sign_divisor;
    reg [7:0] quotient;
    reg [7:0] remainder;

    always @(posedge clk) begin
        if (rst) begin
            res_valid <= 0;
            SR <= 0;
            cnt <= 0;
            start_cnt <= 0;
            sign_dividend <= 0;
            sign_divisor <= 0;
            abs_dividend <= 0;
            abs_divisor <= 0;
            quotient <= 0;
            remainder <= 0;
        end else begin
            if (res_valid) begin
                res_valid <= 0;
            end else if (opn_valid && !res_valid) begin
                sign_dividend <= sign ? dividend[7] : 0;
                sign_divisor <= sign ? divisor[7] : 0;
                abs_dividend <= sign ? (dividend[7] ? (~dividend + 1) : dividend) : dividend;
                abs_divisor <= sign ? (divisor[7] ? (~divisor + 1) : divisor) : divisor;
                SR <= {8'b0, abs_dividend, 1'b0};
                cnt <= 1;
                start_cnt <= 1;
                res_valid <= 0;
            end else if (start_cnt) begin
                if (cnt <= 8) begin
                    if (cnt < 8) begin
                        reg [8:0] sub_res = {1'b0, SR[15:8]} - {1'b0, abs_divisor};
                        reg borrow = sub_res[8];
                        if (borrow) begin
                            SR <= {sub_res[7:0], SR[7:1], 1'b0};
                        end else begin
                            SR <= {sub_res[7:0], SR[7:1], 1'b1};
                        end
                        cnt <= cnt + 1;
                    end else begin
                        start_cnt <= 0;
                        cnt <= 0;
                        quotient <= SR[7:0];
                        remainder <= SR[15:8];
                        if (sign) begin
                            reg [7:0] quo = (sign_dividend != sign_divisor) ? -quotient : quotient;
                            reg [7:0] rem = (sign_dividend) ? -remainder : remainder;
                            result <= {rem, quo};
                        end else begin
                            result <= {remainder, quotient};
                        end
                        res_valid <= 1;
                    end
                end
            end
        end
    end
endmodule

