module multi_booth_8bit (
    input clk,
    input reset,
    input [7:0] a,
    input [7:0] b,
    output reg [15:0] p,
    output reg rdy
);

reg [15:0] multiplier;
reg [15:0] multiplicand;
reg [15:0] product;
reg [4:0] counter;

always @(posedge clk or posedge reset) begin
    if (reset) begin
        multiplier <= { {8{a[7]}}, a };
        multiplicand <= { {8{b[7]}}, b };
        product <= 16'b0;
        counter <= 5'b0;
        rdy <= 1'b0;
    end
    else begin
        if (counter < 16) begin

            multiplicand <= multiplicand << 1;

            if (multiplier[counter]) begin
                product <= product + multiplicand;
            end
            counter <= counter + 1;
        end
        else begin
            rdy <= 1'b1;
        end
    end
end


always @(*) begin
    p = product;
end

endmodule

