module multi_16bit (
    input clk,
    input rst_n,
    input start,
    input [15:0] ain,
    input [15:0] bin,
    output [31:0] yout,
    output reg done
);

reg [4:0] i;

reg [15:0] areg;
reg [15:0] breg;
reg [31:0] yout_r;


always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        i <= 5'b0;
    end else begin
        if (start) begin
            if (i < 5'b10001) 
                i <= i + 1;
        end else
            i <= 5'b0;
    end
end


always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        done <= 1'b0;
    end else begin
        case (i)
            5'b10000: done <= 1'b1;

            5'b10001: done <= 1'b0;

            default: done <= done;
        endcase
    end
end


always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        areg <= 16'b0;
        breg <= 16'b0;
        yout_r <= 32'b0;
    end else begin
        if (start) begin
            if (i == 5'b0) begin 
                areg <= ain;
                breg <= bin;
                yout_r <= 32'b0;
            end else if (i >= 5'b1 && i <= 5'b10000) begin
                if (areg[i-1])
                    yout_r <= yout_r + (breg << (i-1));
            end
        end else begin 
            areg <= 16'b0;
            breg <= 16'b0;
            yout_r <= 32'b0;
        end
    end
end

assign yout = yout_r;

endmodule

