module adder_bcd (
    input [3:0] A,
    input [3:0] B,
    input Cin,
    output [3:0] Sum,
    output Cout
);

    reg [4:0] sum_5bit;
    reg [4:0] sum_corrected;

    always @(*) begin

        sum_5bit = {1'b0, A} + {1'b0, B} + Cin;

        if (sum_5bit > 9) begin
            sum_corrected = sum_5bit + 5'd6;
        end else begin
            sum_corrected = sum_5bit;
        end
    end

    assign Sum = sum_corrected[3:0];
    assign Cout = sum_corrected[4];

endmodule

