    input [3:0] B,
    input Cin,
    output [3:0] S,
    output P,
    output G
);
    wire [3:0] p, g;
    assign p = A ^ B;
    assign g = A & B;

    wire c0, c1, c2, c3, c4;
    assign c0 = Cin;
    assign c1 = g[0] | (p[0] & c0);
