module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);
    reg [2:0] counter;
    reg a_sign, b_sign;
    reg [7:0] a_exponent, b_exponent;
    reg [22:0] a_mantissa, b_mantissa;
    reg [47:0] product;
    reg guard_bit, round_bit, sticky;
    reg [22:0] z_mantissa;
    reg [9:0] z_exponent;

    always @(posedge clk) begin
        if (rst) begin
            counter <= 0;
            z <= 0;
        end else begin
            case (counter)
                0: begin

                    a_sign <= a[31];
                    b_sign <= b[31];
                    a_exponent <= a[30:23];
                    b_exponent <= b[30:23];
                    a_mantissa <= a[22:0];
                    b_mantissa <= b[22:0];
                    counter <= 1;
                end
                1: begin

                    if ((a_exponent == 8'hFF && |a_mantissa) || 
                        (b_exponent == 8'hFF && |b_mantissa)) begin

                        z <= {a_sign ^ b_sign, 8'hFF, 1'b1, 22'h0};
                    end else if ((a_exponent == 8'hFF && ~|a_mantissa) && 
                               (b_exponent == 8'hFF && ~|b_mantissa)) begin

                        z <= {a_sign ^ b_sign, 8'hFF, 1'b0, 23'h0};
                    end else if ((a_exponent == 8'hFF && ~|a_mantissa) || 
                               (b_exponent == 8'hFF && ~|b_mantissa)) begin

                        z <= {1'b0, 8'hFF, 1'b0, 23'h0};
                    end else if ((a_mantissa == 0 && a_exponent == 0) || 
                               (b_mantissa == 0 && b_exponent == 0)) begin

                        z <= {a_sign ^ b_sign, 1'b0, 23'h0};
                    end else begin

                        product <= {1'b1, a_mantissa} * {1'b1, b_mantissa};
                        counter <= 2;
                    end
                end
                2: begin

                    reg [5:0] leading_one;
                    integer i;
                    leading_one = 5'd47;
                    for (i = 47;
 i >= 0;
 i = i - 1) begin
                        if (product[i]) leading_one = i;
                    end
                    product = product << (47 - leading_one);
                    z_exponent = (a_exponent - 8'd127) + (b_exponent - 8'd127) + leading_one - 10'd127;
                    if (product[47]) begin
                        product = product >> 1;
                        z_exponent = z_exponent + 10'd1;
                    end


                    guard_bit = product[46];
                    round_bit = product[45];
                    sticky = |product[44:0];
                    if (guard_bit) begin
                        if (round_bit | sticky) begin
                            {product, sticky} = {product + 48'h1, sticky};
                        end
                    end


                    z_mantissa = product[46:24];
                    if (product[23]) begin 
                        z_mantissa = z_mantissa + 23'h1;
                        if (z_mantissa[22]) z_exponent = z_exponent + 1;
                    end


                    if (z_exponent > 10'h0ff) begin
                        z <= {a_sign ^ b_sign, 8'hFF, 1'b0, 23'h0};
                    end else if (z_exponent < 10'd1) begin
                        z <= {a_sign ^ b_sign, 1'b0, 23'h0};
                    end else begin
                        z <= {a_sign ^ b_sign, z_exponent[7:0], z_mantissa};
                    end
                    counter <= 0;
                end
                default: counter <= 0;
            endcase
        end
    end
endmodule

