module asyn_fifo #(
    parameter WIDTH = 8,
    parameter DEPTH = 16
) (
    input wclk,
    input wrstn,
    input winc,
    input [WIDTH-1:0] wdata,
    input rclk,
    input rrstn,
    input rinc,
    output rempty,
    output wfull,
    output [WIDTH-1:0] rdata
);

localparam ADDR_BITS = $clog2(DEPTH);
localparam PTR_WIDTH = ADDR_BITS + 1;


reg [PTR_WIDTH-1:0] wptr_bin;
wire [PTR_WIDTH-1:0] wptr_gray;
reg [PTR_WIDTH-1:0] rptr_gray_sync1, rptr_gray_sync2;


reg [PTR_WIDTH-1:0] rptr_bin;
wire [PTR_WIDTH-1:0] rptr_gray;
reg [PTR_WIDTH-1:0] wptr_gray_sync1, wptr_gray_sync2;


function [PTR_WIDTH-1:0] binary_to_gray(input [PTR_WIDTH-1:0] binary);
    binary_to_gray = (binary >> 1) ^ binary;
endfunction

function [PTR_WIDTH-1:0] gray_to_binary(input [PTR_WIDTH-1:0] gray);
    reg [PTR_WIDTH-1:0] binary;
    integer i;
    begin
        binary[PTR_WIDTH-1] = gray[PTR_WIDTH-1];
        for (i = PTR_WIDTH-2;
 i >= 0;
 i = i-1)
            binary[i] = binary[i+1] ^ gray[i];
        gray_to_binary = binary;
    end
endfunction


always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) begin
        wptr_bin <= 0;
    end else if (winc && !wfull) begin
        wptr_bin <= wptr_bin + 1;
    end
end

assign wptr_gray = binary_to_gray(wptr_bin);


always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) begin
        {rptr_gray_sync1, rptr_gray_sync2} <= 0;
    end else begin
        rptr_gray_sync1 <= rptr_gray;
        rptr_gray_sync2 <= rptr_gray_sync1;
    end
end


wire [PTR_WIDTH-1:0] rptr_bin_sync = gray_to_binary(rptr_gray_sync2);


assign wfull = (wptr_bin[PTR_WIDTH-1] != rptr_bin_sync[PTR_WIDTH-1]) &&
               (wptr_bin[ADDR_BITS-1:0] == rptr_bin_sync[ADDR_BITS-1:0]);


always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) begin
        rptr_bin <= 0;
    end else if (rinc && !rempty) begin
        rptr_bin <= rptr_bin + 1;
    end
end

assign rptr_gray = binary_to_gray(rptr_bin);


always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) begin
        {wptr_gray_sync1, wptr_gray_sync2} <= 0;
    end else begin
        wptr_gray_sync1 <= wptr_gray;
        wptr_gray_sync2 <= wptr_gray_sync1;
    end
end


wire [PTR_WIDTH-1:0] wptr_bin_sync = gray_to_binary(wptr_gray_sync2);


assign rempty = (rptr_bin == wptr_bin_sync);


dual_port_RAM #(
    .WIDTH(WIDTH),
    .DEPTH(DEPTH)
) ram_inst (
    .wclk(wclk),
    .wrstn(wrstn),
    .wenc(winc && !wfull),
    .waddr(wptr_bin[ADDR_BITS-1:0]),
