module pulse_detect (
    input clk,
    input rst_n,
    input data_in,
    output reg data_out
);
    reg state;
    parameter S0 = 1'b0, 
              S1 = 1'b1;


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= S0;
            data_out <= 0;
        end else begin
            case (state)
                S0: begin
                    if (data_in) begin
                        state <= S1;
                        data_out <= 0;
                    end else begin
                        state <= S0;
                        data_out <= 0;
                    end
                end
                S1: begin
                    if (!data_in) begin
                        state <= S0;
                        data_out <= 1;
                    end else begin
                        state <= S1;
                        data_out <= 0;
                    end
                end
                default: begin
                    state <= S0;
                    data_out <= 0;
                end
            endcase
        end
    end
