module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

reg [7:0] dividend_reg;
reg [7:0] divisor_reg;
reg [7:0] quotient;
reg [8:0] remainder;
reg [3:0] counter;
reg processing;
reg sign_dividend;
reg sign_divisor;

always @(posedge clk) begin
    if (rst) begin
        res_valid <= 0;
        processing <= 0;
        counter <= 0;
        quotient <= 0;
        remainder <= 0;
        sign_dividend <= 0;
        sign_divisor <= 0;
        dividend_reg <= 0;
        divisor_reg <= 0;
    end else begin
        if (opn_valid && !processing) begin
            sign_dividend <= dividend[7] & sign;
            sign_divisor <= divisor[7] & sign;
            dividend_reg <= sign ? (dividend[7] ? -dividend : dividend) : dividend;
            divisor_reg <= sign ? (divisor[7] ? -divisor : divisor) : divisor;
            remainder <= 0;
            quotient <= sign ? (dividend[7] ? -dividend : dividend) : dividend;
            counter <= 0;
            processing <= 1;
            res_valid <= 0;
        end else if (processing) begin
            if (counter < 8) begin
                remainder <= {remainder[7:0], quotient[7]} << 1;
                remainder[0] <= quotient[7];
                quotient <= quotient << 1;
                if (remainder >= {1'b0, divisor_reg}) begin
                    remainder <= remainder - {1'b0, divisor_reg};
                    quotient[0] <= 1'b1;
                end else begin
                    quotient[0] <= 1'b0;
                end
                counter <= counter + 1;
            end else begin
                if (sign) begin
                    if (sign_dividend ^ sign_divisor) begin
                        quotient <= -quotient;
                    end
                    if (sign_dividend) begin
                        remainder <= -remainder;
                    end
                end
                result <= {remainder[7:0], quotient[7:0]};
                res_valid <= 1;
                processing <= 0;
                counter <= 0;
            end
        end else begin
            res_valid <= 0;
        end
    end
end

endmodule

