module fixed_point_adder #(
    parameter Q = 8,
    parameter N = 16
) (
    input [N-1:0] a,
    input [N-1:0] b,
    output reg [N-1:0] c
);

    always @* begin
        if (a[N-1] == b[N-1]) begin

            c = a + b;
        end else begin

            reg [N-1:0] abs_a = a[N-1] ? (-a) : a;
            reg [N-1:0] abs_b = b[N-1] ? (-b) : b;
            if (abs_a > abs_b) begin
                c = {a[N-1], abs_a - abs_b};
            end else if (abs_b > abs_a) begin
                c = {b[N-1], abs_b - abs_a};
            end else begin
                c = 0;
            end
        end
    end

endmodule

