        rptr_bin <= 0;
        rptr_gray <= 0;
        raddr <= 0;
    end else begin
        if (rinc && !rempty) begin
            rptr_bin <= rptr_bin + 1;
            rptr_gray <= (rptr_bin + 1) ^ ((rptr_bin + 1) >> 1);
            raddr <= rptr_bin[ADDR_WIDTH-1:0];
        end
    end
