module LIFObuffer (
    input [3:0] dataIn,
    input RW,
    input EN,
    input Rst,
    input Clk,
    output reg EMPTY,
    output reg FULL,
    output reg [3:0] dataOut
);

reg [3:0] stack_mem [0:3];
reg [2:0] SP;

always @(posedge Clk) begin
    reg [2:0] next_SP;

    if (Rst) begin
        SP <= 4;
        stack_mem[0] <= 0;
        stack_mem[1] <= 0;
        stack_mem[2] <= 0;
        stack_mem[3] <= 0;
        dataOut <= 0;
        EMPTY <= 1;
        FULL <= 0;
    end
    else if (EN) begin
        next_SP = SP;
        dataOut <= 0;

        if (RW) begin 
            if (!EMPTY) begin
                dataOut <= stack_mem[SP];
                next_SP = SP + 1;
            end
        end
        else begin 
            if (!FULL) begin
                stack_mem[SP-1] <= dataIn;
                next_SP = SP - 1;
            end
        end

        SP <= next_SP;
        EMPTY <= (next_SP == 4);
        FULL <= (next_SP == 0);
    end
    else begin
        EMPTY <= (SP == 4);
        FULL <= (SP == 0);
    end
end

endmodule

