module traffic_light (
    input rst_n,
    input clk,
    input pass_request,
    output [7:0] clock,
    output red,
    output yellow,
    output green
);

    reg [7:0] cnt;
    reg [1:0] state;
    reg p_red, p_yellow, p_green;

    parameter idle = 2'b00;
    parameter s1_red = 2'b01;
    parameter s2_yellow = 2'b10;
    parameter s3_green = 2'b11;


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= idle;
            {p_red, p_yellow, p_green} <= 3'b000;
            cnt <= 10;
        end else begin
            case (state)
                idle: begin
                    state <= s1_red;
                    p_red <= 1;
                end
                s1_red: begin
                    if (cnt == 0) begin
                        state <= s3_green;
                        p_red <= 0;
                        p_green <= 1;
                        cnt <= 60;
                    end else begin
                        cnt <= cnt - 1;
                    end
                end
                s3_green: begin
                    if (pass_request) begin
                        if (cnt > 10) cnt <= 10;
                    end
                    if (cnt == 0) begin
                        state <= s2_yellow;
                        p_green <= 0;
                        p_yellow <= 1;
                        cnt <= 5;
                    end else begin
                        cnt <= cnt - 1;
                    end
                end
                s2_yellow: begin
                    if (cnt == 0) begin
                        state <= s1_red;
                        p_yellow <= 0;
                        p_red <= 1;
                        cnt <= 10;
                    end else begin
                        cnt <= cnt - 1;
                    end
                end
                default: state <= idle;
            endcase
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt <= 10;
        end else begin
            case (state)
                s1_red: cnt <= 3;
                s3_green: cnt <= (pass_request && p_green) ? 10 : (cnt > 3) ? cnt - 1 : 5;
                s2_yellow: cnt <= (cnt > 3) ? cnt - 1 : 10;
                default: cnt <= (state == s1_red) ? 3 : 0;
            endcase
        end
    end


    assign clock = cnt;
    assign {red, yellow, green} = {p_red, p_yellow, p_green};

endmodule

