module edge_detect (
    input clk,
    input rst_n,
    input a,
    output reg rise,
    output reg down
);

reg a_prev;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        a_prev <= 1'b0;
    end else begin
        a_prev <= a;
    end
end

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        rise <= 0;
        down <= 0;
    end else begin
        rise <= 0;
        down <= 0;
        if (a != a_prev) begin
            if (a_prev == 0 && a == 1) begin
                rise <= 1;
            end else if (a_prev == 1 && a == 0) begin
                down <= 1;
            end
        end
    end
end

endmodule

