module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

reg [7:0] abs_dividend;
reg [7:0] abs_divisor;
reg [7:0] neg_divisor;
reg [15:0] SR;

reg [3:0] cnt;
reg state;

localparam IDLE = 0, PROCESS = 1, DONE = 2;

always @(posedge clk) begin
    if (rst) begin
        state <= IDLE;
        res_valid <= 0;
        SR <= 16'b0;
        cnt <= 0;
        abs_dividend <= 0;
        abs_divisor <= 0;
        neg_divisor <= 0;
    end else begin
        case (state)
            IDLE: begin
                res_valid <= 0;
                if (opn_valid && !res_valid) begin

                    abs_dividend <= sign ? (dividend[7] ? -dividend : dividend) : dividend;
                    abs_divisor <= sign ? (divisor[7] ? -divisor : divisor) : divisor;
                    neg_divisor <= -((sign && divisor[7]) ? -divisor : divisor);

                    SR <= {8'b0, abs_dividend} << 1;
                    cnt <= 0;
                    state <= PROCESS;
                end
            end
            PROCESS: begin
                if (cnt < 8) begin

                    if (SR[15:8] >= abs_divisor) begin
                        SR[15:8] <= SR[15:8] - abs_divisor;
                        SR[0] <= 1;
                    end else begin
                        SR[0] <= 0;
                    end

                    SR <= SR << 1;
                    cnt <= cnt + 1;
                end else begin
                    state <= DONE;
                end
            end
            DONE: begin
                result <= {SR[15:8], SR[7:0]};

                if (sign) begin
                    if (dividend[7]) begin
                        result[15:8] <= -result[15:8];
                    end
                    if (dividend[7] ^ divisor[7]) begin
                        result[7:0] <= -result[7:0];
                    end
                end
                res_valid <= 1;
                state <= IDLE;
            end
        endcase
    end
end

endmodule

