    wire equal_2 = (A[2] == B[2]);
    wire equal_1 = (A[1] == B[1]);
    wire equal_0 = (A[0] == B[0]);

    assign A_equal = equal_3 & equal_2 & equal_1 & equal_0;

    assign A_less = (A[3] < B[3]) | 
                    (equal_3 & (A[2] < B[2])) | 
                    (equal_3 & equal_2 & (A[1] < B[1])) | 
                    (equal_3 & equal_2 & equal_1 & (A[0] < B[0]));

    assign A_greater = (A[3] > B[3]) | 
                       (equal_3 & (A[2] > B[2])) | 
                       (equal_3 & equal_2 & (A[1] > B[1])) | 
                       (equal_3 & equal_2 & equal_1 & (A[0] > B[0]));

