module cla_16bit (
    input [15:0] A,
    input [15:0] B,
    input Cin,
    output [15:0] S,
    output G,
    output P
);
    wire [15:0] G_i, P_i;
    wire [16:0] C;

    assign G_i = A & B;
    assign P_i = A ^ B;

    assign C[0] = Cin;


    genvar i;
    generate
        for (i = 0;
 i < 16;
 i = i + 1) begin : cla
            assign C[i+1] = G_i[i] | (P_i[i] & C[i]);
        end
    endgenerate

    assign S = P_i ^ C[15:0];


    reg g_temp, p_temp;
    integer j;
    always @(*) begin
        g_temp = 0;
        p_temp = 1;
        for (j = 0;
 j < 16;
 j = j + 1) begin
            g_temp = G_i[j] | (P_i[j] & g_temp);
            p_temp = P_i[j] & p_temp;
        end
    end

    assign G = g_temp;
    assign P = p_temp;
endmodule

