module accu (
    input clk,
    input rst_n,
    input [7:0] data_in,
    input valid_in,
    output reg valid_out,
    output reg [9:0] data_out
);

reg [9:0] sum;
reg [1:0] count;

wire [9:0] next_sum = sum + data_in;
wire [1:0] next_count = count + (valid_in ? 1'b1 : 1'b0);

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        sum <= 10'b0;
        count <= 2'b0;
        valid_out <= 1'b0;
        data_out <= 10'b0;
    end else begin

        valid_out <= 1'b0;
        sum <= next_sum;
        count <= next_count;


        if (valid_in && next_count == 2'b11) begin
            data_out <= next_sum;
            valid_out <= 1'b1;
            sum <= 10'b0;
            count <= 2'b0;
        end
    end
end

endmodule

