module fixed_point_adder #(parameter Q=4, N=8) (
    input [N-1:0] a,
    input [N-1:0] b,
    output reg [N-1:0] res
);

reg sign_a, sign_b;
reg [N-2:0] magnitude_a, magnitude_b;
reg [N-1:0] sum, diff;
reg result_sign;

always @* begin
    sign_a = a[N-1];
    sign_b = b[N-1];
    magnitude_a = sign_a ? (~a[N-2:0] + 1) : a[N-2:0];
    magnitude_b = sign_b ? (~b[N-2:0] + 1) : b[N-2:0];

    if (sign_a == sign_b) begin
        sum = {1'b0, magnitude_a} + {1'b0, magnitude_b};
        result_sign = sign_a;
        res = {result_sign, sum[N-2:0]};
    end else begin
        if (magnitude_a > magnitude_b) begin
            diff = {1'b0, magnitude_a - magnitude_b};
            result_sign = sign_a;
        end else if (magnitude_b > magnitude_a) begin
            diff = {1'b0, magnitude_b - magnitude_a};
            result_sign = sign_b;
        end else begin
            diff = 0;
            result_sign = 0;
        end
        res = {result_sign, diff[N-2:0]};
    end
end

endmodule

