module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);

reg [2:0] counter;
reg a_sign, b_sign, z_sign;
reg [7:0] a_exponent, b_exponent, z_exponent;
reg [22:0] a_mantissa, b_mantissa;
reg [47:0] product;
reg [23:0] product_mantissa;
reg guard_bit, round_bit, sticky_bit;
reg [4:0] exponent_sum;

always @(posedge clk) begin
    if (rst) begin
        counter <= 3'b0;
        z <= 32'b0;
        a_sign <= 0;
        b_sign <= 0;
        z_sign <= 0;
        a_exponent <= 8'b0;
        b_exponent <= 8'b0;
        z_exponent <= 8'b0;
        a_mantissa <= 23'b0;
        b_mantissa <= 23'b0;
        product <= 48'b0;
        product_mantissa <= 24'b0;
        guard_bit <= 0;
        round_bit <= 0;
        sticky_bit <= 0;
        exponent_sum <= 5'b0;
    end else begin
        case (counter)

            0: begin
                a_sign <= a[31];
                b_sign <= b[31];
                a_exponent <= a[30:23];
                b_exponent <= b[30:23];

                a_mantissa <= (a[30:23] == 8'b0) ? {1'b0, a[22:0]} : {1'b1, a[22:0]};
                b_mantissa <= (b[30:23] == 8'b0) ? {1'b0, b[22:0]} : {1'b1, b[22:0]};
                counter <= 1;
            end

            1: begin

                if ((a_exponent == 8'hFF && a_mantissa[22:0] != 0) ||
                    (b_exponent == 8'hFF && b_mantissa[22:0] != 0)) begin
                    z <= {a_sign ^ b_sign, 8'hFF, a_mantissa[22:0]};
                end

                else if ((a_exponent == 8'hFF) || (b_exponent == 8'hFF)) begin
                    if ((a_mantissa == 23'b0 && b_mantissa != 23'b0) ||
                        (b_mantissa == 23'b0 && a_mantissa != 23'b0)) begin
                        z <= {a_sign ^ b_sign, 8'hFF, 23'b0};
                    end
                    else begin
                        z <= {a_sign ^ b_sign, 8'hFF, 23'b0};

                    end
                end

                else if (a_mantissa == 23'b0 || b_mantissa == 23'b0) begin
                    z <= {a_sign ^ b_sign, 23'b0, 31'b0};
                end
                else begin

                    exponent_sum <= a_exponent + b_exponent - 8'd127;
                    product <= {1'b0, a_mantissa} * {1'b0, b_mantissa};

                    counter <= 2;
                end
            end

            2: begin

                if (product[47]) begin

                    product_mantissa <= product[46:23];
                    exponent_sum <= exponent_sum + 1;

                    guard_bit <= product[22];
                    round_bit <= product[21];
                    sticky_bit <= |product[20:0];
                end
                else begin

                    product_mantissa <= product[45:22];
                    guard_bit <= product[21];
                    round_bit <= product[20];
                    sticky_bit <= |product[19:0];
                end
                counter <= 3;
            end

            3: begin

                if (guard_bit & (round_bit | sticky_bit | product_mantissa[0])) begin
                    product_mantissa <= product_mantissa + 1;
                end

                if (product_mantissa[23]) begin

                    product_mantissa <= product_mantissa >> 1;
                    exponent_sum <= exponent_sum + 1;
                end

                if (exponent_sum > 8'hFE) begin

                    z <= {a_sign ^ b_sign, 8'hFF, 23'b0};
                end
                else if (exponent_sum < 8'b1) begin

                    z <= {a_sign ^ b_sign, 23'b0, 31'b0};
                end
                else begin

                    z <= {a_sign ^ b_sign, exponent_sum[7:0], product_mantissa[22:0]};
                end
                counter <= 0;
            end
            default: counter <= 0;
        endcase
    end
end

endmodule

