module sub_64bit (
    input [63:0] A,
    input [63:0] B,
    output reg [63:0] result,
    output reg overflow
);

always @(*) begin

    result = $signed(A) - $signed(B);


    if ((A[63] == 0 && B[63] == 1 && result[63] == 1) ||  
        (A[63] == 1 && B[63] == 0 && result[63] == 0))     
        overflow = 1'b1;
    else
        overflow = 1'b0;
end

endmodule

