module asyn_fifo #(
    parameter WIDTH = 8,
    parameter DEPTH = 16
) (
    input wclk,
    input wwrstn,
    input winc,
    input [WIDTH-1:0] wdata,
    output rempty,
    output wfull,
    input rclk,
    input rrrstn,
    input rinc,
    output [WIDTH-1:0] rdata
);

localparam ADDR_WIDTH = $clog2(DEPTH);
localparam PTR_WIDTH = ADDR_WIDTH + 1;


reg [PTR_WIDTH-1:0] waddr_bin;
reg [ADDR_WIDTH-1:0] wptr_gray;


reg [PTR_WIDTH-1:0] raddr_bin;
reg [ADDR_WIDTH-1:0] rptr_gray;


reg [ADDR_WIDTH-1:0] wptr_gray_sync1, wptr_gray_sync2;
reg [ADDR_WIDTH-1:0] rptr_gray_sync1, rptr_gray_sync2;


dual_port_RAM #(
    .DEPTH(DEPTH),
    .WIDTH(WIDTH)
) ram (
    .wclk(wclk),
    .wenc(winc && !wfull),
    .waddr(waddr_bin[ADDR_WIDTH-1:0]),
    .wdata(wdata),
    .rclk(rclk),
    .renc(rinc && !rempty),
    .raddr(raddr_bin[ADDR_WIDTH-1:0]),
    .rdata(rdata)
);


always @(posedge wclk or negedge wwrstn) begin
    if (!wwrstn) begin
        waddr_bin <= 0;
        wptr_gray <= 0;
    end else begin
        if (winc && !wfull) begin
            waddr_bin <= waddr_bin + 1;
        end
        wptr_gray <= (waddr_bin >> 1) ^ waddr_bin;

    end
end


always @(posedge rclk or negedge rrrstn) begin
    if (!rrrstn) begin
        raddr_bin <= 0;
        rptr_gray <= 0;
    end else begin
        if (rinc && !rempty) begin
            raddr_bin <= raddr_bin + 1;
        end
        rptr_gray <= (raddr_bin >> 1) ^ raddr_bin;

    end
end


always @(posedge wclk) begin
    wptr_gray_sync1 <= rptr_gray;
    wptr_gray_sync2 <= wptr_gray_sync1;
end


always @(posedge rclk) begin
    rptr_gray_sync1 <= wptr_gray;
    rptr_gray_sync2 <= rptr_gray_sync1;
end


assign rempty = (rptr_gray == rptr_gray_sync2);
assign wfull = ((wptr_gray[ADDR_WIDTH-1:ADDR_WIDTH-2] != rptr_gray_sync2[ADDR_WIDTH-1:ADDR_WIDTH-2]) &&
                (wptr_gray[ADDR_WIDTH-3:0] == rptr_gray_sync2[ADDR_WIDTH-3:0]));

endmodule

