module parallel2serial (
    input clk,
    input rst_n,
    input [3:0] d,
    output reg valid_out,
    output reg dout
);

reg [3:0] data_reg;
reg [1:0] cnt;
reg state;


always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= 0;
        data_reg <= 4'b0;
        cnt <= 2'b0;
        valid_out <= 0;
        dout <= 0;
    end else begin
        case (state)
            0: begin 
                if (cnt == 2'b11) begin
                    data_reg <= d;
                    state <= 1;
                    cnt <= 2'b0;
                    valid_out <= 1;
                end else begin
                    cnt <= cnt + 1;
                end
                dout <= 0;
            end
            1: begin 
                if (cnt == 2'b11) begin
                    state <= 0;
                    cnt <= 2'b0;
                    valid_out <= 0;
                end else begin
                    cnt <= cnt + 1;
                end
                case (cnt)
                    2'b00: dout <= data_reg[3];
                    2'b01: dout <= data_reg[2];
                    2'b10: dout <= data_reg[1];
                    2'b11: dout <= data_reg[0];
                endcase
            end
        endcase
    end
end

endmodule

