module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

    reg [7:0] stored_dividend_abs, stored_divisor_abs;
    reg stored_sign, dividend_sign, divisor_sign;
    reg [15:0] shift_reg;
    reg [3:0] cnt;
    reg [7:0] neg_divisor;

    always @(posedge clk) begin
        if (rst) begin
            res_valid <= 0;
            shift_reg <= 0;
            cnt <= 0;
            stored_dividend_abs <= 0;
            stored_divisor_abs <= 0;
            stored_sign <= 0;
            dividend_sign <= 0;
            divisor_sign <= 0;
            result <= 0;
            neg_divisor <= 0;
        end else begin
            if (res_valid) begin
                res_valid <= 0;
            end else if (opn_valid && !res_valid) begin

                if (sign) begin
                    dividend_sign <= dividend[7];
                    divisor_sign <= divisor[7];
                    stored_dividend_abs <= dividend[7] ? (-dividend) : dividend;
                    stored_divisor_abs <= divisor[7] ? (-divisor) : divisor;
                end else begin
                    dividend_sign <= 0;
                    divisor_sign <= 0;
                    stored_dividend_abs <= dividend;
                    stored_divisor_abs <= divisor;
                end
                stored_sign <= sign;

                shift_reg <= {stored_dividend_abs, 8'b0} << 1;
                neg_divisor <= -stored_divisor_abs;
                cnt <= 1;
            end else if (cnt > 0 && cnt <= 8) begin
                if (cnt == 8) begin

                    if (stored_sign) begin

                        reg [7:0] adj_quotient = (dividend_sign ^ divisor_sign) ? (~shift_reg[7:0] + 1) : shift_reg[7:0];
                        reg [7:0] adj_remainder = dividend_sign ? (~shift_reg[15:8] + 1) : shift_reg[15:8];
                        result <= {adj_remainder, adj_quotient};
                    end else begin
                        result <= {shift_reg[15:8], shift_reg[7:0]};
                    end
                    res_valid <= 1;
                    cnt <= 0;
                end else begin

                    reg [7:0] upper = shift_reg[15:8];
                    reg [8:0] temp_sub = {1'b0, upper} + {1'b0, neg_divisor};
                    if (temp_sub[8]) begin
                        shift_reg <= {temp_sub[7:0], shift_reg[7:0], 1'b1};
                    end else begin
                        shift_reg <= {upper, shift_reg[7:0], 1'b0};
                    end
                    cnt <= cnt + 1;
                end
            end
        end
    end

endmodule

