module div_16bit (
    input [15:0] A,
    input [7:0] B,
    output reg [15:0] result,
    output reg [15:0] odd
);

reg [15:0] a_reg;
reg [7:0] b_reg;

always @(*) begin
    a_reg = A;
    b_reg = B;
end

always @(*) begin
    reg [15:0] quotient;
    reg [15:0] remainder;
    reg [7:0] divisor;

    divisor = b_reg;
    remainder = 16'b0;
    quotient = 16'b0;

    for (int i = 15;
 i >= 0;
 i = i - 1) begin

        remainder = {remainder[14:0], a_reg[i]};

        if (remainder >= {8'b0, divisor}) begin
            remainder = remainder - {8'b0, divisor};
            quotient[i] = 1'b1;
        end else begin
            quotient[i] = 1'b0;
        end
    end

    result = quotient;
    odd = remainder;
end

endmodule

