module fixed_point_adder #(
    parameter Q = 8,    
    parameter N = 16    
) (
    input [N-1:0] a,
    input [N-1:0] b,
    output reg [N-1:0] c
);

    wire sign_a = a[N-1];
    wire sign_b = b[N-1];
    wire [N-1:0] abs_a = sign_a ? (~a + 1) : a;
    wire [N-1:0] abs_b = sign_b ? (~b + 1) : b;
    reg [N-1:0] res;

    always @(*) begin
        if (sign_a == sign_b) begin

            res = abs_a + abs_b;
            if (res[N-1]) begin

                res = {1'b0, {(N-1){1'b1}}};
            end
        end else begin

            if (abs_a > abs_b) begin
                res = abs_a - abs_b;
                res[N-1] = sign_a;
            end else if (abs_b > abs_a) begin
                res = abs_b - abs_a;
                res[N-1] = sign_b;
            end else begin
                res = 0;
            end
        end
        c = res;
    end

endmodule

