module fixed_point_subtractor #(
    parameter Q = 4,
    parameter N = 8
) (
    input [N-1:0] a,
    input [N-1:0] b,
    output [N-1:0] c
);
    reg [N-1:0] res;
    reg a_sign, b_sign;
    reg [N-2:0] a_mag, b_mag;

    always @* begin
        a_sign = a[N-1];
        b_sign = b[N-1];
        a_mag = a[N-2:0];
        b_mag = b[N-2:0];

        if (a_sign == b_sign) begin

            if (a_mag >= b_mag) begin
                res = {a_sign, a_mag - b_mag};
            end else begin
                res = {a_sign, b_mag - a_mag};
            end
        end else begin

            if (a_sign == 0) begin

                if (a_mag >= b_mag) begin
                    res = {1'b0, a_mag - b_mag};
                end else begin
                    res = {1'b1, b_mag - a_mag};
                end
            end else begin

                if (a_mag >= b_mag) begin
                    res = {1'b1, a_mag - b_mag};
                end else begin
                    res = {1'b0, b_mag - a_mag};
                end
            end
        end


        if (res[N-2:0] == 0) begin
            res = {1'b0, {(N-1){1'b0}}};
        end
    end

    assign c = res;

endmodule

