module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z = 0
);

    reg [2:0] counter;
    reg a_sign, b_sign, z_sign;
    reg [7:0] a_exponent, b_exponent, z_exponent;
    reg [22:0] a_mantissa, b_mantissa;
    reg [23:0] mantissa_a, mantissa_b;
    reg [49:0] product;

    reg guard, round, sticky;
    reg [24:0] rounded_mantissa;

    always @(posedge clk) begin
        if (rst) begin
            counter <= 0;
            z <= 0;
            a_sign <= 0;
            b_sign <= 0;
            a_exponent <= 0;
            b_exponent <= 0;
            a_mantissa <= 0;
            b_mantissa <= 0;
            mantissa_a <= 0;
            mantissa_b <= 0;
            product <= 0;
            guard <= 0;
            round <= 0;
            sticky <= 0;
            rounded_mantissa <= 0;
            z_sign <= 0;
            z_exponent <= 0;
        end else begin
            case (counter)
                0: begin

                    a_sign <= a[31];
                    b_sign <= b[31];
                    a_exponent <= a[30:23];
                    b_exponent <= b[30:23];
                    a_mantissa <= a[22:0];
                    b_mantissa <= b[22:0];


                    if (a_exponent == 8'hff || b_exponent == 8'hff) begin

                        z <= 32'h7FC00000;
                        counter <= 0;
                    end else if (a_exponent == 0 || b_exponent == 0) begin

                        z <= 32'h0;
                        counter <= 0;
                    end else begin
                        counter <= 1;
                    end
                end

                1: begin

                    mantissa_a <= (a_exponent != 0) ? {1'b1, a_mantissa} : {1'b0, a_mantissa};
                    mantissa_b <= (b_exponent != 0) ? {1'b1, b_mantissa} : {1'b0, b_mantissa};


                    product <= mantissa_a * mantissa_b;


                    z_exponent <= a_exponent + b_exponent - 8'd127;

                    counter <= 2;
                end

                2: begin

                    if (product[47]) begin

                        product <= product >> 1;
                        z_exponent <= z_exponent + 1;
                    end


                    guard <= product[46];
                    round <= product[45];
                    sticky <= |product[44:0];
                    rounded_mantissa <= {1'b0, product[46:1]};


                    counter <= 3;
                end

                3: begin

                    if (guard && (round || sticky)) begin
                        rounded_mantissa <= rounded_mantissa + 1;
                    end


                    if (rounded_mantissa[24]) begin
                        rounded_mantissa <= 25'b0;
                        z_exponent <= z_exponent + 1;
                    end


                    z_sign <= a_sign ^ b_sign;
                    counter <= 4;
                end

                4: begin

                    if (z_exponent >= 8'hff) begin
                        z <= {z_sign, 8'hff, 23'b0};

                    end else if (z_exponent == 0) begin
                        z <= {z_sign, 31'b0};

                    end else begin
                        z <= {z_sign, z_exponent[7:0], rounded_mantissa[22:0]};
                    end

                    counter <= 0;
                end

                default: counter <= 0;
            endcase
        end
    end

endmodule

