    input CLK,
    input RST,
    input IN,
    output reg MATCH
);

reg [2:0] current_state, next_state;


parameter S0 = 3'b000,
          S1 = 3'b001,
          S2 = 3'b010,
          S3 = 3'b011,
          S4 = 3'b100,
          S5 = 3'b101;


always @(posedge CLK) begin
    if (RST)
        current_state <= S0;
    else
        current_state <= next_state;
end


always @(*) begin
    case (current_state)
        S0: next_state = IN ? S1 : S0;
        S1: next_state = IN ? S1 : S2;
        S2: next_state = IN ? S1 : S3;
        S3: next_state = IN ? S4 : S3;
        S4: next_state = IN ? S5 : S3;
        S5: next_state = IN ? S1 : S2;
        default: next_state = S0;
    endcase
end


always @(*) begin
    if (RST)
        MATCH = 0;
    else begin
        case (current_state)
            S4: MATCH = IN;
            default: MATCH = 0;
        endcase
    end
end

endmodule

