module parallel2serial (
    input clk,
    input rst_n,
    input [3:0] d,
    output reg valid_out,
    output reg dout
);

reg [1:0] cnt;
reg [3:0] data_reg;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        data_reg <= 4'b0;
        cnt <= 2'b0;
        valid_out <= 0;
        dout <= 0;
    end else begin
        if (valid_out) begin
            if (cnt == 3) begin
                data_reg <= d;
                valid_out <= 0;
                cnt <= 0;
            end else begin
                cnt <= cnt + 1;
                data_reg <= {data_reg[2:0], 1'b0};
                dout <= data_reg[3];
            end
        end else begin
            data_reg <= d;
            valid_out <= 1;
            cnt <= 0;
            dout <= d[3];
        end
    end
end

