module traffic_light (
    input rst_n,
    input clk,
    input pass_request,
    output [7:0] clock,
    output reg red,
    output reg yellow,
    output reg green
);

reg [7:0] cnt;
reg [1:0] state, next_state;
reg pass_req;

parameter GREEN = 0;
parameter YELLOW = 1;
parameter RED = 2;


always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        pass_req <= 0;
    end else begin
        pass_req <= pass_request;
    end
end


always @(*) begin
    case (state)
        GREEN: begin
            next_state = (cnt == 0) ? YELLOW : GREEN;
        end
        YELLOW: begin
            next_state = (cnt == 0) ? RED : YELLOW;
        end
        RED: begin
            next_state = (cnt == 0) ? GREEN : RED;
        end
        default: next_state = GREEN;
    endcase
end


always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= GREEN;
        cnt <= 60;
    end else begin
        state <= next_state;


        if (state == GREEN) begin
            if (pass_request && !pass_req) begin
                if (cnt > 10) cnt <= 10;
            end else begin
                cnt <= cnt - 1;
            end
        end else begin
            cnt <= cnt - 1;
        end


        if (next_state != state) begin
            case (next_state)
                GREEN: cnt <= 60;
                YELLOW: cnt <= 5;
                RED: cnt <= 10;
                default: cnt <= 60;
            endcase
        end
    end
end


always @(*) begin
    red = 0;
    yellow = 0;
    green = 0;
    case (state)
        GREEN: green = 1;
        YELLOW: yellow = 1;
        RED: red = 1;
        default: ;
    endcase
end

assign clock = cnt;

endmodule

