module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

    reg [7:0] dividend_abs;
    reg [7:0] divisor_abs;
    reg [7:0] quotient;
    reg [7:0] remainder;
    reg [15:0] shift_reg;
    reg [3:0] cnt;
    reg [15:0] NEG_DIVISOR;
    reg [1:0] state;

    localparam IDLE = 2'b00;
    localparam PROCESSING = 2'b01;
    localparam DONE = 2'b10;

    always @(posedge clk) begin
        if (rst) begin
            state <= IDLE;
            res_valid <= 0;
            result <= 0;
            quotient <= 0;
            remainder <= 0;
            shift_reg <= 0;
            cnt <= 0;
            NEG_DIVISOR <= 0;
            dividend_abs <= 0;
            divisor_abs <= 0;
        end else begin
            case (state)
                IDLE: begin
                    if (opn_valid) begin

                        dividend_abs = sign ? (dividend[7] ? -dividend : dividend) : dividend;
                        divisor_abs = sign ? (divisor[7] ? -divisor : divisor) : divisor;


                        shift_reg <= {7'b0, dividend_abs, 1'b0};


                        NEG_DIVISOR <= -{ {8{divisor_abs[7]}}, divisor_abs };


                        cnt <= 1;


                        quotient <= 0;
                        remainder <= 0;

                        state <= PROCESSING;
                    end
                end

                PROCESSING: begin
                    if (cnt == 8) begin

                        state <= DONE;
                        res_valid <= 1;


                        result <= {remainder, quotient};


                        if (sign) begin
                            if (quotient[7] ^ dividend[7] ^ divisor[7]) begin
                                result[7:0] <= -result[7:0];
                            end
                            if (remainder[7] ^ dividend[7]) begin
                                result[15:8] <= -result[15:8];
                            end
                        end
                    end else begin

                        if (cnt >= 1 && cnt <= 8) begin

                            if ({8'b0, remainder} >= NEG_DIVISOR) begin
                                remainder <= {8'b0, remainder} - NEG_DIVISOR;
                                quotient <= {quotient[6:0], 1'b1};
                            end else begin
                                quotient <= {quotient[6:0], 1'b0};
                            end


                            remainder <= remainder << 1;
                            quotient <= quotient << 1;

                            cnt <= cnt + 1;
                        end
                    end
                end

                DONE: begin
                    if (res_valid) begin
                        res_valid <= 0;
                        state <= IDLE;
                    end
                end
            endcase
        end
    end

endmodule

