module fixed_point_adder #(parameter Q, N) (
    input [N-1:0] a,
    input [N-1:0] b,
    output [N-1:0] c
);

    reg [N-1:0] res;

    always @(*) begin

        wire sign_a = a[N-1];
        wire sign_b = b[N-1];


        wire [N-2:0] abs_a = a[N-2:0];
        wire [N-2:0] abs_b = b[N-2:0];


        if (sign_a == sign_b) begin

            wire [N:0] sum_abs = {1'b0, abs_a} + {1'b0, abs_b};

            if (sum_abs > ((1 << (N-1)) - 1)) begin

                if (sign_a)
                    res = {1'b1, {(N-1){1'b0}}};

                else
                    res = {1'b0, {(N-1){1'b1}}};

            end else begin

                res = {sign_a, sum_abs[N-2:0]};
            end
        end

        else begin
            if (abs_a > abs_b) begin
                res = {sign_a, abs_a - abs_b};
            end else if (abs_b > abs_a) begin
                res = {sign_b, abs_b - abs_a};
            end else begin

                res = {1'b0, {(N-1){1'b0}}};
            end
        end
    end

    assign c = res;

endmodule

