module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);

    reg [2:0] counter;
    reg [23:0] a_mantissa, b_mantissa;
    reg [8:0] a_exponent, b_exponent;

    reg a_sign, b_sign;
    reg [47:0] product;
    reg guard_bit, round_bit, sticky;
    reg [23:0] rounded_mantissa;
    reg [8:0] final_exponent;
    reg final_sign;

    localparam INIT = 0;
    localparam PROCESS = 1;
    localparam SPECIAL = 2;
    localparam MULTIPLY = 3;
    localparam NORMALIZE = 4;
    localparam ROUND = 5;
    localparam ADJUST = 6;
    localparam FINAL = 7;

    always @(posedge clk) begin
        if (rst) begin
            counter <= INIT;
            z <= 32'd0;
        end else begin
            case (counter)
                INIT: begin
                    counter <= PROCESS;
                end
                PROCESS: begin
                    a_sign <= a[31];
                    b_sign <= b[31];
                    a_exponent <= {1'b0, a[30:23]};
                    b_exponent <= {1'b0, b[30:23]};
                    a_mantissa <= (a[30:23] == 8'd0) ? {1'b0, a[22:0]} : {1'b1, a[22:0]};
                    b_mantissa <= (b[30:23] == 8'd0) ? {1'b0, b[22:0]} : {1'b1, b[22:0]};
                    counter <= SPECIAL;
                end
                SPECIAL: begin
                    if ((a_exponent == 9'h1FF && a_mantissa != 0) || (b_exponent == 9'h1FF && b_mantissa != 0)) begin
                        z <= {a_sign ^ b_sign, 8'hFF, 23'h1};
                        counter <= FINAL;
                    end else if ((a_exponent == 9'h1FF && a_mantissa == 0) || (b_exponent == 9'h1FF && b_mantissa == 0)) begin
                        if ((a_exponent == 9'h1FF && a_mantissa == 0) && (b_exponent == 9'h1FF && b_mantissa == 0)) begin
                            z <= {a_sign ^ b_sign, 8'hFF, 23'h1};
                        end else begin
                            z <= {a_sign ^ b_sign, 8'hFF, 23'h0};
                        end
                        counter <= FINAL;
                    end else if ((a_exponent == 9'h1FF && a_mantissa == 0) || (b_exponent == 9'h1FF && b_mantissa == 0)) begin
                        z <= {a_sign ^ b_sign, 8'h0, 23'h0};
                        counter <= FINAL;
                    end else begin
                        counter <= MULTIPLY;
                    end
                end
                MULTIPLY: begin
                    product <= a_mantissa * b_mantissa;
                    counter <= NORMALIZE;
                end
                NORMALIZE: begin
                    if (product[47]) begin
                        product <= {1'b0, product[47:1]};
                        final_exponent <= a_exponent + b_exponent + 9'd1 - 9'd127;
                    end else begin
                        product <= product;
                        final_exponent <= a_exponent + b_exponent - 9'd127;
                    end
                    counter <= ROUND;
                end
                ROUND: begin
                    guard_bit <= product[22];
                    round_bit <= product[21];
                    sticky <= |product[20:0];
                    if (guard_bit && (round_bit || sticky)) begin
                        rounded_mantissa <= product[23:1] + 24'h1;
                    end else begin
                        rounded_mantissa <= product[23:1];
                    end
                    final_sign <= a_sign ^ b_sign;
                    counter <= ADJUST;
                end
                ADJUST: begin
                    if (rounded_mantissa[23]) begin
                        rounded_mantissa <= rounded_mantissa >> 1;
                        final_exponent <= final_exponent + 1;
                    end
                    counter <= FINAL;
                end
                FINAL: begin
                    if (final_exponent[8]) begin
                        z <= {final_sign, 8'hFF, 23'h0};
                    end else if (final_exponent == 0 && rounded_mantissa == 0) begin
                        z <= {final_sign, 8'h0, 23'h0};
                    end else begin
                        z <= {final_sign, final_exponent[7:0], rounded_mantissa[22:0]};
                    end
                    counter <= INIT;
                end
                default: counter <= INIT;
            endcase
        end
    end

endmodule

