module dual_port_RAM #(
    parameter DEPTH = 16,
    parameter WIDTH = 8
) (
    input wclk,
    input wenc,
    input [$clog2(DEPTH)-1:0] waddr,
    input [WIDTH-1:0] wdata,

    input rclk,
    input renc,
    input [$clog2(DEPTH)-1:0] raddr,
    output reg [WIDTH-1:0] rdata
);

reg [WIDTH-1:0] RAM_MEM [0:DEPTH-1];

always @(posedge wclk) begin
    if (wenc) RAM_MEM[waddr] <= wdata;
end

always @(posedge rclk) begin
    if (renc) rdata <= RAM_MEM[raddr];
end

endmodule

module asyn_fifo #(
    parameter WIDTH = 8,
    parameter DEPTH = 16
) (
    input wclk,
    input wrstn,
    input winc,
    input [WIDTH-1:0] wdata,
    output reg wfull,

    input rclk,
    input rrstn,
    input rinc,
    output reg rempty,
    output [WIDTH-1:0] rdata
);

localparam N = $clog2(DEPTH);
localparam PTR_WIDTH = N + 1;


dual_port_RAM #(.DEPTH(DEPTH), .WIDTH(WIDTH)) ram (
    .wclk(wclk),
    .wenc(wen),
    .waddr(waddr_bin[N-1:0]),
    .wdata(wdata),
    .rclk(rclk),
    .renc(ren),
    .raddr(raddr_bin[N-1:0]),
    .rdata(rdata)
);


reg [PTR_WIDTH-1:0] wptr_bin;
wire [PTR_WIDTH-1:0] wptr_gray = (wptr_bin >> 1) ^ wptr_bin;
wire wen = winc && !wfull;

always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) wptr_bin <= 0;
    else if (wen) wptr_bin <= wptr_bin + 1;
end


reg [PTR_WIDTH-1:0] rptr_bin;
wire [PTR_WIDTH-1:0] rptr_gray = (rptr_bin >> 1) ^ rptr_bin;
wire ren = rinc && !rempty;

always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) rptr_bin <= 0;
    else if (ren) rptr_bin <= rptr_bin + 1;
end


reg [PTR_WIDTH-1:0] rptr_gray_sync1, rptr_gray_sync2;
reg [PTR_WIDTH-1:0] wptr_gray_sync1, wptr_gray_sync2;

always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) {rptr_gray_sync1, rptr_gray_sync2} <= 0;
    else {rptr_gray_sync1, rptr_gray_sync2} <= {rptr_gray_sync2, rptr_gray};
end

always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) {wptr_gray_sync1, wptr_gray_sync2} <= 0;
    else {wptr_gray_sync1, wptr_gray_sync2} <= {wptr_gray_sync2, wptr_gray};
end


wire [PTR_WIDTH-1:0] rptr_bin_sync = gray2bin(rptr_gray_sync2);
wire [PTR_WIDTH-1:0] expected_wptr_gray = bin2gray(rptr_bin_sync + DEPTH);
wire full_condition = (wptr_gray == expected_wptr_gray);

always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) wfull <= 0;
    else wfull <= full_condition;
end

always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) rempty <= 1;
    else rempty <= (rptr_gray == wptr_gray_sync2);
end


wire [N-1:0] waddr_bin = wptr_bin[N-1:0];
wire [N-1:0] raddr_bin = rptr_bin[N-1:0];


function [PTR_WIDTH-1:0] bin2gray(input [PTR_WIDTH-1:0] bin);
    bin2gray = bin ^ (bin >> 1);
endfunction

function [PTR_WIDTH-1:0] gray2bin(input [PTR_WIDTH-1:0] gray);
    reg [PTR_WIDTH-1:0] bin;
    integer i;
    begin
        bin[PTR_WIDTH-1] = gray[PTR_WIDTH-1];
        for (i = PTR_WIDTH-2;
 i >= 0;
 i = i - 1)
            bin[i] = bin[i+1] ^ gray[i];
        gray2bin = bin;
    end
endfunction

endmodule

