module LIFObuffer (
    input [3:0] dataIn,
    input RW,
    input EN,
    input Rst,
    input Clk,
    output reg EMPTY,
    output reg FULL,
    output reg [3:0] dataOut
);

    reg [3:0] stack_mem [0:3];
    reg [2:0] SP;

    always @(posedge Clk) begin
        if (Rst) begin
            SP <= 3'b100;

            EMPTY <= 1;
            FULL <= 0;
            stack_mem[0] <= 0;
            stack_mem[1] <= 0;
            stack_mem[2] <= 0;
            stack_mem[3] <= 0;
        end
        else if (EN) begin
            if (!FULL) begin
                if (!RW) begin 
                    if (SP < 4) begin
                        stack_mem[SP] <= dataIn;
                        SP <= SP - 1;
                    end
                end
                else begin 
                    if (SP > 0) begin
                        dataOut <= stack_mem[SP-1];
                        stack_mem[SP-1] <= 0;

                        SP <= SP + 1;
                    end
                end
            end
        end
    end


    always @(*) begin
        EMPTY = (SP == 4);
        FULL = (SP == 0);
    end

endmodule

