module parallel2serial (
    input clk,
    input rst_n,
    input [3:0] d,
    output reg valid_out,
    output reg dout
);

    reg [3:0] data_reg;
    reg [1:0] cnt;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            data_reg <= 4'b0;
            cnt <= 2'b0;
            valid_out <= 1'b0;
            dout <= 1'b0;
        end
        else begin
            if (valid_out) begin
                if (cnt == 2'b11) begin

                    data_reg <= d;
                    cnt <= 2'b0;
                    dout <= d[3];
                end
                else begin

                    data_reg <= data_reg << 1;
                    cnt <= cnt + 1;
                    dout <= data_reg[2];
                end
            end
            else begin

                data_reg <= d;
                cnt <= 2'b0;
                dout <= d[3];
                valid_out <= 1'b1;
            end
        end
    end

endmodule

