module pulse_detect (
    input clk,
    input rst_n,
    input data_in,
    output data_out
);

reg [1:0] state;

parameter IDLE = 2'b00,
          STATE1 = 2'b01,
          STATE2 = 2'b10;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
    end
    else begin
        case (state)
            IDLE: state <= (data_in == 0) ? STATE1 : IDLE;
            STATE1: state <= (data_in == 1) ? STATE2 : IDLE;
            STATE2: state <= (data_in == 0) ? IDLE : IDLE;
            default: state <= IDLE;
        endcase
    end
end

assign data_out = (state == STATE2) && (data_in == 0);

endmodule

