module traffic_light (
    input clk,
    input rst_n,
    input pass_request,
    output [7:0] clock,
    output red,
    output yellow,
    output green
);

    parameter idle = 2'b00;
    parameter s1_red = 2'b01;
    parameter s2_yellow = 2'b10;
    parameter s3_green = 2'b11;

    reg [1:0] state;
    reg [7:0] cnt;
    reg p_red, p_yellow, p_green;
    reg p_green_prev, p_yellow_prev, p_red_prev;


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= idle;
            cnt <= 10;
        end else begin
            case (state)
                idle: state <= s1_red;
                s1_red: begin
                    if (cnt == 3) begin
                        state <= s3_green;
                        cnt <= 60;
                    end else cnt <= cnt - 1;
                end
                s3_green: begin
                    if (cnt == 3) begin
                        state <= s2_yellow;
                        cnt <= 5;
                    end else cnt <= cnt - 1;
                end
                s2_yellow: begin
                    if (cnt == 3) begin
                        state <= s1_red;
                        cnt <= 10;
                    end else cnt <= cnt - 1;
                end
                default: state <= idle;
            endcase
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            p_red <= 0;
            p_yellow <= 0;
            p_green <= 0;
        end else begin
            p_red <= (state == s1_red);
            p_green <= (state == s3_green);
            p_yellow <= (state == s2_yellow);

            if (state == s1_red) cnt <= 3;
            else if (state == s2_yellow) cnt <= 3;
            else if (state == s3_green) cnt <= 3;

            if (pass_request && p_green && (cnt > 10)) begin
                cnt <= 10;
            end
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            p_green_prev <= 0;
            p_yellow_prev <= 0;
            p_red_prev <= 0;
        end else begin
            p_green_prev <= p_green;
            p_yellow_prev <= p_yellow;
            p_red_prev <= p_red;
        end
    end

    assign clock = cnt;
    assign red = p_red;
    assign yellow = p_yellow;
    assign green = p_green;

endmodule

