module alu (
    input [31:0] a,
    input [31:0] b,
    input [5:0] aluc,
    output [31:0] r,
    output zero,
    output carry,
    output negative,
    output overflow,
    output flag
);

    reg [31:0] res;
    reg carry_reg;
    reg overflow_reg;
    reg flag_reg;

    assign r = res;
    assign zero = (res == 32'b0);
    assign negative = res[31];
    assign carry = carry_reg;
    assign overflow = overflow_reg;
    assign flag = flag_reg;

    always @(*) begin
        res = 32'b0;
        carry_reg = 1'b0;
        overflow_reg = 1'b0;
        flag_reg = 1'b0;

        case (aluc)
            6'b100000: begin 
                {carry_reg, res} = {1'b0, a} + {1'b0, b};
                overflow_reg = (a[31] == b[31]) && (res[31] != a[31]);
            end
            6'b100001: begin 
                {carry_reg, res} = {1'b0, a} + {1'b0, b};
            end
            6'b100010: begin 
                {carry_reg, res} = {1'b0, a} - {1'b0, b};
                overflow_reg = (a[31] != b[31]) && (res[31] != a[31]);
            end
            6'b100011: begin 
                {carry_reg, res} = {1'b0, a} - {1'b0, b};
            end
            6'b100100: begin 
                res = a & b;
            end
            6'b100101: begin 
                res = a | b;
            end
            6'b100110: begin 
                res = a ^ b;
            end
            6'b100111: begin 
                res = ~(a | b);
            end
            6'b101010: begin 
                res = ($signed(a) < $signed(b)) ? 32'd1 : 32'd0;
                flag_reg = ($signed(a) < $signed(b)) ? 1'b1 : 1'b0;
            end
            6'b101011: begin 
                res = (a < b) ? 32'd1 : 32'd0;
                flag_reg = (a < b) ? 1'b1 : 1'b0;
            end
            6'b000000: begin 
                res = a << b[4:0];
            end
            6'b000010: begin 
                res = a >> b[4:0];
            end
            6'b000011: begin 
                res = $signed(a) >>> b[4:0];
            end
            6'b000100: begin 
                res = b << a[4:0];
            end
            6'b000110: begin 
                res = b >> a[4:0];
            end
            6'b000111: begin 
                res = $signed(b) >>> a[4:0];
            end
            6'b001111: begin 
                res = {a[15:0], 16'b0};
            end
            default: begin 
                res = 32'bz;
            end
        endcase
    end

endmodule

