module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

    reg [1:0] state;
    reg [3:0] counter;
    reg [15:0] SR;
    reg [7:0] absolute_dividend;
    reg [7:0] absolute_divisor;
    reg [7:0] NEG_DIVISOR;

    localparam IDLE = 2'b00;
    localparam DIVIDE = 2'b01;

    always @(posedge clk) begin
        if (rst) begin
            state <= IDLE;
            res_valid <= 0;
            SR <= 16'b0;
            counter <= 0;
        end else begin
            case (state)
                IDLE: begin
                    res_valid <= 0;
                    if (opn_valid) begin

                        absolute_dividend <= sign ? (dividend[7] ? -dividend : dividend) : dividend;
                        absolute_divisor <= sign ? (divisor[7] ? -divisor : divisor) : divisor;
                        NEG_DIVISOR <= -absolute_divisor;


                        SR <= {absolute_dividend, 8'b0} << 1;
                        counter <= 0;
                        state <= DIVIDE;
                    end
                end

                DIVIDE: begin
                    if (counter < 8) begin

                        reg [8:0] remainder_part = SR[15:8];
                        reg [8:0] sub_result;
                        reg carry_out;


                        {carry_out, sub_result} = remainder_part - {{1{NEG_DIVISOR[7]}}, NEG_DIVISOR};

                        if (carry_out) begin

                            SR <= {sub_result, SR[7:1], 1'b1};
                        end else begin

                            SR <= {remainder_part, SR[7:1], 1'b0};
                        end

                        counter <= counter + 1;
                    end else begin

                        reg [7:0] final_remainder = SR[15:8];
                        reg [7:0] final_quotient = SR[7:0];


                        if (sign) begin
                            if (dividend[7]) final_remainder = -final_remainder;
                            if (dividend[7] ^ divisor[7]) final_quotient = -final_quotient;
                        end

                        result <= {final_remainder, final_quotient};
                        res_valid <= 1;
                        state <= IDLE;
                    end
                end
            endcase
        end
    end

endmodule

