module fixed_point_adder #(parameter Q=4, N=8) (
    input [N-1:0] a,
    input [N-1:0] b,
    output reg [N-1:0] c
);

    reg [N-1:0] res;

    always @(*) begin
        if (a[N-1] == b[N-1]) begin

            res = a + b;
        end else begin

            reg [N-1:0] abs_a, abs_b;
            reg [N-1:0] magnitude;
            reg sign;


            abs_a = a[N-1] ? (~a + 1) : a;
            abs_b = b[N-1] ? (~b + 1) : b;

            if (abs_a > abs_b) begin
                magnitude = (abs_a - abs_b);
                sign = 0;
            end else if (abs_b > abs_a) begin
                magnitude = (abs_b - abs_a);
                sign = 1;
            end else begin

                magnitude = 0;
                sign = 0;
            end


            res = {sign, magnitude[N-2:0]};
        end


        c = res;
    end

endmodule

