module fixed_point_subtractor #(
    parameter Q = 4,  
    parameter N = 8   
) (
    input [N-1:0] a,
    input [N-1:0] b,
    output [N-1:0] c
);

    wire sign_a = a[N-1];
    wire sign_b = b[N-1];
    wire same_sign = (sign_a == sign_b);


    wire [N-1:0] sub_result = a - b;


    wire [N-1:0] a_abs = sign_a ? (~a + 1) : a;
    wire [N-1:0] b_abs = sign_b ? (~b + 1) : b;
    wire [N-1:0] sum_abs = a_abs + b_abs;
    wire        a_larger = (a_abs > b_abs);


    wire        diff_sign = a_larger ? 1'b0 : 1'b1;


    wire        result_zero = (sub_result == 0) || ((sum_abs == 0) && !same_sign);


    reg [N-1:0] res;
    always @(*) begin
        if (result_zero) res = 0;
        else if (same_sign) res = sub_result;
        else res = {diff_sign, sum_abs[N-2:0]};
    end

    assign c = res;

endmodule

