module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);

reg [2:0] counter;
reg a_sign, b_sign, z_sign;
reg [7:0] a_exponent, b_exponent, z_exponent;
reg [22:0] a_mantissa, b_mantissa;
reg [47:0] product;
reg [23:0] product_mantissa;
reg guard_bit, round_bit, sticky;
reg [4:0] exponent_sum;
reg [23:0] mantissa_result;


wire a_zero = (a_exponent == 0) && (a_mantissa == 0);
wire b_zero = (b_exponent == 0) && (b_mantissa == 0);
wire a_inf = (a_exponent == 8'hff) && (a_mantissa == 0);
wire b_inf = (b_exponent == 8'hff) && (b_mantissa == 0);
wire a_nan = (a_exponent == 8'hff) && (a_mantissa != 0);
wire b_nan = (b_exponent == 8'hff) && (b_mantissa != 0);
wire is_nan = a_nan || b_nan || (a_inf && b_zero) || (b_inf && a_zero);
wire is_inf = (a_inf || b_inf) && !is_nan;
wire is_zero = a_zero || b_zero;

always @(posedge clk) begin
    if (rst) begin
        counter <= 0;
        z <= 0;
        a_sign <= 0;
        b_sign <= 0;
        z_sign <= 0;
        a_exponent <= 0;
        b_exponent <= 0;
        a_mantissa <= 0;
        b_mantissa <= 0;
        product <= 0;
        product_mantissa <= 0;
        guard_bit <= 0;
        round_bit <= 0;
        sticky <= 0;
        exponent_sum <= 0;
        mantissa_result <= 0;
    end else begin
        case (counter)
            0: begin

                a_sign <= a[31];
                b_sign <= b[31];
                a_exponent <= a[30:23];
                b_exponent <= b[30:23];
                a_mantissa <= (a_exponent == 0) ? {1'b0, a[22:0]} : {1'b1, a[22:0]};
                b_mantissa <= (b_exponent == 0) ? {1'b0, b[22:0]} : {1'b1, b[22:0]};
                counter <= counter + 1;
            end
            1: begin

                if (is_nan) begin
                    z <= {a_sign ^ b_sign, 8'hff, 23'h1};

                    counter <= 0;
                end else if (is_inf) begin
                    z <= {a_sign ^ b_sign, 8'hff, 23'h0};

                    counter <= 0;
                end else if (is_zero) begin
                    z <= {a_sign ^ b_sign, 23'h0, 31'h0};

                    counter <= 0;
                end else begin

                    exponent_sum <= (a_exponent + b_exponent - 8'd127);

                    product <= {1'b0, a_mantissa} * {1'b0, b_mantissa};
                    counter <= counter + 1;
                end
            end
            2: begin

                if (product[47]) begin

                    product_mantissa <= {product[46:24], 1'b0};
                    sticky <= |product[23:0];
                    round_bit <= product[23];
                    guard_bit <= product[24];
                end else if (product[46]) begin

                    product_mantissa <= {product[45:23], 2'b0};
                    sticky <= |product[22:0];
                    round_bit <= product[23];
                    guard_bit <= product[24];
                end else begin

                    product_mantissa <= product[47:24];
                    sticky <= 1'b0;
                    round_bit <= 1'b0;
                    guard_bit <= 1'b0;
                end
                counter <= counter + 1;
            end
            3: begin

                if (guard_bit & (round_bit | sticky)) begin
                    if (product_mantissa[23]) begin
                        mantissa_result <= product_mantissa + 1;
                        if (mantissa_result[24]) begin
                            z_exponent <= exponent_sum + 2;
                            mantissa_result <= 24'h1;
                        end else begin
                            z_exponent <= exponent_sum + 1;
                        end
                    end else begin
                        mantissa_result <= product_mantissa + 1;
                        z_exponent <= exponent_sum;
                    end
                end else begin
                    mantissa_result <= product_mantissa;
                    z_exponent <= exponent_sum;
                end
                counter <= counter + 1;
            end
            4: begin

                if (z_exponent >= 8'hff) begin

                    z <= {a_sign ^ b_sign, 8'hff, 23'h0};
                end else if (z_exponent == 0) begin

                    z <= {a_sign ^ b_sign, 8'h0, mantissa_result[22:0]};
                end else begin

                    z <= {a_sign ^ b_sign, z_exponent, mantissa_result[22:0]};
                end
                counter <= 0;
            end
        endcase
    end
end

endmodule

