module asyn_fifo #(
    parameter WIDTH = 8,
    parameter DEPTH = 16
) (
    input wclk,
    input wrstn,
    input winc,
    input [WIDTH-1:0] wdata,
    output wfull,

    input rclk,
    input rrstn,
    input rinc,
    output rempty,

    output [WIDTH-1:0] rdata
);

localparam ADDR_BITS = $clog2(DEPTH);
localparam PTR_BITS = ADDR_BITS;


reg [ADDR_BITS-1:0] wptr_bin = 0;
reg [PTR_BITS-1:0] wptr_gray;


reg [ADDR_BITS-1:0] rptr_bin = 0;
reg [PTR_BITS-1:0] rptr_gray;


reg [PTR_BITS-1:0] wptr_gray_synced0, wptr_gray_synced1;
reg [PTR_BITS-1:0] rptr_gray_synced0, rptr_gray_synced1;


function [ADDR_BITS-1:0] gray_to_bin;
    input [PTR_BITS-1:0] gray;
    integer i;
    begin
        gray_to_bin[ADDR_BITS-1] = gray[ADDR_BITS-1];
        for (i = ADDR_BITS-2;
 i >= 0;
 i = i - 1)
            gray_to_bin[i] = gray_to_bin[i+1] ^ gray[i];
    end
endfunction


always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) begin
        {rptr_gray_synced1, rptr_gray_synced0} <= 0;
    end else begin
        rptr_gray_synced1 <= rptr_gray;
        rptr_gray_synced0 <= rptr_gray_synced1;
    end
end


always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) begin
        {wptr_gray_synced1, wptr_gray_synced0} <= 0;
    end else begin
        wptr_gray_synced1 <= wptr_gray;
        wptr_gray_synced0 <= wptr_gray_synced1;
    end
end


always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) begin
        wptr_bin <= 0;
        wptr_gray <= 0;
    end else if (winc && !wfull) begin
        wptr_bin <= wptr_bin + 1;
        wptr_gray <= (wptr_bin >> 1) ^ wptr_bin;
    end
end


always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) begin
        rptr_bin <= 0;
        rptr_gray <= 0;
    end else if (rinc && !rempty) begin
        rptr_bin <= rptr_bin + 1;
        rptr_gray <= (rptr_bin >> 1) ^ rptr_bin;
    end
end


assign rempty = (rptr_gray_synced0 == wptr_gray_synced0);
assign wfull = (wptr_gray == {~rptr_gray_synced0[PTR_BITS-1:PTR_BITS-2], rptr_gray_synced0[PTR_BITS-3:0]});


dual_port_RAM #(
    .DEPTH(DEPTH),
    .WIDTH(WIDTH)
) ram (
    .wclk(wclk),
    .wenc(winc && !wfull),
    .waddr(wptr_bin),
    .wdata(wdata),
    .rclk(rclk),
    .renc(rinc && !rempty),
    .raddr(gray_to_bin(rptr_gray_synced0)),
    .rdata(rdata)
);

endmodule

