module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

    reg [7:0] abs_dividend, abs_divisor;
    reg [7:0] neg_divisor;
    reg [16:0] SR;

    reg [3:0] cnt;
    reg start_cnt;
    reg [7:0] quotient;
    reg [7:0] remainder;
    reg sign_quotient;
    reg sign_remainder;

    always @(posedge clk) begin
        if (rst) begin
            res_valid <= 0;
            SR <= 0;
            cnt <= 0;
            start_cnt <= 0;
            quotient <= 0;
            remainder <= 0;
            sign_quotient <= 0;
            sign_remainder <= 0;
            abs_dividend <= 0;
            abs_divisor <= 0;
            neg_divisor <= 0;
            result <= 0;
        end else begin
            if (opn_valid && !res_valid) begin

                if (sign) begin
                    abs_dividend <= dividend[7] ? -dividend : dividend;
                    abs_divisor <= divisor[7] ? -divisor : divisor;
                    sign_quotient <= dividend[7] ^ divisor[7];
                    sign_remainder <= dividend[7];
                end else begin
                    abs_dividend <= dividend;
                    abs_divisor <= divisor;
                    sign_quotient <= 0;
                    sign_remainder <= 0;
                end


                SR <= ({abs_dividend, 8'b0} << 1);
                neg_divisor <= -abs_divisor;

                cnt <= 1;
                start_cnt <= 1;
                res_valid <= 0;
                quotient <= 0;
                remainder <= 0;
            end else if (start_cnt) begin
                if (cnt <= 8) begin
                    if (cnt == 8) begin

                        if (SR[16:8] >= neg_divisor) begin
                            remainder <= SR[16:8] - neg_divisor;
                            quotient <= {quotient[6:0], 1'b1};
                        end else begin
                            remainder <= SR[16:8];
                            quotient <= {quotient[6:0], 1'b0};
                        end
                        cnt <= cnt + 1;
                    end else begin

                        SR <= SR << 1;
                        if (SR[16:8] >= neg_divisor) begin
                            remainder <= SR[16:8] - neg_divisor;
                            quotient <= {quotient[6:0], 1'b1};
                        end else begin
                            remainder <= SR[16:8];
                            quotient <= {quotient[6:0], 1'b0};
                        end
                        cnt <= cnt + 1;
                    end
                end else begin

                    start_cnt <= 0;
                    cnt <= 0;
                    if (sign) begin
                        if (sign_quotient) quotient <= -quotient;
                        if (sign_remainder) remainder <= -remainder;
                    end
                    result <= {remainder, quotient};
                    res_valid <= 1;
                end
            end else if (res_valid) begin
                res_valid <= 0;
            end
        end
    end
endmodule

