module fixed_point_adder #(parameter Q = 2, N = 4) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output reg [N-1:0] c
);

    wire a_sign = a[N-1];
    wire b_sign = b[N-1];


    wire [N-2:0] a_mag = a_sign ? (~a[N-2:0] + 1) : a[N-2:0];
    wire [N-2:0] b_mag = b_sign ? (~b[N-2:0] + 1) : b[N-2:0];


    wire [N-2:0] max_mag = (a_mag > b_mag) ? a_mag : ((b_mag > a_mag) ? b_mag : 0);
    wire [N-2:0] min_mag = (a_mag > b_mag) ? b_mag : ((b_mag > a_mag) ? a_mag : 0);
    wire mag_equal = (a_mag == b_mag);
    wire [N-2:0] result_mag = (max_mag - min_mag);
    wire sign_gt = (a_mag > b_mag) ? a_sign : b_sign;


    wire [N-1:0] result = (a_sign == b_sign) ? 
        (a + b) : 
        (mag_equal ? 0 : {sign_gt, result_mag});

    always @(*) begin
        c = result;
    end

endmodule

