module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);

    reg [2:0] counter;
    reg a_sign, b_sign, z_sign;
    reg [8:0] a_exponent, b_exponent, z_exponent;
    reg [23:0] a_mantissa, b_mantissa;
    reg [47:0] product;
    reg guard, round, sticky;
    reg [22:0] z_mantissa;

    always @(posedge clk) begin
        if (rst) begin
            counter <= 0;
            z <= 0;
        end else begin
            case (counter)
                0: begin

                    a_sign <= a[31];
                    b_sign <= b[31];
                    a_exponent <= a[30:23];
                    b_exponent <= b[30:23];
                    a_mantissa <= (a[30:23] == 0) ? {1'b0, a[22:0]} : {1'b1, a[22:0]};
                    b_mantissa <= (b[30:23] == 0) ? {1'b0, b[22:0]} : {1'b1, b[22:0]};

                    if ((a[30:23] == 8'hFF) || (b[30:23] == 8'hFF)) begin
                        if (a[30:23] == 8'hFF && b[30:23] == 8'hFF) begin
                            z <= {1'b0, 8'hFF, 23'h1};
                        end else if (a[30:23] == 8'hFF) begin
                            z <= {a_sign ^ b_sign, 8'hFF, 23'b0};
                        end else begin
                            z <= {a_sign ^ b_sign, 8'hFF, 23'b0};
                        end
                        counter <= 0;
                    end else if (a == 0 || b == 0) begin
                        z <= (a == 0 && b == 0) ? {1'b0, 8'hFF, 23'h1} : 
                            (a == 0) ? {b_sign, 31'b0} : {a_sign, 31'b0};
                        counter <= 0;
                    end else begin
                        counter <= 1;
                    end
                end

                1: begin
                    product = a_mantissa * b_mantissa;
                    counter <= 2;
                end

                2: begin

                    if (product[47]) begin
                        product = product >> 1;
                        z_exponent = {1'b0, a_exponent} + {1'b0, b_exponent} - 9'd254 + 9'd1;
                    end else begin
                        z_exponent = {1'b0, a_exponent} + {1'b0, b_exponent} - 9'd254;
                    end
                    counter <= 3;
                end

                3: begin

                    z_mantissa = product[46:24];
                    guard = product[23];
                    round = product[22];
                    sticky = |product[21:0];

                    if (guard && (round || sticky || z_mantissa[0])) begin
                        if (z_mantissa == 23'h0) begin
                            z_exponent <= z_exponent + 9'd1;
                        end else begin
                            z_mantissa <= z_mantissa + 1;
                        end
                    end


                    if (z_exponent[8] || z_exponent[7:0] == 0) begin
                        z <= {a_sign ^ b_sign, 8'hFF, 23'b0};
                    end else begin
                        z <= {a_sign ^ b_sign, z_exponent[7:0], z_mantissa};
                    end
                    counter <= 0;
                end

                default: counter <= 0;
            endcase
        end
    end

endmodule

