                    if (data_in == 0) begin
                        state <= IDLE;
                        data_out <= 1;
                    end else begin
                        state <= IDLE;
                        data_out <= 0;
                    end
                end
                default: begin
                    state <= IDLE;
                    data_out <= 0;
                end
            endcase
        end
    end

