                if (pass_request && (cnt > 10)) begin
                    cnt <= 10;
                end else if (cnt == 0) begin
                    state <= s2_yellow;
                    cnt <= 5;
                end else begin
                    cnt <= cnt - 1;
                end
            end
            s2_yellow: begin
                if (cnt == 0) begin
                    state <= s1_red;
                    cnt <= 10;
                end else begin
                    cnt <= cnt - 1;
