module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

reg [7:0] quotient;
reg [7:0] remainder;
reg [15:0] SR;

reg [3:0] cnt;
reg start_cnt;
reg sign_reg;
reg sign_quotient;
reg sign_remainder;
reg [7:0] divisor_abs;

always @(posedge clk) begin
    if (rst) begin
        res_valid <= 0;
        cnt <= 0;
        start_cnt <= 0;
        SR <= 16'b0;
        quotient <= 8'b0;
        remainder <= 8'b0;
        sign_reg <= 0;
        sign_quotient <= 0;
        sign_remainder <= 0;
        divisor_abs <= 8'b0;
    end else begin
        if (opn_valid && !res_valid) begin

            if (sign) begin
                divisor_abs <= (divisor[7]) ? -divisor : divisor;
                sign_quotient <= (dividend[7] ^ divisor[7]);
                sign_remainder <= dividend[7];
                sign_reg <= 1;
            end else begin
                divisor_abs <= divisor;
                sign_quotient <= 0;
                sign_remainder <= 0;
                sign_reg <= 0;
            end

            if (sign) begin
                remainder <= (dividend[7]) ? -dividend : dividend;
            end else begin
                remainder <= dividend;
            end
            quotient <= 8'b0;
            SR <= {remainder, quotient} << 1;
            cnt <= 1;
            start_cnt <= 1;
            res_valid <= 0;
        end else if (start_cnt) begin
            if (cnt == 8) begin

                quotient <= SR[7:0];
                remainder <= SR[15:8];
                if (sign_reg) begin
                    if (sign_quotient) quotient <= -quotient;
                    if (sign_remainder) remainder <= -remainder;
                end
                result <= {remainder, quotient};
                res_valid <= 1;
                start_cnt <= 0;
                cnt <= 0;
            end else begin

                if (SR[15:8] >= divisor_abs) begin
                    SR[15:8] <= SR[15:8] - divisor_abs;
                    quotient <= {quotient[6:0], 1'b1};
                end else begin
                    quotient <= {quotient[6:0], 1'b0};
                end
                SR <= {SR[15:8], quotient} << 1;
                cnt <= cnt + 1;
            end
        end else begin
            res_valid <= 0;
        end
    end
end

endmodule

