module div_16bit (
    input [15:0] A,
    input [7:0] B,
    output reg [15:0] result,
    output reg [15:0] odd
);

    reg [15:0] a_reg;
    reg [7:0] b_reg;

    always @(*) begin
        a_reg = A;
        b_reg = B;
    end

    always @(*) begin
        integer i;
        reg [15:0] quotient;
        reg [15:0] remainder;

        quotient = 16'b0;
        remainder = 16'b0;

        for (i = 15;
 i >= 0;
 i = i - 1) begin
            remainder = (remainder << 1) | ((a_reg >> i) & 1);
            if (remainder >= {8'b0, b_reg}) begin
                quotient[i] = 1;
                remainder = remainder - {8'b0, b_reg};
            end else begin
                quotient[i] = 0;
            end
        end

        result = quotient;
        odd = remainder;
    end

endmodule

