module fixed_point_adder #(parameter Q=4, N=8) (
    input [N-1:0] a,
    input [N-1:0] b,
    output reg [N-1:0] c
);

    always @(*) begin
        reg a_sign, b_sign;
        reg [N-1:0] mag_a, mag_b;
        reg [N:0] sum_mags;
        reg [N-1:0] diff;

        a_sign = a[N-1];
        b_sign = b[N-1];


        mag_a = a_sign ? (~a + 1) : a;
        mag_b = b_sign ? (~b + 1) : b;

        if (a_sign == b_sign) begin

            sum_mags = mag_a + mag_b;
            c = {a_sign, sum_mags[N-1:0]};
        end else begin

            if (mag_a > mag_b) begin
                diff = mag_a - mag_b;
                c = {1'b0, diff[N-1:0]};
            end else if (mag_b > mag_a) begin
                diff = mag_b - mag_a;
                c = {1'b1, diff[N-1:0]};
            end else begin

                c = {1'b0, {N-1{1'b0}}};
            end
        end
    end

endmodule

