module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);

    reg [2:0] counter;
    reg a_sign, b_sign, z_sign;
    reg [7:0] a_exponent, b_exponent, z_exponent;
    reg [22:0] a_mantissa, b_mantissa;
    reg [22:0] a_mantissa_ext, b_mantissa_ext;
    reg [49:0] product;
    reg [23:0] product_mantissa;
    reg guard_bit, round_bit, sticky;
    reg [23:0] rounded_mantissa;
    reg [8:0] sum_exponent;

    always @(posedge clk) begin
        if (rst) begin
            counter <= 3'b0;
            z <= 32'b0;
            a_sign <= 0;
            b_sign <= 0;
            z_sign <= 0;
            a_exponent <= 0;
            b_exponent <= 0;
            a_mantissa <= 0;
            b_mantissa <= 0;
            a_mantissa_ext <= 24'b0;
            b_mantissa_ext <= 24'b0;
            product <= 49'b0;
            product_mantissa <= 24'b0;
            guard_bit <= 0;
            round_bit <= 0;
            sticky <= 0;
            rounded_mantissa <= 24'b0;
            sum_exponent <= 9'b0;
        end else begin
            case (counter)
                3'b000: begin

                    a_sign <= a[31];
                    b_sign <= b[31];
                    a_exponent <= a[30:23];
                    b_exponent <= b[30:23];
                    a_mantissa <= a[22:0];
                    b_mantissa <= b[22:0];


                    if ((a_exponent == 8'hff && a_mantissa != 0) || 
                        (b_exponent == 8'hff && b_mantissa != 0)) begin

                        z <= {a_sign ^ b_sign, 8'hff, 23'h000001};
                        counter <= 3'b111;
                    end else if ((a_exponent == 8'hff) || (b_exponent == 8'hff)) begin

                        if ((a_exponent == 8'hff && a_mantissa == 0) || 
                            (b_exponent == 8'hff && b_mantissa == 0)) begin
                            if ((a_exponent == 8'hff && a_mantissa == 0) && 
                                (b_exponent == 8'hff && b_mantissa == 0)) begin

                                z <= {a_sign ^ b_sign, 8'hff, 23'b0};
                            end else if ((a_exponent == 8'hff && a_mantissa == 0) || 
                                        (b_exponent == 8'hff && b_mantissa == 0)) begin

                                z <= {a_sign ^ b_sign, 8'hff, 23'b0};
                            end else begin

                                z <= {1'b0, 8'hff, 23'h000001};
                            end
                        end else if (a_exponent == 0 && a_mantissa == 0 && b_exponent == 0 && b_mantissa == 0) begin

                            z <= {a_sign ^ b_sign, 8'b0, 23'b0};
                        end
                        counter <= 3'b111;
                    end else if (a_exponent == 0 && a_mantissa == 0 && b_exponent == 0 && b_mantissa == 0) begin

                        z <= {a_sign ^ b_sign, 8'b0, 23'b0};
                        counter <= 3'b111;
                    end else begin

                        counter <= 3'b001;
                    end
                end

                3'b001: begin

                    a_mantissa_ext <= (a_exponent == 0) ? {1'b0, a_mantissa} : {1'b1, a_mantissa};
                    b_mantissa_ext <= (b_exponent == 0) ? {1'b0, b_mantissa} : {1'b1, b_mantissa};
                    product <= {1'b0, a_mantissa_ext} * {1'b0, b_mantissa_ext};
                    sum_exponent <= (a_exponent - 8'd127) + (b_exponent - 8'd127);
                    counter <= 3'b010;
                end

                3'b010: begin

                    if (product[48] == 1'b1) begin
                        product_mantissa <= product[47:24];
                        guard_bit <= product[23];
                        round_bit <= product[22];
                        sticky <= |product[21:0];
                        sum_exponent <= sum_exponent + 9'd1;
                    end else if (product[47] == 1'b1) begin
                        product_mantissa <= product[46:23];
                        guard_bit <= product[22];
                        round_bit <= product[21];
                        sticky <= |product[20:0];
