module LIFObuffer (
    input wire [3:0] dataIn,
    input wire RW,
    input wire EN,
    input wire Rst,
    input wire Clk,
    output wire EMPTY,
    output wire FULL,
    output reg [3:0] dataOut
);

    reg [3:0] stack_mem [0:3];
    reg [2:0] SP;

    initial begin
        SP = 3'd4;
        dataOut = 0;
        stack_mem[0] = 0;
        stack_mem[1] = 0;
        stack_mem[2] = 0;
        stack_mem[3] = 0;
    end

    always @(posedge Clk) begin
        if (Rst) begin
            SP <= 3'd4;
            stack_mem[0] <= 0;
            stack_mem[1] <= 0;
            stack_mem[2] <= 0;
            stack_mem[3] <= 0;
            dataOut <= 0;
        end
        else if (EN) begin
            if (RW) begin 
                if (!EMPTY) begin
                    dataOut <= stack_mem[SP];
                    stack_mem[SP] <= 0;
                    SP <= SP + 1;
                end
            end
            else begin 
                if (!FULL) begin
                    stack_mem[SP - 1] <= dataIn;
                    SP <= SP - 1;
                end
            end
        end
    end

    assign EMPTY = (SP == 3'd4);
    assign FULL = (SP == 3'd0);

endmodule

