module pulse_detect (
    input clk,
    input rst_n,
    input data_in,
    output reg data_out
);


    parameter S0 = 2'b00,
              S1 = 2'b01,
              S2 = 2'b10;

    reg [1:0] current_state, next_state;


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            current_state <= S0;
            data_out <= 0;
        end else begin
            current_state <= next_state;
        end
    end


    always @(*) begin
        case (current_state)
            S0: begin
                if (data_in) begin
                    next_state = S1;
                    data_out = 0;
                end else begin
                    next_state = S0;
                    data_out = 0;
                end
            end
            S1: begin
                if (!data_in) begin
                    next_state = S2;
                    data_out = 1;
                end else begin
                    next_state = S1;
                    data_out = 0;
                end
            end
            S2: begin
                next_state = S0;
                data_out = 0;
            end
            default: begin
                next_state = S0;
                data_out = 0;
            end
        endcase
    end

endmodule

