module traffic_light (
    input rst_n,
    input clk,
    input pass_request,
    output reg [7:0] clock,
    output reg red,
    output reg yellow,
    output reg green
);


parameter idle = 2'b00, s1_red = 2'b01, s2_yellow = 2'b10, s3_green = 2'b11;
reg [1:0] state, next_state;


reg p_red, p_yellow, p_green;


reg [7:0] cnt;


always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= idle;
        cnt <= 10;
    end else begin
        state <= next_state;

        if (state == s3_green) begin
            if (pass_request && (cnt > 10)) cnt <= 10;
            else if (cnt > 0) cnt <= cnt - 1;
        end else if (state == s2_yellow) begin
            if (cnt > 0) cnt <= cnt - 1;
        end else if (state == s1_red) begin
            if (cnt > 0) cnt <= cnt - 1;
        end else begin
            cnt <= cnt;
        end
    end
end


always @(*) begin
    case (state)
        idle: next_state = s1_red;
        s1_red: next_state = (cnt == 0) ? s3_green : s1_red;
        s3_green: next_state = (cnt == 0) ? s2_yellow : s3_green;
        s2_yellow: next_state = (cnt == 0) ? s1_red : s2_yellow;
        default: next_state = idle;
    endcase
end


always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        red <= 0;
        yellow <= 0;
        green <= 0;
        p_red <= 0;
        p_yellow <= 0;
        p_green <= 0;
    end else begin
        p_red <= red;
        p_yellow <= yellow;
        p_green <= green;
        case (next_state)
            s1_red: begin
                red <= 1;
                yellow <= 0;
                green <= 0;
            end
            s3_green: begin
                red <= 0;
                yellow <= 0;
                green <= 1;
            end
            s2_yellow: begin
                red <= 0;
                yellow <= 1;
                green <= 0;
            end
            default: begin
                red <= 0;
                yellow <= 0;
                green <= 0;
            end
        endcase
    end
end


always @(posedge clk) begin
    clock <= cnt;
end


always @(posedge clk) begin
    if (state == s1_red && cnt == 0) begin
        cnt <= 10;
    end else if (state == s3_green && cnt == 0) begin
        cnt <= 60;
    end else if (state == s2_yellow && cnt == 0) begin
        cnt <= 5;
    end
end

endmodule

