module width_8to16 (
    input clk,
    input rst_n,
    input valid_in,
    input [7:0] data_in,
    output reg [15:0] data_out,
    output reg valid_out
);

    reg [7:0] data_lock;
    reg has_data;

    reg [15:0] combined_data;
    reg combined_valid;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            data_lock <= 8'b0;
            has_data <= 1'b0;
            combined_data <= 16'b0;
            combined_valid <= 1'b0;
        end else begin
            combined_valid <= 1'b0;
            if (has_data && valid_in) begin
                combined_data <= {data_lock, data_in};
                combined_valid <= 1'b1;
                has_data <= 1'b0;
            end else if (valid_in) begin
                data_lock <= data_in;
                has_data <= 1'b1;
            end
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            data_out <= 16'b0;
            valid_out <= 1'b0;
        end else begin
            data_out <= combined_data;
            valid_out <= combined_valid;
        end
    end

endmodule

