    input RST,
    output reg [5:0] Hours,
    output reg [5:0] Mins,
    output reg [5:0] Secs
);

always @(posedge CLK or posedge RST) begin
    if (RST) begin
        Secs <= 0;
    end else begin
        Secs <= (Secs == 59) ? 0 : Secs + 1;
    end
end

always @(posedge CLK or posedge RST) begin
    if (RST) begin
        Mins <= 0;
    end else begin
        if (Mins == 59 && Secs == 59)
            Mins <= 0;
        else if (Secs == 59)
            Mins <= Mins + 1;
        else
            Mins <= Mins;
    end
end

always @(posedge CLK or posedge RST) begin
    if (RST) begin
        Hours <= 0;
    end else begin
        if (Hours == 23 && Mins == 59 && Secs == 59)
            Hours <= 0;
        else if (Mins == 59 && Secs == 59)
            Hours <= Hours + 1;
