module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

reg [16:0] shift_reg;

reg [3:0] cnt;

reg start_cnt;

reg [7:0] abs_dividend, abs_divisor;

reg original_sign;

reg original_sign_div;



wire [7:0] NEG_DIVISOR = -abs_divisor;

always @(posedge clk) begin
    if (rst) begin
        res_valid <= 0;
        shift_reg <= 0;
        cnt <= 0;
        start_cnt <= 0;
        abs_dividend <= 0;
        abs_divisor <= 0;
        original_sign <= 0;
        original_sign_div <= 0;
    end else begin
        if (opn_valid && !res_valid) begin

            if (sign) begin
                original_sign <= dividend[7] ^ divisor[7];

                original_sign_div <= divisor[7];

                abs_dividend <= dividend[7] ? (~dividend + 1) : dividend;
                abs_divisor <= divisor[7] ? (~divisor + 1) : divisor;
            end else begin
                original_sign <= 0;
                abs_dividend <= dividend;
                abs_divisor <= divisor;
            end


            shift_reg <= { {9{abs_dividend[7]}}, abs_dividend } << 1;
            cnt <= 0;
            start_cnt <= 1;
            res_valid <= 0;
        end else if (start_cnt) begin
            if (cnt < 8) begin

                wire [8:0] temp = shift_reg[16:8] + (original_sign_div ? NEG_DIVISOR : 9'b0);
                wire [7:0] new_quotient = shift_reg[8:1] << 1 | (temp[8] ? 1'b0 : 1'b1);
                shift_reg <= { temp, new_quotient };
                cnt <= cnt + 1;
            end else begin

                reg [7:0] quotient = shift_reg[8:1];
                reg [7:0] remainder = {1'b0, shift_reg[16:9]};
                if (sign) begin
                    if (original_sign) quotient <= ~quotient + 1;

                    remainder <= sign ? (~remainder + 1) : remainder;

                end
                result <= {remainder, quotient};
                start_cnt <= 0;
                res_valid <= 1;
            end
        end


        if (opn_valid && res_valid) res_valid <= 0;
    end
end

endmodule

