module div_16bit (
    input [15:0] A,
    input [7:0] B,
    output [15:0] result,
    output [15:0] odd
);

    reg [15:0] a_reg;
    reg [7:0] b_reg;
    reg [15:0] quotient;
    reg [15:0] remainder;


    always @(*) begin
        a_reg = A;
        b_reg = B;
    end


    always @(*) begin
        remainder = 0;
        quotient = 0;

        for (int i = 15;
 i >= 0;
 i = i - 1) begin
            reg [15:0] temp_remainder = {remainder[14:0], a_reg[i]};
            if (temp_remainder >= {8'b0, b_reg}) begin
                remainder = temp_remainder - {8'b0, b_reg};
                quotient[i] = 1'b1;
            end else begin
                remainder = temp_remainder;
                quotient[i] = 1'b0;
            end
        end
    end

    assign result = quotient;
    assign odd = remainder;

endmodule

