            if (!FULL) begin
                if (RW == 0) begin 
                    stack_mem[SP] <= dataIn;
                    SP <= SP + 1;
                end
            end
            if (!EMPTY) begin
                if (RW == 1) begin 
                    dataOut <= stack_mem[SP - 1];
                    stack_mem[SP - 1] <= 4'b0;
                    SP <= SP - 1;
                end
            end
        end
    end

