module pulse_detect (
    input clk,
    input rst_n,
    input data_in,
    output reg data_out = 0
);


    localparam IDLE = 2'b00;
    localparam RISE = 2'b01;
    localparam FALL = 2'b10;

    reg [1:0] state;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
        end else begin
            case (state)
                IDLE: begin
                    if (data_in) begin
                        state <= RISE;
                    end else begin
                        state <= IDLE;
                    end
                end
                RISE: begin
                    if (!data_in) begin
                        state <= FALL;
                    end else begin
                        state <= RISE;
                    end
                end
                FALL: begin
                    state <= IDLE;
                end
                default: begin
                    state <= IDLE;
                end
            endcase
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            data_out <= 0;
        end else begin
            case (state)
                FALL: data_out <= 1;
                default: data_out <= 0;
            endcase
        end
    end

endmodule

