module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

reg [7:0] abs_dividend;
reg [7:0] abs_divisor;
reg [7:0] neg_divisor;
reg [15:0] shift_reg;
reg [3:0] cnt;
reg start_cnt;

localparam IDLE = 0, BUSY = 1;
reg state;

always @(posedge clk) begin
    if (rst) begin
        state <= IDLE;
        res_valid <= 0;
        result <= 0;
        shift_reg <= 0;
        cnt <= 0;
        start_cnt <= 0;
        abs_dividend <= 0;
        abs_divisor <= 0;
        neg_divisor <= 0;
    end else begin
        case (state)
            IDLE: begin
                if (opn_valid && !res_valid) begin

                    if (sign) begin
                        abs_dividend <= dividend[7] ? -dividend : dividend;
                        abs_divisor <= divisor[7] ? -divisor : divisor;
                        neg_divisor <= -(divisor[7] ? -divisor : divisor);
                    end else begin
                        abs_dividend <= dividend;
                        abs_divisor <= divisor;
                        neg_divisor <= -divisor;
                    end

                    shift_reg <= {abs_dividend, 8'b0} << 1;
                    cnt <= 1;
                    start_cnt <= 1;
                    state <= BUSY;
                end
            end
            BUSY: begin
                if (start_cnt) begin
                    start_cnt <= 0;
                end else if (cnt < 8) begin

                    {shift_reg, neg_divisor} <= shift_reg - {9'b0, neg_divisor};

                    if (shift_reg[8]) begin
                        shift_reg <= {shift_reg[8:0], 1'b0};
                    end else begin
                        shift_reg <= {shift_reg[7:0], 1'b1};
                        cnt <= cnt + 1;
                    end
                end else if (cnt == 8) begin

                    shift_reg <= {shift_reg[15:9], 1'b0};

                    if (sign) begin
                        if (dividend[7] ^ divisor[7]) begin
                            shift_reg[15:8] <= -shift_reg[15:8];
                        end
                        if (dividend[7] ^ shift_reg[15:8][0]) begin
                            shift_reg[7:0] <= -shift_reg[7:0];
                        end
                    end
                    result <= {shift_reg[15:8], shift_reg[7:0]};
                    state <= IDLE;
                    res_valid <= 1;
                end else begin
                    res_valid <= 0;
                end
            end
        endcase
    end
end

endmodule

