module adder_bcd (
    input [3:0] A,
    input [3:0] B,
    input Cin,
    output [3:0] Sum,
    output Cout
);

    wire [4:0] sum_initial = A + B + Cin;
    wire correct = (sum_initial > 9) || (sum_initial[4]);

    wire [4:0] sum_corrected = sum_initial + (correct ? 5'd6 : 5'd0);

    assign Sum = sum_corrected[3:0];
