module fixed_point_adder #(parameter Q=2, N=4) (
    input [N-1:0] a,
    input [N-1:0] b,
    output [N-1:0] c
);

    reg [N-1:0] res;

    always @(*) begin
        if (a[N-1] == b[N-1]) begin
            res = a + b;
        end else begin
            if ($signed(a) > $signed(b)) begin
                res = $signed(a) - $signed(b);
            end else begin
                res = $signed(b) - $signed(a);
            end
        end
    end

    assign c = res;

endmodule

