module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z = 0
);

    reg [2:0] counter = 0;
    reg a_sign, b_sign, z_sign;
    reg [7:0] a_exponent, b_exponent, z_exponent;
    reg [23:0] a_mantissa, b_mantissa;
    reg [47:0] product;
    reg guard, round, sticky;

    always @(posedge clk) begin
        if (rst) begin
            counter <= 0;
            z <= 0;
        end else begin
            case (counter)
                0: begin

                    a_sign <= a[31];
                    b_sign <= b[31];
                    a_exponent <= a[30:23];
                    b_exponent <= b[30:23];
                    a_mantissa <= (a[30:23] == 0) ? {1'b0, a[22:0]} : {1'b1, a[22:0]};
                    b_mantissa <= (b[30:23] == 0) ? {1'b0, b[22:0]} : {1'b1, b[22:0]};
                    counter <= 1;
                end

                1: begin

                    if ((a_exponent == 8'hff && a_mantissa[22:0] != 0) ||
                        (b_exponent == 8'hff && b_mantissa[22:0] != 0)) begin
                        z <= {1'b0, 8'hff, 23'h1};

                    end else if ((a_exponent == 8'hff && a_mantissa[22:0] == 0) ||
                                (b_exponent == 8'hff && b_mantissa[22:0] == 0)) begin
                        if ((a_exponent == 8'hff && a_mantissa[22:0] == 0) && 
                            (b_mantissa[22:0] == 0)) begin
                            z <= {1'b0, 8'hff, 23'h1};

                        end else begin
                            z <= {a_sign ^ b_sign, 8'hff, 23'h0};

                        end
                    end else if ((a_exponent == 0 && a_mantissa[22:0] == 0) ||
                                (b_exponent == 0 && b_mantissa[22:0] == 0)) begin
                        z <= {a_sign ^ b_sign, 31'h0};

                    end else begin
                        product <= a_mantissa * b_mantissa;
                        counter <= 2;
                    end
                end

                2: begin

                    z_exponent <= a_exponent + b_exponent - 8'd127;
                    if (product[47]) begin
                        product <= product >> 1;
                        z_exponent <= z_exponent + 1;
                    end
                    counter <= 3;
                end

                3: begin

                    guard <= product[22];
                    round <= product[21];
                    sticky <= |product[20:0];
                    counter <= 4;
                end

                4: begin

                    if ((guard && (round || sticky)) || 
                        (guard && !round && !sticky && (product[23] % 2))) begin
                        if (product[46:24] == 23'h7fffff) begin
                            product[46:24] <= 23'h0;
                            z_exponent <= z_exponent + 1;
                        end else begin
                            product[46:24] <= product[46:24] + 1;
                        end
                    end
                    counter <= 5;
                end

                5: begin

                    z_sign <= a_sign ^ b_sign;
                    if (z_exponent >= 8'hff) begin
                        z <= {z_sign, 8'hff, 23'h0};

                    end else if (z_exponent == 0) begin
                        z <= {z_sign, 31'h0};

                    end else begin
                        z <= {z_sign, z_exponent, product[46:24]};
                    end
                    counter <= 0;
                end
