module asyn_fifo #(
    parameter DEPTH = 16,
    parameter WIDTH = 8
) (
    input wclk,
    input wrstn,
    input winc,
    input [WIDTH-1:0] wdata,
    input rclk,
    input rrstn,
    input rinc,
    output wfull,
    output rempty,
    output [WIDTH-1:0] rdata
);
    reg [4:0] waddr_bin;
    reg [3:0] wptr_gray;
    reg [4:0] raddr_bin;
    reg [3:0] rptr_gray;
    reg [3:0] rptr_gray_sync1, rptr_gray_sync2;
    reg [3:0] wptr_gray_sync1, wptr_gray_sync2;

    function [4:0] gray_to_bin;
        input [3:0] gray;
        reg [4:0] bin;
        begin
            bin[4] = gray[3];
            bin[3] = bin[4] ^ gray[2];
            bin[2] = bin[3] ^ gray[1];
            bin[1] = bin[2] ^ gray[0];
            bin[0] = bin[1] ^ 1'b0;
            gray_to_bin = bin;
        end
    endfunction

    wire [4:0] rptr_bin_sync = gray_to_bin(rptr_gray_sync2);
    wire [4:0] wptr_bin_sync = gray_to_bin(wptr_gray_sync2);
    wire full = (waddr_bin - rptr_bin_sync) >= DEPTH;
    wire empty = (raddr_bin == wptr_bin_sync);

    assign wfull = full;
    assign rempty = empty;


    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn) begin
            waddr_bin <= 0;
            wptr_gray <= 0;
            rptr_gray_sync1 <= 0;
            rptr_gray_sync2 <= 0;
        end else begin
            if (winc && !wfull) begin
                waddr_bin <= waddr_bin + 1;
            end
            wptr_gray <= waddr_bin ^ (waddr_bin >> 1);
            rptr_gray_sync1 <= rptr_gray;
            rptr_gray_sync2 <= rptr_gray_sync1;
        end
    end


    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn) begin
            raddr_bin <= 0;
            rptr_gray <= 0;
            wptr_gray_sync1 <= 0;
            wptr_gray_sync2 <= 0;
        end else begin
            if (rinc && !rempty) begin
                raddr_bin <= raddr_bin + 1;
            end
            rptr_gray <= raddr_bin ^ (raddr_bin >> 1);
            wptr_gray_sync1 <= wptr_gray;
            wptr_gray_sync2 <= wptr_gray_sync1;
        end
    end


    wire [3:0] waddr = waddr_bin[3:0];
    wire [3:0] raddr = raddr_bin[3:0];
    dual_port_RAM #(.DEPTH(DEPTH), .WIDTH(WIDTH)) ram (
        .wclk(wclk),
        .wenc(winc && !wfull),
        .waddr(waddr),
        .wdata(wdata),
        .rclk(rclk),
        .renc(rinc && !rempty),
        .raddr(raddr),
        .rdata(rdata)
    );

endmodule

