module pulse_detect (
    input clk,
    input rst_n,
    input data_in,
    output reg data_out
);


    localparam IDLE  = 2'b00;
    localparam STATE1 = 2'b01;
    localparam STATE2 = 2'b10;

    reg [1:0] current_state, next_state;


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            current_state <= IDLE;
        end else begin
            current_state <= next_state;
        end
    end


    always @(*) begin
        next_state = current_state;
        data_out = 0;

        case (current_state)
            IDLE: begin
                if (data_in == 0)
                    next_state = STATE1;
            end
            STATE1: begin
                if (data_in == 1)
                    next_state = STATE2;
                else
                    next_state = IDLE;
            end
            STATE2: begin
                data_out = (data_in == 0) ? 1 : 0;
                next_state = IDLE;
            end
            default: next_state = IDLE;
        endcase
    end

endmodule

