module traffic_light (
    input rst_n,
    input clk,
    input pass_request,
    output reg [7:0] clock,
    output reg red,
    output reg yellow,
    output reg green
);


    localparam idle     = 2'b00;
    localparam s1_red   = 2'b01;
    localparam s3_green = 2'b10;
    localparam s2_yellow= 2'b11;

    reg [1:0] state, next_state;
    reg [7:0] cnt, next_cnt;


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= idle;
            cnt <= 8'd10;
            {red, yellow, green} <= 3'b0;
        end else begin
            state <= next_state;
            cnt <= next_cnt;

            case (next_state)
                idle: {red, yellow, green} <= 3'b000;
                s1_red: {red, yellow, green} <= 3'b100;
                s3_green: {red, yellow, green} <= 3'b010;
                s2_yellow: {red, yellow, green} <= 3'b001;
                default: {red, yellow, green} <= 3'b000;
            endcase
        end
    end


    always @(*) begin
        next_state = state;
        next_cnt = cnt;
        if (!rst_n) begin
            next_state = idle;
            next_cnt = 8'd10;
        end else begin
            case (state)
                idle: begin
                    next_state = s1_red;
                    next_cnt = 8'd10;
                end
                s1_red: begin
                    if (cnt == 0) begin
                        next_state = s3_green;
                        next_cnt = 8'd60;
                    end else begin
                        next_cnt = cnt - 1;
                    end
                end
                s3_green: begin

                    if (pass_request && cnt > 8'd10) begin
                        next_cnt = 8'd10;
                    end else begin
                        next_cnt = cnt - 1;
                    end
                    if (next_cnt == 0) begin
                        next_state = s2_yellow;
                        next_cnt = 8'd5;
                    end
                end
                s2_yellow: begin
                    if (cnt == 0) begin
                        next_state = s1_red;
                        next_cnt = 8'd10;
                    end else begin
                        next_cnt = cnt - 1;
                    end
                end
                default: begin
                    next_state = idle;
                    next_cnt = 8'd0;
                end
            endcase
        end
    end

    assign clock = cnt;

endmodule

