module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

    reg [7:0] dividend_latch;
    reg [7:0] divisor_latch;
    reg sign_latch;
    reg [3:0] cnt;
    reg start;
    reg [15:0] sr;
    reg [7:0] neg_divisor;
    reg [7:0] quotient;
    reg [7:0] remainder;
    reg sign_quotient;
    reg sign_remainder;

    always @(posedge clk) begin
        if (rst) begin
            res_valid <= 0;
            result <= 0;
            cnt <= 0;
            start <= 0;
            sr <= 0;
            neg_divisor <= 0;
            quotient <= 0;
            remainder <= 0;
            sign_quotient <= 0;
            sign_remainder <= 0;
            dividend_latch <= 0;
            divisor_latch <= 0;
            sign_latch <= 0;
        end else begin
            if (!res_valid) begin
                if (opn_valid) begin

                    dividend_latch <= dividend;
                    divisor_latch <= divisor;
                    sign_latch <= sign;


                    if (sign) begin
                        remainder <= dividend[7] ? -dividend : dividend;
                        quotient <= divisor[7] ? -divisor : divisor;
                        sign_quotient <= dividend[7] ^ divisor[7];
                        sign_remainder <= dividend[7];
                    end else begin
                        remainder <= dividend;
                        quotient <= divisor;
                        sign_quotient <= 0;
                        sign_remainder <= 0;
                    end


                    sr <= {remainder, 1'b0} << 1;


                    neg_divisor <= -quotient;

                    cnt <= 1;
                    start <= 1;
                    res_valid <= 0;
                end else if (start) begin
                    if (cnt[3]) begin 

                        if (sign_remainder)
                            remainder <= -remainder;
                        if (sign_quotient)
                            quotient <= -quotient;


                        result <= {remainder, quotient};
                        res_valid <= 1;
                        start <= 0;
                        cnt <= 0;
                    end else begin

                        if (sr[15:8] >= neg_divisor) begin
                            sr[15:8] <= sr[15:8] - neg_divisor;
                            quotient <= (quotient << 1) | 1'b1;
                        end else begin
                            quotient <= quotient << 1;
                        end
                        sr <= sr << 1;
                        cnt <= cnt + 1;
                    end
                end
            end else begin
                res_valid <= 0;
            end
        end
    end

endmodule

