module multi_16bit (
    input clk,
    input rst_n,
    input start,
    input [15:0] ain,
    input [15:0] bin,
    output [31:0] yout,
    output done
);

    reg [4:0] i;
    reg [15:0] areg, breg;
    reg [31:0] yout_r;
    reg done_r;


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            i <= 5'b0;
        end else begin
            if (start) begin
                if (i < 17)
                    i <= i + 1;
                else
                    i <= 17;
            end else begin
                i <= 0;
            end
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            areg <= 16'b0;
            breg <= 16'b0;
            yout_r <= 32'b0;
        end else begin
            if (start) begin
                if (i == 0) begin
                    areg <= ain;
                    breg <= bin;
                end
                if (i >= 1 && i <= 16) begin
                    if (areg[i-1])
                        yout_r <= yout_r + ( {16'b0, breg} << (i-1) );
                end
            end
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            done_r <= 0;
        end else begin
            if (i == 16)
                done_r <= 1;
            else if (i == 17)
                done_r <= 0;

        end
    end

    assign yout = yout_r;
    assign done = done_r;

endmodule

