module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);

    reg [2:0] counter;
    reg a_sign, b_sign, z_sign;
    reg [7:0] a_exponent, b_exponent, z_exponent;
    reg [22:0] a_mantissa_in, b_mantissa_in;
    reg [23:0] a_mantissa, b_mantissa;
    reg [47:0] product;
    reg [23:0] z_mantissa;
    reg guard_bit, round_bit, sticky;
    reg [4:0] sticky_recompute;


    wire a_zero = (a_exponent == 0 && a_mantissa_in == 0);
    wire b_zero = (b_exponent == 0 && b_mantissa_in == 0);
    wire a_inf = (a_exponent == 8'hFF);
    wire b_inf = (b_exponent == 8'hFF);
    wire a_nan = (a_exponent == 8'hFF && a_mantissa_in != 0);
    wire b_nan = (b_exponent == 8'hFF && b_mantissa_in != 0);
    wire a_sign_bit = a[31];
    wire b_sign_bit = b[31];

    always @(posedge clk) begin
        if (rst) begin
            counter <= 0;
            z <= 0;
        end else begin
            case (counter)
                0: begin

                    a_sign <= a[31];
                    b_sign <= b[31];
                    a_exponent <= a[30:23];
                    b_exponent <= b[30:23];
                    a_mantissa_in <= a[22:0];
                    b_mantissa_in <= b[22:0];


                    if (a_nan || b_nan || 
                        (a_inf && b_zero) || (b_inf && a_zero)) begin
                        z_sign <= a_sign ^ b_sign;
                        z <= {a_sign ^ b_sign, 8'hFF, 23'h1};

                        counter <= 0;
                    end else if (a_zero || b_zero) begin
                        z_sign <= a_sign ^ b_sign;
                        z <= {a_sign ^ b_sign, 31'b0};
                        counter <= 0;
                    end else if (a_inf || b_inf) begin
                        z_sign <= a_sign ^ b_sign;
                        z <= {a_sign ^ b_sign, 8'hFF, 23'b0};
                        counter <= 0;
                    end else begin

                        a_mantissa <= (a_exponent == 0) ? {1'b0, a_mantissa_in} : {1'b1, a_mantissa_in};
                        b_mantissa <= (b_exponent == 0) ? {1'b0, b_mantissa_in} : {1'b1, b_mantissa_in};
                        product <= {24'b0, a_mantissa} * {24'b0, b_mantissa};
                        counter <= 1;
                    end
                end

                1: begin

                    if (product[47:46] >= 2'b10) begin
                        product <= {1'b0, product[47:1]};
                        z_exponent <= a_exponent + b_exponent - 8'd127 + 1;
                    end else begin
                        z_exponent <= a_exponent + b_exponent - 8'd127;
                    end
                    counter <= 2;
                end

                2: begin

                    guard_bit <= product[0];
                    round_bit <= product[1];
                    sticky = |product[63:2];
                    sticky_recompute = {product[4:0]};
                    sticky <= |sticky_recompute;


                    if (guard_bit && (round_bit || sticky)) begin
                        z_mantissa <= product[47:24] + 1;
                        if (z_mantissa[23]) begin
                            z_exponent <= z_exponent + 1;
                        end
                    end else if (guard_bit && !(round_bit || sticky)) begin

                        if (product[23]) begin
                            z_mantissa <= product[47:24] + 1;
                            if (z_mantissa[23]) begin
                                z_exponent <= z_exponent + 1;
                            end
                        end else begin
                            z_mantissa <= product[47:24];
                        end
                    end else begin
                        z_mantissa <= product[47:24];
                    end

                    counter <= 3;
                end

                3: begin

                    if (z_exponent >= 255) begin
                        z <= {z_sign, 8'hFF, 23'b0};

                    end else if (z_exponent == 0) begin

                        z <= {z_sign, 8'h0, z_mantissa[22:0]};
                    end else begin
                        z <= {z_sign, z_exponent, z_mantissa[22:0]};
                    end
                    counter <= 0;
                end

                default: counter <= 0;
            endcase
        end
    end

endmodule

