        case (current_state)
            IDLE: next_state = data_in ? S1 : IDLE;
            S1:   next_state = data_in ? IDLE : S2;
            S2:   next_state = data_in ? IDLE : S3;
            S3:   next_state = data_in ? S4 : IDLE;
            S4:   next_state = IDLE;
            default: next_state = IDLE;
        endcase
    end


    assign sequence_detected = (current_state == S4);

