            SP <= 3'b0;
            for (integer i = 0;
 i < 4;
 i = i + 1)
                stack_mem[i] <= 4'b0;
        end
        else begin
            if (RW) begin 
                if (SP != 0) begin
                    dataOut <= stack_mem[SP-1];
                    SP <= SP - 1;
                end
            end
            else begin 
                if (SP != 4) begin
                    stack_mem[SP] <= dataIn;
                    SP <= SP + 1;
                end
            end
        end
    end
end


assign EMPTY = (SP == 0);
assign FULL = (SP == 4);

