module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

    reg [7:0] dividend_reg, divisor_reg;
    reg sign_reg;
    reg [7:0] absolute_dividend, absolute_divisor;
    reg [8:0] NEG_DIVISOR;
    reg [15:0] SR;
    reg [3:0] cnt;
    reg start_cnt;

    reg [7:0] quotient;
    reg [7:0] remainder;
    reg quotient_sign;
    reg remainder_sign;

    always @(posedge clk) begin
        if (rst) begin
            res_valid <= 0;
            cnt <= 0;
            start_cnt <= 0;
            SR <= 0;
            dividend_reg <= 0;
            divisor_reg <= 0;
            sign_reg <= 0;
            absolute_dividend <= 0;
            absolute_divisor <= 0;
            NEG_DIVISOR <= 0;
            quotient <= 0;
            remainder <= 0;
            quotient_sign <= 0;
            remainder_sign <= 0;
            result <= 0;
        end else begin
            if (opn_valid && !res_valid && !start_cnt) begin
                dividend_reg <= dividend;
                divisor_reg <= divisor;
                sign_reg <= sign;


                absolute_dividend <= sign ? (dividend[7] ? -dividend : dividend) : dividend;
                absolute_divisor <= sign ? (divisor[7] ? -divisor : divisor) : divisor;


                quotient_sign <= (sign && (dividend[7] ^ divisor[7])) ? 1 : 0;
                remainder_sign <= sign ? dividend[7] : 0;


                SR <= {absolute_dividend, 8'b0} << 1;


                NEG_DIVISOR <= {1'b1, absolute_divisor} + 1;

                cnt <= 1;
                start_cnt <= 1;
                res_valid <= 0;
            end else if (start_cnt) begin
                if (cnt <= 8) begin
                    if (cnt == 8) begin

                        remainder <= remainder_sign ? -remainder : remainder;
                        quotient <= quotient_sign ? -quotient : quotient;

                        result <= {remainder, quotient};
                        res_valid <= 1;
                        start_cnt <= 0;
                    end else begin

                        {remainder, quotient} <= SR;


                        if (SR[15:8] >= NEG_DIVISOR[7:0]) begin
                            remainder <= SR[15:8] - NEG_DIVISOR[7:0];
                            quotient <= (quotient << 1) | 1'b1;
                        end else begin
                            quotient <= (quotient << 1) | 1'b0;
                        end

                        cnt <= cnt + 1;
                    end
                end
            end

            if (res_valid && !opn_valid) begin
                res_valid <= 0;
            end
        end
    end

endmodule

