module div_16bit (
    input [15:0] A,
    input [7:0] B,
    output reg [15:0] result,
    output reg [15:0] odd
);

reg [15:0] a_reg, b_reg;


always @(A or B) begin
    a_reg = A;
    b_reg = B;
end


always @(A or B) begin
    integer i;
    reg [15:0] temp_result;
    reg [15:0] remainder;
    reg [15:0] divisor;

    divisor = {8'b0, b_reg};

    temp_result = 0;
    remainder = 0;

    for (i = 15;
 i >= 0;
 i = i - 1) begin

        remainder = (remainder << 1) | ((a_reg >> i) & 1);
        if (remainder >= divisor) begin
            temp_result[i] = 1;
            remainder = remainder - divisor;
        end else begin
            temp_result[i] = 0;
        end
    end

    result = temp_result;
    odd = remainder;
end

endmodule

