module fixed_point_adder #(
    parameter Q = 4,
    parameter N = 8
) (
    input [N-1:0] a,
    input [N-1:0] b,
    output reg [N-1:0] c
);

always @(*) begin
    if (a[N-1] == b[N-1]) begin

        c = a + b;
    end else begin

        reg [N-1:0] a_mag, b_mag;
        a_mag = a[N-1] ? (~a + 1) : a;
        b_mag = b[N-1] ? (~b + 1) : b;

        if (a_mag > b_mag) begin
            c = a_mag - b_mag;
            c[N-1] = 0;

        end else if (b_mag > a_mag) begin
            c = b_mag - a_mag;
            c[N-1] = 1;

        end else begin
            c = 0;

        end
    end
end

endmodule

