module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);

    reg [2:0] counter;
    reg a_sign, b_sign, z_sign;
    reg [7:0] a_exponent, b_exponent, z_exponent;
    reg [23:0] a_mantissa, b_mantissa;
    reg [47:0] product;
    reg guard, round_bit, sticky;
    reg [22:0] z_mantissa;

    always @(posedge clk) begin
        if (rst) begin
            counter <= 3'b0;
            z <= 32'b0;
        end else begin
            case (counter)
                0: begin

                    a_sign <= a[31];
                    b_sign <= b[31];
                    a_exponent <= a[30:23];
                    b_exponent <= b[30:23];

                    a_mantissa <= (a[30:23] == 0) ? {1'b0, a[22:0]} : {1'b1, a[22:0]};
                    b_mantissa <= (b[30:23] == 0) ? {1'b0, b[22:0]} : {1'b1, b[22:0]};
                    counter <= counter + 1;
                end

                1: begin

                    if (a_exponent == 8'hff || b_exponent == 8'hff) begin

                        if (a_exponent == 8'hff && b_exponent == 8'hff) begin

                            z <= {a_sign ^ b_sign, 8'hff, 23'h1};
                        end else if (a_exponent == 8'hff) begin

                            if (b_mantissa == 0) z <= {a_sign ^ b_sign, 8'hff, 23'h1};
                            else z <= {a_sign ^ b_sign, 8'hff, 23'b0};
                        end else begin

                            if (a_mantissa == 0) z <= {a_sign ^ b_sign, 8'hff, 23'h1};
                            else z <= {a_sign ^ b_sign, 8'hff, 23'b0};
                        end
                    end else if (a_mantissa == 0 || b_mantissa == 0) begin

                        z <= {a_sign ^ b_sign, 31'b0};
                    end else begin

                        counter <= counter + 1;
                    end
                end

                2: begin

                    product <= a_mantissa * b_mantissa;
                    counter <= counter + 1;
                end

                3: begin

                    if (product[47]) begin

                        product <= product >> 1;
                        z_exponent <= a_exponent + b_exponent - 126;
                    end else begin
                        z_exponent <= a_exponent + b_exponent - 127;
                    end
                    counter <= counter + 1;
                end

                4: begin

                    guard <= product[0];
                    round_bit <= product[1];
                    sticky <= |product[47:2];
                    counter <= counter + 1;
                end

                5: begin

                    if (guard && (round_bit || sticky)) begin
                        if (z_mantissa[0]) begin

                            z_mantissa <= z_mantissa + 1;
                            if (z_mantissa == 0) z_exponent <= z_exponent + 1;
                        end else begin
                            z_mantissa <= z_mantissa + 1;
                        end
                    end
                    counter <= counter + 1;
                end

                6: begin

                    if (z_exponent >= 255) begin

                        z <= {z_sign, 8'hff, 23'b0};
                    end else if (z_exponent == 0) begin

                        z <= {z_sign, 31'b0};
                    end else begin

                        z <= {z_sign, z_exponent[6:0], z_mantissa};
                    end
                    counter <= 0;
                end

                default: counter <= 0;
            endcase
        end
    end

endmodule

