module LIFObuffer (
    input [3:0] dataIn,
    input RW,
    input EN,
    input Rst,
    input Clk,
    output reg EMPTY,
    output reg FULL,
    output reg [3:0] dataOut
);

reg [2:0] SP;

reg [3:0] stack_mem [0:3];


always @(posedge Clk) begin
    if (Rst) begin
        SP <= 0;
        stack_mem[0] <= 0;
        stack_mem[1] <= 0;
        stack_mem[2] <= 0;
        stack_mem[3] <= 0;
        dataOut <= 0;
    end
    else if (EN) begin
        if (RW == 0) begin 
            if (SP < 4) begin
                stack_mem[SP] <= dataIn;
                SP <= SP + 1;
            end
        end
        else begin 
            if (SP > 0) begin
                dataOut <= stack_mem[SP-1];
                SP <= SP - 1;
            end
        end
    end

    EMPTY <= (SP == 0);
    FULL <= (SP == 4);
end

endmodule

