module traffic_light (
    input clk,
    input rst_n,
    input pass_request,
    output reg [7:0] clock,
    output reg red,
    output reg yellow,
    output reg green
);


    parameter [1:0] idle = 0, s1_red = 1, s2_yellow = 2, s3_green = 3;

    reg [1:0] state;
    reg [7:0] cnt;
    reg p_red, p_yellow, p_green;


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= idle;
            cnt <= 10;
        end else begin
            case (state)
                idle: begin
                    state <= s1_red;
                    cnt <= 2;

                end
                s1_red: begin
                    if (cnt == 0) begin
                        state <= s3_green;
                        cnt <= 59;

                    end else begin
                        cnt <= cnt - 1;
                    end
                end
                s3_green: begin
                    if (cnt == 0) begin
                        state <= s2_yellow;
                        cnt <= 4;

                    end else begin
                        cnt <= cnt - 1;
                    end

                    if (pass_request && cnt > 10)
                        cnt <= 10;
                end
                s2_yellow: begin
                    if (cnt == 0) begin
                        state <= s1_red;
                        cnt <= 2;
                    end else begin
                        cnt <= cnt - 1;
                    end
                end
                default: state <= idle;
            endcase
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            red <= 0;
            yellow <= 0;
            green <= 0;
            p_red <= 0;
            p_yellow <= 0;
            p_green <= 0;
        end else begin
            case (state)
                idle: begin
                    red <= 0;
                    yellow <= 0;
                    green <= 0;
                end
                s1_red: begin
                    red <= 1;
                    yellow <= 0;
                    green <= 0;
                end
                s3_green: begin
                    green <= 1;
                    yellow <= 0;
                    red <= 0;
                end
                s2_yellow: begin
                    yellow <= 1;
                    green <= 0;
                    red <= 0;
                end
                default: begin
                    red <= 0;
                    yellow <= 0;
                    green <= 0;
                end
            endcase

            p_red <= red;
            p_yellow <= yellow;
            p_green <= green;
        end
    end


    always @(*) begin
        clock = cnt;
    end

endmodule

