    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            stored_data <= 8'b0;
            stored_flag <= 1'b0;
            stage1_data <= 16'b0;
            stage1_valid <= 1'b0;
        end else begin
            stage1_valid <= 1'b0;


            if (valid_in) begin
                if (stored_flag) begin

                    stage1_data <= {stored_data, data_in};
                    stage1_valid <= 1'b1;
                    stored_flag <= 1'b0;
