                    stored_data <= data_in;
                    stored_flag <= 1'b1;
                end
            end
        end
    end


    reg [15:0] data_out_reg;
    reg valid_out_reg;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            data_out_reg <= 16'b0;
            valid_out_reg <= 1'b0;
        end else begin
            data_out_reg <= stage1_data;
            valid_out_reg <= stage1_valid;
        end
    end

    assign data_out = data_out_reg;
    assign valid_out = valid_out_reg;

