module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

    reg [7:0] a, b;

    reg [7:0] divisor_comp;
    reg [8:0] sr;

    reg [3:0] count;
    reg busy;
    reg div_sign;
    reg [8:0] remainder_part;

    always @(posedge clk) begin
        if (rst) begin
            busy <= 0;
            res_valid <= 0;
            sr <= 9'b0;
            remainder_part <= 9'b0;
            count <= 0;
            a <= 0;
            b <= 0;
            divisor_comp <= 0;
            div_sign <= 0;
            result <= 0;
        end else begin
            if (busy) begin
                if (count < 8) begin

                    sr <= {sr[7:0], 1'b0};


                    if (remainder_part >= b) begin
                        remainder_part <= remainder_part - b;
                        sr[0] <= 1;

                    end else begin
                        sr[0] <= 0;

                    end

                    count <= count + 1;
                end else begin

                    if (sign) begin
                        if (div_sign) begin
                            sr[8:1] <= ~sr[8:1] + 1;

                        end
                        if (dividend[7]) begin
                            remainder_part <= ~remainder_part + 1;

                        end
                    end

                    result <= {remainder_part, sr[8:1]};
                    res_valid <= 1;
                    busy <= 0;
                end
            end else if (opn_valid && !res_valid) begin

                a <= (sign && dividend[7]) ? (~dividend + 1) : dividend;
                b <= (sign && divisor[7]) ? (~divisor + 1) : divisor;
                div_sign <= (dividend[7] ^ divisor[7]);


                sr <= {a, 1'b0};
                remainder_part <= 9'b0;
                count <= 0;
                busy <= 1;
            end

            if (res_valid) begin
                res_valid <= !opn_valid;
            end
        end
    end

endmodule

