    .wen(winc && !wfull),
    .waddr(wptr_bin[ADDR_WIDTH-1:0]),
    .wdata(wdata),
    .rclk(rclk),
    .ren(rinc && !rempty),
    .raddr(rptr_bin[ADDR_WIDTH-1:0]),
    .rdata(rdata)
);


always @(posedge wclk or negedge wrstn) begin
    if (!wrstn)
        wptr_bin <= 0;
    else if (winc && !wfull)
        wptr_bin <= wptr_bin + 1;
