assign wptr_gray = (wptr_bin >> 1) ^ wptr_bin;


always @(posedge wclk or negedge rrstn) begin
    if (!rrstn) begin
        rptr_sync_1 <= 0;
        rptr_sync_2 <= 0;
    end else begin
        rptr_sync_1 <= rptr_gray;
        rptr_sync_2 <= rptr_sync_1;
