module traffic_light (
    input rst_n,
    input clk,
    input pass_request,
    output reg [7:0] clock,
    output reg red,
    output reg yellow,
    output reg green
);


parameter idle     = 2'b00;
parameter s1_red   = 2'b01;
parameter s2_yellow= 2'b10;
parameter s3_green = 2'b11;


reg [7:0] cnt;
reg [1:0] state;
reg p_red, p_yellow, p_green;


always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= idle;
    end else begin
        case (state)
            idle: state <= s1_red;
            s1_red: if (cnt == 0) state <= s3_green;
            s3_green: if (cnt == 0) state <= s2_yellow;
            s2_yellow: if (cnt == 0) state <= s1_red;
            default: state <= idle;
        endcase
    end
end


always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        cnt <= 10;
    end else begin
        if (pass_request && green) begin
            if (cnt > 10) cnt <= 10;

        end else if (!green && p_green) begin
            cnt <= 60;
        end else if (!yellow && p_yellow) begin
            cnt <= 5;
        end else if (!red && p_red) begin
            cnt <= 10;
        end else begin
            cnt <= cnt - 1;
        end
    end
end


always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        {p_red, p_yellow, p_green} <= 3'b0;
    end else begin
        p_red   <= red;
        p_yellow <= yellow;
        p_green <= green;
    end
end


always @(*) begin
    {red, yellow, green} = 3'b000;
    case (state)
        s1_red: red = 1;
        s2_yellow: yellow = 1;
        s3_green: green = 1;
        default: ;

    endcase
end

assign clock = cnt;

endmodule

