module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

    reg [1:0] state;
    localparam IDLE = 2'b00;
    localparam SETUP = 2'b01;
    localparam DIVIDE = 2'b10;
    localparam FINISH = 2'b11;

    reg [7:0] divisor_abs, dividend_abs;
    reg sign_dividend, sign_divisor;
    reg [15:0] SR;

    reg [3:0] cnt;
    reg [7:0] NEG_DIVISOR;

    always @(posedge clk) begin
        if (rst) begin
            state <= IDLE;
            res_valid <= 0;
            SR <= 0;
            cnt <= 0;
            result <= 0;
            sign_dividend <= 0;
            sign_divisor <= 0;
            divisor_abs <= 0;
            dividend_abs <= 0;
            NEG_DIVISOR <= 0;
        end else begin
            case (state)
                IDLE: begin
                    res_valid <= 0;
                    if (opn_valid) begin

                        sign_dividend <= sign ? dividend[7] : 1'b0;
                        sign_divisor <= sign ? divisor[7] : 1'b0;


                        dividend_abs <= sign ? (dividend[7] ? -dividend : dividend) : dividend;
                        divisor_abs <= sign ? (divisor[7] ? -divisor : divisor) : divisor;


                        SR <= {8'b0, dividend_abs};
                        NEG_DIVISOR <= -divisor_abs;

                        cnt <= 0;
                        state <= DIVIDE;
                    end
                end

                DIVIDE: begin
                    if (cnt < 8) begin

                        reg [8:0] remainder_sub;
                        reg [7:0] new_remainder;
                        reg new_lsb;

                        remainder_sub = {1'b0, SR[15:8]} - NEG_DIVISOR;

                        if (remainder_sub[8] == 0) begin
                            new_remainder = remainder_sub[7:0];
                            new_lsb = 1'b1;
                        end else begin
                            new_remainder = remainder_sub[7:0];
                            new_lsb = 1'b0;
                        end

                        SR[15:8] <= new_remainder;
                        SR[7:0] <= {SR[6:0], new_lsb};
                        cnt <= cnt + 1;
                    end else begin
                        state <= FINISH;
                    end
                end

                FINISH: begin

                    reg [7:0] remainder_abs = SR[15:8];
                    reg [7:0] quotient_abs = SR[7:0];
                    reg [7:0] remainder;
                    reg [7:0] quotient;

                    if (sign) begin
                        remainder = sign_dividend ? -remainder_abs : remainder_abs;
                        quotient = (sign_dividend ^ sign_divisor) ? -quotient_abs : quotient_abs;
                    end else begin
                        remainder = remainder_abs;
                        quotient = quotient_abs;
                    end

                    result <= {remainder, quotient};
                    res_valid <= 1;
                    state <= IDLE;
                end

                default: state <= IDLE;
            endcase
        end
    end

endmodule

