module comparator_4bit (
    input [3:0] A,
    input [3:0] B,
    output A_greater,
    output A_equal,
    output A_less
);

    wire borrow_0 = 1'b0;
    wire borrow_1 = (~A[0] & B[0]) | ((A[0] ^ B[0]) & borrow_0);
    wire borrow_2 = (~A[1] & B[1]) | ((A[1] ^ B[1]) & borrow_1);
    wire borrow_3 = (~A[2] & B[2]) | ((A[2] ^ B[2]) & borrow_2);
    wire borrow_4 = (~A[3] & B[3]) | ((A[3] ^ B[3]) & borrow_3);

    assign A_less = borrow_4;
    assign A_equal = (A == B);
    assign A_greater = ~borrow_4 & (A != B);

