module cla_16bit (
    input [16:1] A,
    input [16:1] B,
    input C_in,
    output [16:1] S,
    output C_out,
    output G_group,
    output P_group
);

    wire [16:1] P, G;
    wire [16:1] C;

    assign P = A ^ B;
    assign G = A & B;


    assign C[1] = C_in;
    genvar i;
    generate
        for (i = 2;
 i <= 16;
 i = i + 1) begin : carry_gen
            assign C[i] = G[i-1] | (P[i-1] & C[i-1]);
        end
    endgenerate


    assign S = P ^ C[16:1];


    assign C_out = G[16] | (P[16] & C[16]);


    assign P_group = &P;



    reg [15:0] G_terms;
    integer j, k;
    always @(*) begin
        G_terms = 0;
        for (j = 0;
 j < 16;
 j = j + 1) begin
            reg term;
            term = 1;
            for (k = j+1;
 k <= 16;
 k = k + 1) begin
                term = term & P[k];
            end
            G_terms[j] = term & G[j];
        end
        G_group = |G_terms;
    end

endmodule

