module fixed_point_adder #(
    parameter N = 8,
    parameter Q = 4
) (
    input [N-1:0] a,
    input [N-1:0] b,
    output [N-1:0] c
);

    reg sign_a, sign_b;
    reg [N-2:0] mag_a, mag_b;
    reg [N-2:0] sum_mag;
    reg sign_res;

    always @* begin
        sign_a = a[N-1];
        sign_b = b[N-1];
        mag_a = a[N-2:0];
        mag_b = b[N-2:0];

        if (sign_a == sign_b) begin
            sum_mag = mag_a + mag_b;
            sign_res = sign_a;
        end else begin
            if (mag_a > mag_b) begin
                sum_mag = mag_a - mag_b;
                sign_res = sign_a;
            end else if (mag_b > mag_a) begin
                sum_mag = mag_b - mag_a;
                sign_res = sign_b;
            end else begin
                sum_mag = 0;
                sign_res = 0;
            end
        end

        c = {sign_res, sum_mag};
    end

endmodule

