    reg sign_a, sign_b;
    reg [N-2:0] mag_a, mag_b;
    reg [N-1:0] diff_mag;

    reg sign_mag;

    sign_a = a[N-1];
    mag_a = sign_a ? ((~a[N-2:0]) + 1) : a[N-2:0];

    sign_b = b[N-1];
    mag_b = sign_b ? ((~b[N-2:0]) + 1) : b[N-2:0];

    if (sign_a == sign_b) begin

        if (mag_a >= mag_b) begin
            sign_mag = sign_a;
            diff_mag = {1'b0, mag_a - mag_b};
        end else begin
            sign_mag = ~sign_a;
            diff_mag = {1'b0, mag_b - mag_a};
        end
    end else begin

        diff_mag = mag_a + mag_b;
        sign_mag = (mag_a >= mag_b) ? 1'b0 : 1'b1;
    end


    if (diff_mag == 0) begin
        sign_mag = 1'b0;
    end

    res = {sign_mag, diff_mag[N-2:0]};
    c = res;
end

endmodule

