    reg [22:0] a_mantissa, b_mantissa;
    reg [23:0] a_man, b_man;
    reg [47:0] product;
    reg guard, round, sticky;

    always @(posedge clk) begin
        if (rst) begin
            counter <= 0;
            z <= 0;
        end else begin
            case (counter)
                0: begin

                    a_sign <= a[31];
                    b_sign <= b[31];
                    a_exponent <= a[30:23];
                    b_exponent <= b[30:23];
                    a_mantissa <= a[22:0];
                    b_mantissa <= b[22:0];
                    a_man <= {1'b1, a[22:0]};
                    b_man <= {1'b1, b[22:0]};
                    sum_exponent <= 0;


                    if (a_exponent == 8'hff || b_exponent == 8'hff) begin
                        if ((a_exponent == 8'hff && b_exponent == 8'hff) || 
                            (a_mantissa != 0 && b_exponent == 8'hff) || 
                            (b_mantissa != 0 && a_exponent == 8'hff)) begin
                            z <= {a_sign ^ b_sign, 8'hff, 23'h1};
                        end else if (a_mantissa == 0 && b_exponent == 8'hff) begin
                            z <= {a_sign ^ b_sign, 8'hff, 23'h0};
                        end else if (b_mantissa == 0 && a_exponent == 8'hff) begin
                            z <= {a_sign ^ b_sign, 8'hff, 23'h0};
                        end else if (a_mantissa == 0 || b_mantissa == 0) begin
                            z <= {a_sign ^ b_sign, 31'h0};
                        end
                    end else if (a_exponent == 0 || b_exponent == 0) begin
                        if (a_exponent == 0 && b_exponent == 0 && a_mantissa == 0 && b_mantissa == 0) begin
                            z <= {a_sign ^ b_sign, 31'h0};
                        end
                    end else begin
                        counter <= 1;
                    end
                end

                1: begin

                    sum_exponent <= a_exponent + b_exponent - 8'd127 + 8'd127;
                    product <= a_man * b_man;
                    counter <= 2;
                end

                2: begin

                    if (product[47]) begin
                        sum_exponent <= sum_exponent + 1;
                        product <= product >> 1;
                    end
                    counter <= 3;
                end

                3: begin

                    {guard, round, sticky} = {product[1:0], |product[0]};
                    if (guard && (round || sticky)) begin
                        if (product[0]) begin
                            sum_exponent <= sum_exponent + 1;
                        end
                    end else if (guard && !(round || sticky)) begin
                        if (product[0]) begin
                            sum_exponent <= sum_exponent + 1;
                        end
                    end
                    if (sum_exponent >= 8'hff) begin
                        z <= {a_sign ^ b_sign, 8'hff, 23'h0};
                    end else if (sum_exponent[8] || sum_exponent < 0) begin
                        z <= {a_sign ^ b_sign, 31'h0};
                    end else begin
                        z <= {a_sign ^ b_sign, sum_exponent, product[46:24]};
                    end
                    counter <= 0;
                end

                default: counter <= 0;
            endcase
