module LIFObuffer (
    input [3:0] dataIn,
    input RW,
    input EN,
    input Rst,
    input Clk,
    output EMPTY,
    output FULL,
    output reg [3:0] dataOut
);

reg [3:0] stack_mem [0:3];
reg [2:0] SP;


assign EMPTY = (SP == 0);
assign FULL = (SP == 4);

integer i;

always @(posedge Clk) begin
    if (Rst) begin

        for (i=0;
 i<4;
 i=i+1) stack_mem[i] <= 4'b0;
        SP <= 3'b0;
        dataOut <= 4'b0;
    end
    else if (EN) begin
        if (RW) begin 
            if (SP != 0) begin
                dataOut <= stack_mem[SP-1];
                stack_mem[SP-1] <= 4'b0;

                SP <= SP - 1;
            end
        end
        else begin 
            if (SP != 4) begin
                stack_mem[SP] <= dataIn;
                SP <= SP + 1;
            end
        end
    end
end

endmodule

