module pulse_detect (
    input clk,
    input rst_n,
    input data_in,
    output reg data_out
);

localparam S0 = 2'b00;
localparam S1 = 2'b01;
localparam S2 = 2'b10;
localparam S3 = 2'b11;

reg [1:0] state;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= S0;
        data_out <= 0;
    end else begin
        case (state)
            S0: begin
                if (data_in == 0) begin
                    state <= S1;
                end else begin
                    state <= S0;
                end
                data_out <= 0;
            end
            S1: begin
                if (data_in == 1) begin
                    state <= S2;
                end else begin
                    state <= S0;
                end
                data_out <= 0;
            end
            S2: begin
                if (data_in == 0) begin
                    state <= S3;
                end else begin
                    state <= S0;
                end
                data_out <= 0;
            end
            S3: begin
                state <= S0;
                data_out <= 1;
            end
            default: begin
                state <= S0;
                data_out <= 0;
            end
        endcase
    end
end

endmodule

