module traffic_light (
    input rst_n,
    input clk,
    input pass_request,
    output reg [7:0] clock,
    output reg red,
    output reg yellow,
    output reg green
);

parameter idle = 2'b00,
          s1_red = 2'b01,
          s2_yellow = 2'b10,
          s3_green = 2'b11;

reg [7:0] cnt;
reg [1:0] state;
reg p_red, p_yellow, p_green;


always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= idle;
        p_red <= 0;
        p_yellow <= 0;
        p_green <= 0;
    end else begin
        case (state)
            idle: begin
                state <= s1_red;
                p_red <= 1;
                p_yellow <= 0;
                p_green <= 0;
            end
            s1_red: begin
                if (cnt == 3) begin
                    state <= s3_green;
                    p_red <= 0;
                    p_green <= 1;
                    p_yellow <= 0;
                end else begin
                    state <= s1_red;
                end
            end
            s3_green: begin
                if (cnt == 3) begin
                    state <= s2_yellow;
                    p_red <= 0;
                    p_green <= 0;
                    p_yellow <= 1;
                end else begin
                    state <= s3_green;
                end
            end
            s2_yellow: begin
                if (cnt == 3) begin
                    state <= s1_red;
                    p_red <= 1;
                    p_green <= 0;
                    p_yellow <= 0;
                end else begin
                    state <= s2_yellow;
                end
            end
            default: state <= idle;
        endcase
    end
end


always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        cnt <= 10;
    end else begin
        if (pass_request && green) begin
            cnt <= 10;
