    if (!rst_n) begin
        data_lock <= 8'b0;
        has_first <= 1'b0;
        combined_data <= 16'b0;
        combined_valid <= 1'b0;
        valid_out <= 1'b0;
        data_out <= 16'b0;
    end else begin
        combined_valid <= 1'b0;

        valid_out <= 1'b0;


        if (has_first) begin
            if (valid_in) begin
                combined_data <= {data_lock, data_in};

                combined_valid <= 1'b1;

                has_first <= 1'b0;

            end
        end else begin
            if (valid_in) begin
                data_lock <= data_in;

                has_first <= 1'b1;

            end
        end


        if (combined_valid) begin
            data_out <= combined_data;
            valid_out <= 1'b1;
        end
    end
end

