module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

    reg [7:0] abs_dividend;
    reg [7:0] abs_divisor;
    reg [7:0] quotient_sign;
    reg [7:0] remainder_sign;
    reg [15:0] SR;
    reg [3:0] cnt;
    reg start_cnt;
    reg [7:0] NEG_DIVISOR;

    always @(posedge clk) begin
        if (rst) begin
            res_valid <= 0;
            SR <= 0;
            cnt <= 0;
            start_cnt <= 0;
            abs_dividend <= 0;
            abs_divisor <= 0;
            quotient_sign <= 0;
            remainder_sign <= 0;
            NEG_DIVISOR <= 0;
            result <= 0;
        end else begin
            if (opn_valid && !res_valid) begin

                if (sign) begin
                    abs_dividend <= dividend[7] ? (~dividend + 1) : dividend;
                    abs_divisor <= divisor[7] ? (~divisor + 1) : divisor;
                    quotient_sign <= dividend[7] ^ divisor[7];
                    remainder_sign <= dividend[7];
                end else begin
                    abs_dividend <= dividend;
                    abs_divisor <= divisor;
                    quotient_sign <= 0;
                    remainder_sign <= 0;
                end

                NEG_DIVISOR <= -abs_divisor;
                SR <= {abs_dividend << 1, 8'b0};
                cnt <= 8;
                start_cnt <= 1;
                res_valid <= 0;
            end else if (start_cnt && cnt > 0) begin

                if (SR[15:8] >= NEG_DIVISOR) begin

                    SR <= {SR[15:8] - NEG_DIVISOR, SR[7:0], 1'b1};
                end else begin

                    SR <= {SR[15:8], SR[7:0], 1'b0};
                end
                cnt <= cnt - 1;
            end

            if (cnt == 0 && start_cnt) begin
                start_cnt <= 0;

                if (sign) begin
