module fixed_point_adder #(
    parameter Q = 4,
    parameter N = 8
) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output reg [N-1:0] c
);

reg [N-1:0] res;

wire a_sign = a[N-1];
wire b_sign = b[N-1];


wire [N-2:0] a_mag = a_sign ? (~a[N-2:0] + 1) : a[N-2:0];
wire [N-2:0] b_mag = b_sign ? (~b[N-2:0] + 1) : b[N-2:0];

always @(*) begin
    if (a_sign == b_sign) begin

        wire [N:0] sum_mag = {1'b0, a_mag} + {1'b0, b_mag};

        res = {a_sign, sum_mag[N-1:0]};
    end else begin

        if (a_mag > b_mag) begin
            res = {1'b0, a_mag - b_mag};
        end else if (b_mag > a_mag) begin
            res = {1'b0, b_mag - a_mag};
        end else begin 
            res = {1'b0, {(N-1){1'b0}}};
        end
    end


    c = res;
end

endmodule

