reg a_sign, b_sign, z_sign;
reg [7:0] a_exponent, b_exponent, z_exponent;
reg [22:0] a_mantissa, b_mantissa;
reg [47:0] product;
reg [23:0] a_mantissa_ext, b_mantissa_ext;
reg guard, round_bit, sticky;
reg [47:0] normalized_product;
reg [23:0] final_mantissa;
reg [7:0] final_exponent;


wire a_zero = (a_exponent == 0) && (a_mantissa == 0);
wire b_zero = (b_exponent == 0) && (b_mantissa == 0);
wire a_inf = (a_exponent == 8'hff) && (a_mantissa == 0);
wire b_inf = (b_exponent == 8'hff) && (b_mantissa == 0);
wire a_nan = (a_exponent == 8'hff) && (a_mantissa != 0);
wire b_nan = (b_exponent == 8'hff) && (b_mantissa != 0);


function [5:0] leading_zero_count(input [47:0] num);
    reg [5:0] i;
    begin
        leading_zero_count = 0;
        for (i = 47;
 i >= 0;
 i = i - 1) begin
            if (num[i] == 1'b1) break;
            leading_zero_count = leading_zero_count + 1;
        end
    end
endfunction

always @(posedge clk) begin
    if (rst) begin
        counter <= 0;
        z <= 0;
    end else begin
        case (counter)
            0: begin

                a_sign <= a[31];
                b_sign <= b[31];
                a_exponent <= a[30:23];
                b_exponent <= b[30:23];
                a_mantissa <= a[22:0];
                b_mantissa <= b[22:0];


                if (a_nan || b_nan) begin
                    z_sign <= a_sign ^ b_sign;
                    z <= {z_sign, 8'hff, 23'h000001};
                    counter <= 3;
                end else if ((a_inf && b_zero) || (b_inf && a_zero)) begin
                    z_sign <= a_sign ^ b_sign;
                    z <= {z_sign, 8'hff, 23'h0};
                    counter <= 3;
                end else if (a_inf || b_inf) begin
                    z_sign <= a_sign ^ b_sign;
                    z <= {z_sign, 8'hff, 23'h0};
                    counter <= 3;
                end else if (a_zero || b_zero) begin
                    z_sign <= a_sign ^ b_sign;
                    z <= {z_sign, 8'h00, 23'h0};
                    counter <= 3;
                end else begin

                    a_mantissa_ext <= (a_exponent == 0) ? {1'b0, a_mantissa} : {1'b1, a_mantissa};
                    b_mantissa_ext <= (b_exponent == 0) ? {1'b0, b_mantissa} : {1'b1, b_mantissa};
                    counter <= 1;
                end
            end
            1: begin

                product <= a_mantissa_ext * b_mantissa_ext;

                normalized_product <= product << (leading_zero_count(product) - 1);

                z_exponent <= a_exponent + b_exponent - 8'd127 - leading_zero_count(product) + 1;

                guard <= product[47 - (leading_zero_count(product) - 1)];
                round_bit <= product[46 - (leading_zero_count(product) - 1)];
                sticky <= |product[45 - (leading_zero_count(product) - 1):0];
                counter <= 2;
            end
            2: begin

                final_mantissa <= normalized_product[23:0];
                if (guard && (round_bit || sticky || (final_mantissa[0]))) begin
                    if (final_mantissa == 24'hffffff) begin
                        final_mantissa <= 24'h0;
                        final_exponent <= z_exponent + 1;
                    end else begin
                        final_mantissa <= final_mantissa + 1;
                        final_exponent <= z_exponent;
                    end
                end else begin
                    final_exponent <= z_exponent;
                end
                counter <= 3;
            end
            3: begin

                if (final_exponent >= 255) begin
                    z <= {z_sign, 8'hff, 23'h0};
                end else if (final_exponent <= 0) begin
                    z <= {z_sign, 8'h0, 23'h0};
                end else begin
                    z <= {z_sign, final_exponent[7:0], final_mantissa[22:0]};
                end
                counter <= 0;
            end
        endcase
    end
end

endmodule

