module traffic_light (
    input rst_n,
    input clk,
    input pass_request,
    output reg [7:0] clock,
    output reg red,
    output reg yellow,
    output reg green
);

    parameter idle = 2'b00;
    parameter s1_red = 2'b01;
    parameter s2_yellow = 2'b10;
    parameter s3_green = 2'b11;

    reg [7:0] cnt;
    reg [1:0] state;
    reg p_red, p_yellow, p_green;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= idle;
        end else begin
            case (state)
                idle: state <= s1_red;
                s1_red: if (cnt == 3) state <= s3_green;
                s3_green: if (cnt == 3) state <= s2_yellow;
                s2_yellow: if (cnt == 3) state <= s1_red;
                default: state <= idle;
            endcase
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt <= 10;
        end else begin
            if (pass_request && p_green && (cnt > 10)) begin
                cnt <= 10;
            end else begin
                case (state)
                    idle: cnt <= 10;
                    s1_red: if (cnt == 0) cnt <= 60;
                    s3_green: if (cnt == 0) cnt <=5;
                    s2_yellow: if (cnt ==0) cnt <=10;
                    default: cnt <= cnt;
                endcase
            end
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            red <=0;
            yellow <=0;
            green <=0;
            p_red <=0;
            p_yellow <=0;
            p_green <=0;
        end else begin
            p_red <= red;
            p_yellow <= yellow;
            p_green <= green;
            case (state)
                idle: begin
                    red <=0;
                    yellow <=0;
                    green <=0;
                end
                s1_red: begin
                    red <=1;
                    yellow <=0;
                    green <=0;
                end
                s3_green: begin
                    red <=0;
                    yellow <=0;
                    green <=1;
                end
                s2_yellow: begin
                    red <=0;
                    yellow <=1;
                    green <=0;
                end
                default: begin
                    red <=0;
                    yellow <=0;
                    green <=0;
                end
            endcase
        end
    end

    assign clock = cnt;

