module edge_detect (
    input clk,
    input rst_n,
    input a,
    output reg rise = 0,
    output reg down = 0
);

reg a_prev;

always @(posedge clk) begin
    if (!rst_n) begin
        a_prev <= 0;
        rise <= 0;
        down <= 0;
    end else begin

        rise <= 0;
        down <= 0;


        if (a_prev == 0 && a == 1) begin
            rise <= 1;
        end

        else if (a_prev == 1 && a == 0) begin
            down <= 1;
        end


        a_prev <= a;
    end
end

endmodule

