module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output [15:0] result
);

    reg [1:0] state;
    reg [7:0] abs_dividend, abs_divisor;
    reg sign_dividend, sign_divisor;
    reg [16:0] shift_reg;

    reg [3:0] cnt;

    localparam IDLE = 2'b00;
    localparam INIT = 2'b01;
    localparam PROCESS = 2'b10;
    localparam DONE = 2'b11;

    always @(posedge clk) begin
        if (rst) begin
            state <= IDLE;
            res_valid <= 0;
            shift_reg <= 0;
            cnt <= 0;
            {abs_dividend, abs_divisor} <= 0;
            {sign_dividend, sign_divisor} <= 0;
        end else begin
            case (state)
                IDLE: begin
                    if (opn_valid && !res_valid) begin

                        if (sign) begin
                            abs_dividend <= dividend[7] ? -dividend : dividend;
                            abs_divisor <= divisor[7] ? -divisor : divisor;
                            sign_dividend <= dividend[7];
                            sign_divisor <= divisor[7];
                        end else begin
                            abs_dividend <= dividend;
                            abs_divisor <= divisor;
                            sign_dividend <= 0;
                            sign_divisor <= 0;
                        end

                        shift_reg <= {9'b0, {abs_dividend, 1'b0}};
                        cnt <= 0;
                        state <= INIT;
                    end
                end
                INIT: begin

                    state <= PROCESS;
                end
                PROCESS: begin
                    if (cnt < 8) begin

                        shift_reg <= shift_reg << 1;

                        if (shift_reg[16:8] >= abs_divisor) begin
                            shift_reg[16:8] <= shift_reg[16:8] - abs_divisor;
                            shift_reg[0] <= 1'b1;
                        end else begin
                            shift_reg[0] <= 1'b0;
                        end
                        cnt <= cnt + 1;
                    end else begin

                        state <= DONE;
                        res_valid <= 1;

                        if (sign) begin

                            if (sign_dividend != sign_divisor) begin
                                shift_reg[7:0] <= -shift_reg[7:0];
                            end

                            if (sign_dividend) begin
                                shift_reg[16:8] <= -shift_reg[16:8];
                            end
                        end
                    end
                end
                DONE: begin
                    if (opn_valid) begin
                        state <= IDLE;
                        res_valid <= 0;
                    end
                end
            endcase
        end
    end

    assign result = {shift_reg[16:8], shift_reg[7:0]};

endmodule

