reg [15:0] rem;
reg [15:0] quo;


always @* begin
    a_reg = A;
    b_reg = B;
end


always @* begin
    rem = 16'b0;
    quo = 16'b0;

    for (int i = 15;
 i >= 0;
 i = i - 1) begin

        rem = {rem[14:0], a_reg[i]};

        if (rem >= {8'b0, b_reg}) begin
            rem = rem - {8'b0, b_reg};
            quo[i] = 1;
        end else begin
            quo[i] = 0;
        end
    end

    result = quo;
    odd = rem;
end

endmodule

