module multi_16bit (
    input clk,
    input rst_n,
    input start,
    input [15:0] ain,
    input [15:0] bin,
    output reg [31:0] yout,
    output reg done
);

reg [4:0] i;

reg [15:0] areg, breg;
reg [31:0] yout_r;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        i <= 5'b0;
        areg <= 16'b0;
        breg <= 16'b0;
        yout_r <= 32'b0;
        done <= 1'b0;
    end else begin

        if (start) begin
            if (i < 17)
                i <= i + 1;
            else
                i <= 5'b0;
        end else begin
            i <= 5'b0;
        end


        if (i == 5'b0) begin
            areg <= ain;
            breg <= bin;
            yout_r <= 32'b0;
        end


        if (start && i > 0 && i < 17) begin
            if (areg[i-1]) begin
                yout_r <= yout_r + (breg << (i-1));
            end
        end


        if (i == 16)
            done <= 1'b1;
        else if (i == 17)
            done <= 1'b0;
        else
            done <= 1'b0;
    end
end

assign yout = yout_r;

endmodule

