module fixed_point_adder #(parameter Q=4, N=8) (
    input [N-1:0] a,
    input [N-1:0] b,
    output [N-1:0] c
);

    reg [N-2:0] mag_a, mag_b;
    reg sign_a, sign_b;
    reg [N-2:0] sum_mag;
    reg sum_sign;

    always @(*) begin
        sign_a = a[N-1];
        sign_b = b[N-1];
        mag_a = sign_a ? (~a[N-2:0] + 1) : a[N-2:0];
        mag_b = sign_b ? (~b[N-2:0] + 1) : b[N-2:0];
    end

    always @(*) begin
        if (sign_a == sign_b) begin
            sum_mag = mag_a + mag_b;
            sum_sign = sign_a;
        end else begin
            if (mag_a > mag_b) begin
                sum_mag = mag_a - mag_b;
                sum_sign = sign_a;
            end else if (mag_b > mag_a) begin
                sum_mag = mag_b - mag_a;
                sum_sign = sign_b;
            end else begin
                sum_mag = 0;
                sum_sign = 0;
            end
        end
    end

    assign c = {sum_sign, sum_mag};

endmodule

