module sub_64bit(
  input [63:0] A,
  input [63:0] B,
  output reg [63:0] result,
  output reg overflow
);
  always @(*) begin
    result = A - B;

    // Overflow happens when the sign of A and B are different, but the sign of result matches B
    if ((A[63] != B[63]) && (result[63] != A[63])) begin
      overflow = 1;
    end else begin
      overflow = 0;
    end
  end

endmodule

module up_down_counter (
    input wire clk,
    input wire reset,
    input wire up_down,
    output reg [15:0] count
);

always @(posedge clk or posedge reset)
begin
    if (reset) begin
        count <= 16'b0; 
    end else begin
        if (up_down) begin
            // Increment the counter if up_down is high
            if (count == 16'b1111_1111_1111_1111) begin
                count <= 16'b0; 
            end else begin
                count <= count + 1; 
            end
        end else begin
            // Decrement the counter if up_down is low
            if (count == 16'b0) begin
                count <= 16'b1111_1111_1111_1111; 
            end else begin
                count <= count - 1; 
            end
        end
    end
end

endmodule

