module LIFObuffer (
    input Clk,
    input Rst,
    input EN,
    input RW,
    input [3:0] dataIn,
    output EMPTY,
    output FULL,
    output [3:0] dataOut
);
    reg [2:0] SP;

    reg [3:0] stack_mem [0:3];

    reg [3:0] dataOut_reg;

    assign EMPTY = (SP == 4);

    assign FULL = (SP == 0);

    assign dataOut = dataOut_reg;

    always @(posedge Clk) begin
        if (Rst) begin

            SP <= 4;
            stack_mem[0] <= 0;
            stack_mem[1] <= 0;
            stack_mem[2] <= 0;
            stack_mem[3] <= 0;
            dataOut_reg <= 0;
        end
        else if (EN) begin
            if (RW) begin 
                if (!EMPTY) begin
                    dataOut_reg <= stack_mem[SP-1];

                    stack_mem[SP-1] <= 0;

                    SP <= SP + 1;

                end
            end
            else begin 
                if (!FULL) begin
                    stack_mem[SP-1] <= dataIn;

                    SP <= SP - 1;

                end
            end
        end
    end
endmodule

