module traffic_light (
    input rst_n,
    input clk,
    input pass_request,
    output [7:0] clock,
    output reg red,
    output reg yellow,
    output reg green
);

    parameter idle = 2'b00;
    parameter s1_red = 2'b01;
    parameter s2_yellow = 2'b10;
    parameter s3_green = 2'b11;

    reg [1:0] state;
    reg [1:0] prev_state;
    reg [7:0] cnt;
    reg p_red, p_yellow, p_green;


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= idle;
            red <= 0;
            yellow <= 0;
            green <= 0;
            p_red <= 0;
            p_yellow <= 0;
            p_green <= 0;
        end else begin
            case (state)
                idle: begin
                    state <= s1_red;
                    red <= 1;
                    yellow <= 0;
                    green <= 0;
                    p_red <= 0;
                    p_yellow <= 0;
                    p_green <= 0;
                end
                s1_red: begin
                    if (cnt == 0) begin
                        state <= s2_yellow;
                        red <= 0;
                        yellow <= 1;
                        green <= 0;
                        p_red <= 1;
                        p_yellow <= 0;
                        p_green <= 0;
                    end else begin
                        red <= 1;
                        yellow <= 0;
                        green <= 0;
                    end
                end
                s2_yellow: begin
                    if (cnt == 0) begin
                        state <= s3_green;
                        yellow <= 0;
                        green <= 1;
                        p_yellow <= 0;
                        p_green <= 1;
                    end else begin
                        yellow <= 1;
                        green <= 0;
                    end
                end
                s3_green: begin
                    if (cnt == 0) begin
                        state <= s1_red;
                        green <= 0;
                        red <= 1;
                        p_green <= 0;
                        p_red <= 1;
                    end else begin
                        green <= 1;
                        yellow <= 0;
                        red <= 0;
                    end
                end
                default: begin
                    state <= idle;
                    red <= 0;
                    yellow <= 0;
                    green <= 0;
                    p_red <= 0;
                    p_yellow <= 0;
                    p_green <= 0;
                end
            endcase
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt <= 10;
        end else begin
            if (state != prev_state) begin
                case (state)
                    s1_red: cnt <= 10;
                    s2_yellow: cnt <= 5;
                    s3_green: cnt <= 60;
                    default: cnt <= 10;
                endcase
            end else begin
                if (state == s3_green) begin
                    if (pass_request && (cnt > 10))
                        cnt <= 10;
                    else
                        cnt <= cnt - 1;
                end else begin
                    cnt <= cnt - 1;
                end
            end
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            prev_state <= idle;
        else
            prev_state <= state;
    end


    assign clock = cnt;

endmodule

