module alu (
    input [31:0] a,
    input [31:0] b,
    input [5:0] aluc,
    output reg [31:0] r,
    output zero,
    output reg carry,
    output negative,
    output reg overflow,
    output flag
);


parameter ADD  = 6'b100000;
parameter ADDU = 6'b100001;
parameter SUB  = 6'b100010;
parameter SUBU = 6'b100011;
parameter AND  = 6'b100100;
parameter OR   = 6'b100101;
parameter XOR  = 6'b100110;
parameter NOR  = 6'b100111;
parameter SLT  = 6'b101010;
parameter SLTU = 6'b101011;
parameter SLL  = 6'b000000;
parameter SRL  = 6'b000010;
parameter SRA  = 6'b000011;
parameter SLLV = 6'b000100;
parameter SRLV = 6'b000110;
parameter SRAV = 6'b000111;
parameter LUI  = 6'b001111;


wire [31:0] slt_result;
wire [31:0] sltu_result;


assign slt_result = ($signed(a) < $signed(b)) ? 32'd1 : 32'd0;


assign sltu_result = (a < b) ? 32'd1 : 32'd0;


assign zero = (r == 32'd0);


assign negative = r[31];


assign flag = (aluc == SLT)  ? slt_result[0]  :
              (aluc == SLTU) ? sltu_result[0] : 1'bz;

always @(*) begin
    case (aluc)
        ADD: begin
            {carry, r} = {1'b0, a} + {1'b0, b};
            overflow = (a[31] == b[31]) && (r[31] != a[31]);
        end
        ADDU: begin
            {carry, r} = {1'b0, a} + {1'b0, b};
            overflow = 1'b0;
        end
        SUB: begin
            {carry, r} = {1'b0, a} - {1'b0, b};
            overflow = (a[31] != b[31]) && (r[31] != a[31]);
        end
        SUBU: begin
            {carry, r} = {1'b0, a} - {1'b0, b};
            overflow = 1'b0;
        end
        AND:  begin {carry, overflow, r} = {1'b0, 1'b0, a & b};
 end
        OR:   begin {carry, overflow, r} = {1'b0, 1'b0, a | b};
 end
        XOR:  begin {carry, overflow, r} = {1'b0, 1'b0, a ^ b};
 end
        NOR:  begin {carry, overflow, r} = {1'b0, 1'b0, ~(a | b)};
 end
        SLT:  begin {carry, overflow, r} = {1'b0, 1'b0, slt_result};
 end
        SLTU: begin {carry, overflow, r} = {1'b0, 1'b0, sltu_result};
 end
        SLL:  begin {carry, overflow, r} = {1'b0, 1'b0, a << b[4:0]};
 end
        SRL:  begin {carry, overflow, r} = {1'b0, 1'b0, a >> b[4:0]};
 end
        SRA:  begin {carry, overflow, r} = {1'b0, 1'b0, $signed(a) >>> b[4:0]};
 end
        SLLV: begin {carry, overflow, r} = {1'b0, 1'b0, b << a[4:0]};
 end
        SRLV: begin {carry, overflow, r} = {1'b0, 1'b0, b >> a[4:0]};
 end
        SRAV: begin {carry, overflow, r} = {1'b0, 1'b0, $signed(b) >>> a[4:0]};
 end
        LUI:  begin {carry, overflow, r} = {1'b0, 1'b0, {a[15:0], 16'b0}};
 end
        default: begin {carry, overflow, r} = 38'b0;
 end
    endcase
end

endmodule

