module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

    reg [7:0] saved_dividend;
    reg [7:0] saved_divisor;
    reg [7:0] abs_dividend;
    reg [7:0] abs_divisor;
