    reg [3:0] cnt;

    reg start_cnt;
    reg sign_q;
    reg sign_r;


    function [7:0] abs(input [7:0] val);
        abs = val[7] ? (~val + 1) : val;
    endfunction


    always @(*) begin
        if (sign) begin
            sign_q = (dividend[7] ^ divisor[7]) ? 1 : 0;
            sign_r = dividend[7];
        end else begin
            sign_q = 0;
            sign_r = 0;
        end
    end


    always @(posedge clk) begin
        if (rst) begin
            res_valid <= 0;
            SR <= 0;
            cnt <= 0;
            start_cnt <= 0;
            saved_dividend <= 0;
            saved_divisor <= 0;
            abs_dividend <= 0;
            abs_divisor <= 0;
            result <= 0;
        end else begin
            if (opn_valid && !res_valid) begin

                saved_dividend <= sign ? abs(dividend) : dividend;
                saved_divisor <= sign ? abs(divisor) : divisor;
                abs_dividend <= sign ? abs(dividend) : dividend;
                abs_divisor <= sign ? abs(divisor) : divisor;


                SR <= {8'b0, abs_dividend, 1'b0};



                SR <= {8'b0, abs_dividend, 1'b0};




                cnt <= 1;
                start_cnt <= 1;
                res_valid <= 0;
            end else if (start_cnt) begin
                if (cnt < 8) begin

                    if (SR[15:8] >= abs_divisor) begin
                        SR[15:8] <= SR[15:8] - abs_divisor;
                        SR[7:0] <= {SR[6:0], 1'b1};
                    end else begin
                        SR[7:0] <= {SR[6:0], 1'b0};
                    end
                    cnt <= cnt + 1;
                end else begin

                    if (sign) begin
                        if (sign_q) result[7:0] <= -SR[7:0];
                        if (sign_r) result[23:16] <= -SR[15:8];
                    end else begin
                        result[7:0] <= SR[7:0];
                        result[15:8] <= SR[15:8];
                    end
                    res_valid <= 1;
                    start_cnt <= 0;
                end
            end else if (res_valid) begin
                res_valid <= 0;
            end
        end
    end

