module adder_bcd (
    input [3:0] A,
    input [3:0] B,
    input Cin,
    output [3:0] Sum,
    output Cout
);

    wire [4:0] sum_bin = {1'b0, A} + {1'b0, B} + Cin;
    wire [4:0] sum_corrected = sum_bin + 5'd6;
    wire correction_needed = (sum_bin > 9);

    assign Sum = correction_needed ? sum_corrected[3:0] : sum_bin[3:0];
    assign Cout = correction_needed ? sum_corrected[4] : 1'b0;

endmodule

