module fixed_point_adder #(
    parameter Q = 16,  
    parameter N = 32   
) (
    input  wire [N-1:0] a,
    input  wire [N-1:0] b,
    output reg  [N-1:0] c
);

reg [N-1:0] res;
reg sign_a, sign_b;
reg [N-1:0] a_abs, b_abs;

always @(*) begin
    sign_a = a[N-1];
    sign_b = b[N-1];
    a_abs = sign_a ? (~a + 1) : a;
    b_abs = sign_b ? (~b + 1) : b;

    if (sign_a == sign_b) begin

        res = a + b;
    end else begin

        if (a_abs > b_abs) begin
            res = a_abs - b_abs;
            res[N-1] = sign_a;
        end else if (b_abs > a_abs) begin
            res = b_abs - a_abs;
            res[N-1] = sign_b;
        end else begin

            res = {N{1'b0}};
        end
    end

    c = res;
end

endmodule

