module fixed_point_subtractor #(
    parameter Q = 4,
    parameter N = 8
)(
    input [N-1:0] a,
    input [N-1:0] b,
    output [N-1:0] c
);

reg [N-1:0] res;
wire a_sign = a[N-1];
wire b_sign = b[N-1];
wire same_sign = (a_sign == b_sign);

reg [N:0] abs_a;

reg [N:0] abs_b;
reg [N:0] sum;

always @(*) begin
    if (same_sign) begin
        res = a - b;
    end else begin
        abs_a = a_sign ? (~{1'b0, a} + 1) : {1'b0, a};
        abs_b = b_sign ? (~{1'b0, b} + 1) : {1'b0, b};
        sum = abs_a + abs_b;

        if (sum == 0) begin
            res = 0;
        end else begin
            res = (abs_a > abs_b) ? {1'b0, sum[N-1:0]} : {1'b1, sum[N-1:0]};
        end
    end
end

assign c = res;

endmodule

