module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);

    reg [2:0] counter;
    reg [22:0] a_mantissa, b_mantissa;
    reg [7:0] a_exponent, b_exponent;
    reg a_sign, b_sign;
    reg [47:0] product;
    reg guard_bit, round_bit, sticky;
    reg [4:0] exp_sum;
    reg [22:0] z_mantissa;

    always @(posedge clk) begin
        if (rst) begin
            counter <= 0;
            z <= 0;
        end else begin
            case (counter)
                0: begin

                    if (a[30:23] == 8'hff) begin
                        if (a[22:0] == 0) begin 
                            if (b[30:23] == 8'hff) begin
                                z <= {a[31] ^ b[31], 8'hff, 1'b0, 22'h0};

                            end else begin
                                z <= {a[31] ^ b[31], 8'hff, 1'b0, 22'h0};

                            end
                        end else begin 
                            z <= {a[31] ^ b[31], 8'hff, 1'b1, 22'h0};
                        end
                    end else if (b[30:23] == 8'hff) begin
                        if (b[22:0] == 0) begin 
                            z <= {a[31] ^ b[31], 8'hff, 1'b0, 22'h0};
                        end else begin 
                            z <= {a[31] ^ b[31], 8'hff, 1'b1, 22'h0};
                        end
                    end else if (a[22:0] == 0 && b[22:0] == 0) begin 
                        z <= {a[31] ^ b[31], 8'h0, 23'h0};
                    end else if (a[22:0] == 0 || b[22:0] == 0) begin 
                        z <= {a[31] ^ b[31], 8'h0, 23'h0};
                    end else begin
                        a_sign <= a[31];
                        b_sign <= b[31];
                        a_exponent <= a[30:23];
                        b_exponent <= b[30:23];
                        a_mantissa <= {1'b1, a[22:0]};
                        b_mantissa <= {1'b1, b[22:0]};
                        counter <= 1;
                    end
                end

                1: begin

                    product <= a_mantissa * b_mantissa;
                    counter <= 2;
                end

                2: begin

                    if (product[47:46] >= 2'b10) begin
                        product <= product >> 1;
                        exp_sum <= a_exponent + b_exponent - 8'd127 + 1;
                    end else begin
                        exp_sum <= a_exponent + b_exponent - 8'd127;
                    end
                    guard_bit <= product[22];
                    round_bit <= product[21];
                    sticky <= |product[20:0];
                    z_mantissa <= product[22:0];
                    counter <= 3;
                end

                3: begin

                    if (guard_bit && (round_bit || sticky || (z_mantissa[0] && !round_bit))) begin
                        if (z_mantissa == 23'h7fffff) begin
                            z_mantissa <= 0;
                            exp_sum <= exp_sum + 1;
                        end else begin
                            z_mantissa <= z_mantissa + 1;
                        end
                    end


                    if (z_mantissa == 0 && exp_sum == 5'h1f) begin

                        z <= {a_sign ^ b_sign, 8'hff, 23'h0};
                    end else if (exp_sum >= 9'h100) begin

                        z <= {a_sign ^ b_sign, 8'hff, 23'h0};
                    end else if (exp_sum <= 0) begin

                        z <= {a_sign ^ b_sign, 8'h0, 23'h0};
                    end else begin

                        z <= {a_sign ^ b_sign, exp_sum[7:0], z_mantissa};
                    end
                    counter <= 0;
                end

                default: counter <= 0;
            endcase
        end
    end

endmodule

