module fsm (
    input IN,
    input CLK,
    input RST,
    output reg MATCH
);

    reg [2:0] state;
    localparam S0 = 3'b000,
               S1 = 3'b001,
               S2 = 3'b010,
               S3 = 3'b011,
               S4 = 3'b100;

    always @(posedge CLK or posedge RST) begin
        if (RST) begin
            state <= S0;
            MATCH <= 0;
        end else begin
            case (state)
                S0: begin
                    MATCH <= 0;
                    state <= IN ? S1 : S0;
                end
                S1: begin
                    MATCH <= 0;
                    state <= IN ? S1 : S2;
                end
                S2: begin
                    MATCH <= 0;
                    state <= IN ? S1 : S3;
                end
                S3: begin
                    if (IN) begin
                        MATCH <= 1;
                        state <= S4;
                    end else begin
                        MATCH <= 0;
                        state <= S0;
                    end
                end
                S4: begin
                    if (IN) begin
                        MATCH <= 1;
                        state <= S1;

                    end else begin
                        MATCH <= 0;
                        state <= S0;
                    end
                end
                default: begin
                    state <= S0;
                    MATCH <= 0;
                end
            endcase
        end
    end

endmodule

