module LIFObuffer (
    input [3:0] dataIn,
    input RW,
    input EN,
    input Rst,
    input Clk,
    output reg EMPTY,
    output reg FULL,
    output reg [3:0] dataOut
);

reg [3:0] stack_mem [0:3];
reg [3:0] SP;
reg [3:0] next_SP;

integer i;

always @(*) begin
    if (Rst) begin
        next_SP = 4;
    end else if (EN) begin
        if (FULL) begin
            next_SP = SP;
        end else if (EMPTY) begin
            next_SP = RW ? SP : (SP - 1);
        end else begin
            next_SP = RW ? SP + 1 : SP - 1;
        end
    end else begin
        next_SP = SP;
    end
end

always @(posedge Clk) begin
    if (Rst) begin
        SP <= 4;
        EMPTY <= 1;
        FULL <= 0;
        for (i = 0;
 i < 4;
 i = i + 1) begin
            stack_mem[i] <= 0;
        end
    end else if (EN) begin
        SP <= next_SP;

        if (!FULL && !RW) begin
            stack_mem[next_SP - 1] <= dataIn;
        end else if (!EMPTY && RW) begin
            dataOut <= stack_mem[next_SP - 1];
            stack_mem[next_SP - 1] <= 0;
        end
    end

    EMPTY <= (next_SP == 4);
    FULL <= (next_SP == 0);
end

endmodule

