module traffic_light (
    input rst_n,
    input clk,
    input pass_request,
    output reg [7:0] clock,
    output reg red,
    output reg yellow,
    output reg green
);


parameter idle = 2'b00,
          s1_red = 2'b01,
          s2_yellow = 2'b10,
          s3_green = 2'b11;

reg [1:0] state;
reg [7:0] cnt;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= idle;
        cnt <= 10;

    end else begin
        case (state)
            idle: begin
                state <= s1_red;
                cnt <= 10;

            end
            s1_red: begin
                if (cnt == 0) begin
                    state <= s3_green;
                    cnt <= 60;

                end else begin
                    cnt <= cnt - 1;
                end
            end
            s3_green: begin

                if (pass_request && cnt > 10) begin
                    cnt <= 10;
                end
                if (cnt == 0) begin
                    state <= s2_yellow;
                    cnt <= 5;

                end else begin
                    cnt <= cnt - 1;
                end
            end
            s2_yellow: begin
                if (cnt == 0) begin
                    state <= s1_red;
                    cnt <= 10;

                end else begin
                    cnt <= cnt - 1;
                end
            end
            default: state <= idle;
        endcase
    end
end


always @(posedge clk) begin
    clock <= cnt;
end


always @(*) begin
    case (state)
        idle: {red, yellow, green} = 3'b000;
        s1_red: {red, yellow, green} = 3'b100;
        s3_green: {red, yellow, green} = 3'b001;
        s2_yellow: {red, yellow, green} = 3'b010;
