module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

reg [7:0] dividend_abs;
reg [7:0] divisor_abs;
reg [16:0] SR;

reg [7:0] quotient;
reg [3:0] cnt;
reg start_cnt;
reg [8:0] NEG_DIVISOR;


always @(posedge clk) begin
    if (rst) begin
        res_valid <= 0;
        quotient <= 0;
        dividend_abs <= 0;
        divisor_abs <= 0;
        SR <= 0;
        cnt <= 0;
        start_cnt <= 0;
        NEG_DIVISOR <= 0;
    end else begin
        if (opn_valid && !res_valid) begin

            if (sign) begin
                dividend_abs <= dividend[7] ? -dividend : dividend;
                divisor_abs <= divisor[7] ? -divisor : divisor;
            end else begin
                dividend_abs <= dividend;
                divisor_abs <= divisor;
            end

            SR <= {dividend_abs, 1'b0};

            NEG_DIVISOR <= -{1'b0, divisor_abs};
            cnt <= 1;
            start_cnt <= 1;
            res_valid <= 0;
        end

        if (start_cnt) begin
            if (cnt <= 8) begin
                reg [8:0] sub_result;
                sub_result = SR - NEG_DIVISOR;

                if (sub_result[8] == 0) begin
                    SR <= {sub_result[7:0], 1'b0};
                    quotient <= {quotient[6:0], 1'b0};
                end else begin
                    SR <= {sub_result[7:0], 1'b1};
                    quotient <= {quotient[6:0], 1'b1};
                end
                cnt <= cnt + 1;
            end else begin

                res_valid <= 1;
                start_cnt <= 0;
                cnt <= 0;

                if (sign) begin

                    if ((dividend[7] ^ divisor[7])) quotient <= -quotient;

                    if (dividend[7]) begin
                        result <= {dividend_abs, quotient};
                    end else begin
                        result <= {dividend_abs, quotient};
                    end
                end else begin
                    result <= {dividend_abs, quotient};
                end
            end
        end
    end
end

endmodule

