module fixed_point_adder #(parameter Q = 4, N = 8) (
    input [N-1:0] a,
    input [N-1:0] b,
    output [N-1:0] c
);

    reg [N-1:0] res;

    wire sign_a = a[N-1];
    wire sign_b = b[N-1];


    wire [N-1:0] a_abs = sign_a ? (~a + 1) : a;
    wire [N-1:0] b_abs = sign_b ? (~b + 1) : b;

    always @(*) begin
        if (sign_a == sign_b) begin

            res = a_abs + b_abs;
            res[N-1] = sign_a;


            if (res[N-1] != sign_a) begin
                res = {sign_a, {(N-1){1'b1}}};

            end
        end else begin

            if (a_abs > b_abs) begin
                res = a_abs - b_abs;
                res[N-1] = sign_a;
            end else if (b_abs > a_abs) begin
                res = b_abs - a_abs;
                res[N-1] = sign_b;
            end else begin

                res = 0;
            end
        end
    end

    assign c = res;

endmodule

