module fixed_point_subtractor #(
    parameter Q = 4, 
    parameter N = 8  
) (
    input [N-1:0] a, 
    input [N-1:0] b, 
    output [N-1:0] c 
);

    reg [N-1:0] res;
    reg sign_a, sign_b;
    reg [N-1:0] abs_a, abs_b;
    reg [N-1:0] abs_diff;
    reg sign_res;

    always @(*) begin
        sign_a = a[N-1];
        sign_b = b[N-1];

        if (sign_a == sign_b) begin

            res = a - b;
        end else begin

            abs_a = sign_a ? (~a + 1) : a;
            abs_b = sign_b ? (~b + 1) : b;

            if (abs_a > abs_b) begin
                abs_diff = abs_a - abs_b;
                sign_res = sign_a;
            end else if (abs_b > abs_a) begin
                abs_diff = abs_b - abs_a;
                sign_res = ~sign_a;
            end else begin
                abs_diff = 0;
                sign_res = 0;
            end


            res = {sign_res, abs_diff};
        end


        if (res == 0) begin
            res[N-1] = 0;
        end
    end

    assign c = res;

endmodule

