                    b_is_inf <= (b_exponent[7:0] == 8'hff) && (!|b_mantissa);
                    result_is_inf <= (a_is_inf || b_is_inf) && !(a_is_zero || b_is_zero);


                    a_is_zero <= (a_exponent[7:0] == 0) && (!|a_mantissa);
                    b_is_zero <= (b_exponent[7:0] == 0) && (!|b_mantissa);
                    result_is_zero <= (a_is_zero || b_is_zero) && !(a_is_inf || b_is_inf);

                    if (result_is_nan || result_is_inf || result_is_zero) begin

                        if (result_is_nan) begin
                            z <= {a_sign ^ b_sign, 8'hff, 23'h1};
                        end else if (result_is_inf) begin
                            z <= {a_sign ^ b_sign, 8'hff, 23'h0};
                        end else if (result_is_zero) begin
                            z <= {a_sign ^ b_sign, 31'h0};
